L["Show me the highlights"] = "Highlights ansehen"
L["Skip all %d and continue"] = "Alle %d überspringen und fortfahren"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Du kannst jede Funktion später in Menu2 einrichten."
L["Custom Aura tracking on Unitframes"] = "Eigene Aura-Tracker auf Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Erstelle bis zu drei eigene Bereiche auf Spieler-, Ziel-, Fokus- und Bossframes, trage exakte Buff- oder Debuff-SpellIDs ein und verfolge deine eigenen DoTs am Zielframe über eine kuratierte Klassen-Reihe."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Deine MSUF-Frames werden damit zu fokussierten Trackern im WeakAura-Stil – mit Symbolen, Timern, Dauerbalken sowie Färbung, Rand, Leuchten oder Pulsieren des ganzen Frames."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "drei eigene Aura-Tracker pro unterstütztem Unitframe, exakte Zauberlisten und Full-Frame-Effekte"
L["Build a Custom tracker"] = "Eigenen Aura-Tracker bauen"
L["Aura settings in the right place"] = "Aura-Einstellungen am richtigen Ort"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "Einrichtung und individuelle Darstellung findest du jetzt in den passenden Unitframe- und Gruppe/Schlachtzug-Menüs. Darstellung > Auren enthält die erweiterten gemeinsamen Stile."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Konfiguriere jeden Frame direkt an seinem Platz und nutze Auren für gemeinsame Symbolformen, Rahmen, Schatten, Farben und Abstände."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "Aura-Steuerung pro Frame und erweiterte gemeinsame Darstellung unter Darstellung > Auren"
L["Open shared Aura styles"] = "Gemeinsame Aura-Stile öffnen"
L["Adaptive Party and Raid layouts"] = "Adaptive Gruppen- und Raidlayouts"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Gruppe, Schlachtzug und Mythic-Schlachtzug haben adaptive Layouts und Skalierung, Aura-Filter und Blacklists pro Reihe und eine eigene Seite für die Entzauber-Überlagerung bekommen - und du bestimmst pro Gruppenart, ob MSUF oder Blizzard die Frames zeichnet."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Ein Gruppen-Setup begleitet dich von der Fünfergruppe bis in den Schlachtzug, und du entscheidest pro Reihe, welche Auren überhaupt erscheinen dürfen."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "adaptive Gruppenlayouts und Skalierung, Gruppen-Aura-Filter und Blacklists, die Entzauber-Überlagerungsseite und die Anbieter-Steuerung pro Gruppenart"
L["Open Group Layout"] = "Gruppenlayout öffnen"
L["New health values and text formats"] = "Neue Gesundheitswerte und Textformate"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "Gesundheitstext kann gekürzte oder vollständige Werte mit einheitlicherer Formatierung anzeigen, und die neue Anzeige für verlorene Maximalgesundheit markiert reduzierte Maximalwerte auf Einzel- und Gruppenframes."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Du kannst kompakte Lesbarkeit oder exakte Zahlen wählen, ohne dein bestehendes Layout aufzugeben."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "die neuen Gesundheitskürzel, Vollwerte, Textformate und die Anzeige für verlorene Maximalgesundheit"
L["Open HP Text Editor"] = "HP-Text-Editor öffnen"
L["More flexible class resources"] = "Flexiblere Klassenressourcen"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Klassenressourcen bieten losgelöste Layouts, weitere Formen sowie feinere Farben pro Slot und für den Vollzustand."
L["You can move class information where your eyes already are and make important states easier to read."] = "Du kannst Klasseninformationen in deinen Blickbereich verschieben und wichtige Zustände leichter lesbar machen."
L["detached class resources, new shapes and per-state colors"] = "losgelöste Klassenressourcen, neue Formen und zustandsabhängige Farben"
L["Configure Class Resources"] = "Klassenressourcen einrichten"
L["Cast target text"] = "Zauberziel-Text"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Zauberleisten für Ziel, Fokus und Bosse können jetzt mit eigener Textdarstellung anzeigen, wen der aktuelle Zauber trifft."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Du erkennst das Ziel eines wichtigen Zaubers, ohne den Blick von der Zauberleiste abzuwenden."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "Zauberziel-Namen und deren Textdarstellung auf Ziel-, Fokus- und Bossframes"
L["Open Target Cast Bar"] = "Ziel-Zauberleiste öffnen"
L["Back and Forward between pages"] = "Zurück und Vorwärts zwischen Seiten"
L["New Back and Forward arrows in the bottom-left menu bar remember the pages you visit."] = "Neue Zurück- und Vorwärts-Pfeile unten links im Menü merken sich die besuchten Seiten."
L["Jump between recent settings pages without finding them again in navigation or search."] = "Springe zwischen den zuletzt verwendeten Einstellungsseiten, ohne sie erneut in Navigation oder Suche zu finden."
L["Back and Forward page history in the bottom-left menu bar"] = "Zurück-/Vorwärts-Verlauf unten links in der Menüleiste"
L["Try the Back button"] = "Zurück-Button ausprobieren"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Sieh dir zuerst die Release-Highlights im Dashboard an oder überspringe sie, bevor du Aktionen der Ersteinrichtung verwendest."
L["Priority Frames for the units that matter"] = "Prioritätsframes für die Einheiten, die zählen"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Hefte bis zu fünf Gruppenmitglieder von Hand an, oder lass MSUF automatisch die Tanks wählen, und gib ihnen eine eigene Leiste, die sich mitten im Kampf nie umsortiert."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "Die Leute, die du im Blick behalten musst, behalten einen festen Platz auf dem Bildschirm, mit dem Aussehen und dem Click-Casting von Gruppe oder Schlachtzug."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "Prioritätsframes, manuelles und automatisches Anheften und ihre eigene Platzierung"
L["Set up Priority Frames"] = "Prioritätsframes einrichten"
L["One Colors page with click-to-paint"] = "Eine Farbseite mit Klick-zum-Färben"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Alle Farben liegen jetzt auf einer Seite, aufgeteilt in Arbeitsbereiche für Spieler & Ziel, Gruppe & Schlachtzug, Zauberleiste, Auren, Ressource und Klassenressourcen, jeweils mit eigener Live-Vorschau."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Du klickst das Element in der Vorschau an, statt das passende Farbfeld zu suchen, und verwendest jede Farbe aus den zuletzt benutzten oder gespeicherten Paletten erneut."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "die neue Farbseite, Klick-zum-Färben-Vorschauen, Paletten und die neue Farbauswahl"
L["Open the Colors page"] = "Farbseite öffnen"
L["One 0-30 layer scale for everything"] = "Eine 0-30-Ebenenskala für alles"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Texte, Statussymbole, Auren, Rahmen, Balkenkonturen, Gruppenanzeigen und Klassenressourcen ordnen sich alle auf einer gemeinsamen 0-30-Ebenenskala."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Du entscheidest genau, was vor was gezeichnet wird, und die Ebenenübersicht neben jedem Ebenenregler zeigt den ganzen Stapel auf einmal."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "die addonweite 0-30-Ebenenskala und die Ebenenübersicht"
L["MSUF Edit Mode, rebuilt"] = "MSUF-Bearbeitungsmodus, neu gebaut"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "Der Bearbeitungsmodus hat eine andockbare Werkzeugleiste, neu gestaltete Schnellmenüs an jedem Frame und Rückgängig/Wiederholen, das dort genauso funktioniert wie im Menü."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Du verschiebst, skalierst und kopierst Frames direkt auf dem Bildschirm und nimmst jeden Fehlgriff zurück, ohne das Menü wieder zu öffnen."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "die neue Bearbeitungsmodus-Werkzeugleiste, ihre Schnellmenüs und gemeinsames Rückgängig/Wiederholen"
L["Start Edit Mode"] = "Bearbeitungsmodus starten"
L["Spell Indicators on Group Frames"] = "Zaubersymbole auf Gruppenframes"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Verfolge ausgewählte Buffs auf Gruppen- und Schlachtzugsframes als Symbol-, Quadrat-, Balken- oder Zahlenanzeige, mit eigenen Zauberlisten und Eckanzeigen."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Du siehst fehlende oder ablaufende Externals und wichtige Buffs direkt auf den Frames, mit Ablauf-Leuchten am Symbol, Hervorhebung der Lebensleiste und Full-Frame-Effekten."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "Zaubersymbole mit eigenen Aura-Listen, Eckanzeigen und Ablauf-Warnungen"
L["Open Spell Indicators"] = "Zaubersymbole öffnen"
L["Fill Direction for Health and Power"] = "Füllrichtung für Leben und Ressource"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Jeder Unitframe kann Leben und Ressource von links nach rechts, rechts nach links, unten nach oben oder oben nach unten füllen."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "Vertikale und gespiegelte Balkenlayouts werden zur Einstellung pro Frame - das bietet derzeit kein anderes Unitframe-Addon."
L["the per-frame Fill Direction control for Health and Power bars"] = "die Füllrichtung pro Frame für Lebens- und Ressourcenbalken"
L["Choose a Fill Direction"] = "Füllrichtung wählen"
L["Portraits: attached, detached or overlay"] = "Porträts: angeheftet, losgelöst oder Overlay"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "Porträts bleiben am Frame, schweben frei oder liegen als Overlay in der Lebensleiste - mit eigener Größe, Neun-Punkt-Verankerung, Deckkraft und verschiebbarem Zoom."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Rechteckige und Wasserzeichen-Porträts werden möglich, und Relief-Ringe sowie formfolgende Ränder rahmen quadratische, runde, abgerundete und Diamant-Porträts."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "die neuen Porträt-Platzierungen, Relief-Ringe und formfolgende Porträtränder"
L["Open Portrait settings"] = "Porträt-Einstellungen öffnen"
L["Status icon packs"] = "Statussymbol-Pakete"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Rolle, Anführer, Schlachtzugssymbol, Bereitschaftscheck und jedes andere Statussymbol können pro Anzeige zwischen zwölf mitgelieferten Stilen oder eigenen Symbolen wechseln."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Statussymbole passen endlich zu deinem UI-Stil statt immer zur Blizzard-Grafik, und externe Pakete können sich über SharedMedia registrieren."
L["the twelve status icon styles and per-indicator custom icons"] = "die zwölf Statussymbol-Stile und eigene Symbole pro Anzeige"
L["Pick an icon style"] = "Symbolstil wählen"

L["Show navigation icons"] = "Navigationssymbole anzeigen"
