L["Rounded frame texture was changed.\n\nA UI reload is required because this style rebuilds frame masks and protected frame visuals.\n\nReload now?"] = "Die abgerundete Rahmentextur wurde geändert.\n\nEin UI-Reload ist erforderlich, weil dieser Stil Frame-Masken und geschützte Frame-Visuals neu aufbaut.\n\nJetzt neu laden?"
