L["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Dieselbe Einstellung wie auf jeder Unit-Seite > Transparenz. Sie nutzt dieselbe HP-Track-Farbe; aus bedeutet, dass mindestens ein Unitframe aus ist."
L["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Nutze das, wenn HP-Bar-Fade den leeren HP-Bereich verschwinden lässt oder schwarz wirken lässt. Es behält dieselbe HP-Track-Farbe aus Farben."
L["On: HP stays transparent and missing health uses the HP track color. Off: normal background transparency is used."] = "An: HP bleibt transparent und fehlende HP nutzt die HP-Track-Farbe. Aus: normale Hintergrund-Transparenz wird genutzt."
