--- MSUF 5.1 Beta 1
L["Blizzard Aura Layering"] = "Blizzard-Aura-Ebenen"
L["Blizzard renders these icons on MSUF's container. If icons appear behind frames, raise the container strata or frame level."] = "Blizzard rendert diese Symbole im MSUF-Container. Wenn Symbole hinter Frames erscheinen, erhöhe Container-Strata oder Frame-Level."
L["Icon size: %d"] = "Symbolgröße: %d"
L["Buff max: %d"] = "Max. Buffs: %d"
L["Debuff max: %d"] = "Max. Debuffs: %d"
L["Off = MSUF Custom Buffs run too; duplicates can appear."] = "Aus = MSUF Custom Buffs laufen mit; Duplikate möglich."
L["Layering"] = "Ebenen"
L["Container level: +%d"] = "Container-Level: +%d"
L["Enable defensives"] = "Defensives aktivieren"
L["Max defensives"] = "Max. Defensives"
L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Wenn aktiv, gehören Buff-Icons WoW. MSUF-Ausblendkategorien und eigene Buff-Positionen filtern von Blizzard gerenderte Buffs nicht; Himmelszorn oder Erdschild können weiter erscheinen."
L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Wenn aktiv, gehoeren Debuff-Icons WoW. MSUF-Ausblendkategorien und eigene Debuff-Positionen filtern von Blizzard gerenderte Debuffs nicht."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Wenn aktiv, gehoeren Defensiv-Icons WoW. Eigene MSUF-Positionierung und -Darstellung greifen nur, wenn dies aus ist oder der Renderer auf MSUF Custom steht."
L["Checked categories hide MSUF custom buff icons only. Blizzard-rendered buffs bypass this list, so Skyfury or Earth Shield can still appear while Use Blizzard: Buffs is enabled."] = "Markierte Kategorien verbergen nur eigene MSUF-Buff-Icons. Von Blizzard gerenderte Buffs umgehen diese Liste; Himmelszorn oder Erdschild können weiter erscheinen, solange Blizzard verwenden: Buffs aktiv ist."
L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Markierte Kategorien verbergen nur eigene MSUF-Debuff-Icons. Von Blizzard gerenderte Debuffs umgehen diese Liste, solange Use Blizzard: Debuffs aktiv ist."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Blizzard-Rendering ist weiter aktiv, aber diese Gruppe nutzt MSUF Custom, weil ihr Blizzard-verwenden-Schalter aus ist. Andere aktive Blizzard-Auratypen können weiterhin passende Zauber anzeigen, daher können Duplikate entstehen."
L["Turning Use Blizzard: Buffs off makes MSUF Custom Buffs run while Blizzard rendering stays active. Matching buffs can appear twice."] = "Wenn Blizzard verwenden: Buffs aus ist, laufen MSUF Custom Buffs mit, während Blizzard-Rendering aktiv bleibt. Passende Buffs können doppelt erscheinen."
L["MSUF Custom + Blizzard active"] = "MSUF Custom + Blizzard aktiv"

--- MSUF2 rounded-frame search/menu coverage
local MSUF2_ROUNDED_SEARCH_deDE = {
    ["Controls the rounded frame texture style for unit frames, group frames, power bars, and mouseover highlights."] = "Steuert den abgerundeten Frame-Textur-Stil für Unitframes, Gruppenframes, Ressourcenleisten und Mouseover-Hervorhebungen.",
    ["Enable or disable rounded mouseover highlight edges."] = "Aktiviert oder deaktiviert abgerundete Mouseover-Hervorhebungen.",
    ["Enable or disable rounded textures on group frames."] = "Aktiviert oder deaktiviert abgerundete Texturen auf Gruppenframes.",
    ["Enable or disable rounded textures on power bars."] = "Aktiviert oder deaktiviert abgerundete Texturen auf Ressourcenleisten.",
    ["Enable or disable rounded textures on unit frames."] = "Aktiviert oder deaktiviert abgerundete Texturen auf Unitframes.",
    ["Group frames"] = "Gruppenframes",
    ["How do I enable or disable rounded frames?"] = "Wie schalte ich abgerundete Frames ein oder aus?",
    ["Master switch for the rounded frame texture style."] = "Hauptschalter für den abgerundeten Frame-Textur-Stil.",
    ["Mouseover highlights"] = "Mouseover-Hervorhebungen",
    ["Open Global Style > Bars > Rounded Texture. Use the master toggle for all rounded frame textures, or the separate toggles for unit frames, group frames, power bars, and mouseover highlights."] = "Öffne Globaler Stil > Balken > Abgerundete Textur. Nutze den Hauptschalter für alle abgerundeten Frame-Texturen oder die einzelnen Schalter für Unitframes, Gruppenframes, Ressourcenleisten und Mouseover-Hervorhebungen.",
    ["Open this section to enable or disable rounded frame textures and its per-surface toggles."] = "Öffne diesen Abschnitt, um abgerundete Frame-Texturen und die einzelnen Flächen-Schalter ein- oder auszuschalten.",
    ["Opens: Global Style > Bars > Rounded Texture"] = "Oeffnet: Globaler Stil > Bars > Abgerundete Textur",
    ["Power bars"] = "Ressourcenleisten",
    ["Rounded frame texture"] = "Abgerundete Frame-Textur",
    ["Corner rounding"] = "Eckenabrundung",
    ["Rounded Texture"] = "Abgerundete Textur",
}
for k, v in pairs(MSUF2_ROUNDED_SEARCH_deDE) do
