--- MSUF locale coverage fill - visible menu/runtime strings
local MSUF_LOCALE_COVERAGE_deDE = {
    ["!msuf help      - Print this help via chat (from your own character)."] = "!msuf help      - Diese Hilfe per Chat ausgeben (von deinem eigenen Charakter).",
    ["(then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "(dann /reload ODER MSUF Menü > Erweitert > Werksreset)",
    ["/msuf absorb    - Toggle showing total absorb amount in HP text."] = "/msuf absorb    - Anzeige der gesamten Absorptionsmenge im HP-Text umschalten.",
    ["/msuf analytics off|on|status - Toggle Wago Analytics beta telemetry."] = "/msuf analytics off|on|status - Wago-Analytics-Beta-Telemetrie umschalten.",
    ["/msuf fullreset - FULL factory reset (all profiles/settings)."] = "/msuf fullreset - VOLLSTÄNDIGER Werksreset (alle Profile/Einstellungen).",
    ["/msuf gfhoverdebug on|off|status - Debug group-frame hover + tooltip paths."] = "/msuf gfhoverdebug on|off|status - Group-Frame-Hover und Tooltip-Pfade debuggen.",
    ["/msuf help      - Show this help."] = "/msuf help      - Diese Hilfe anzeigen.",
    ["/msuf reset     - Reset all MSUF frame positions and visibility to defaults."] = "/msuf reset     - Alle MSUF-Frame-Positionen und Sichtbarkeit auf Standardwerte zurücksetzen.",
    ["/msufdbgpos     - Toggle position drift debugger (overlay + chat log)."] = "/msufdbgpos     - Positionsdrift-Debugger umschalten (Overlay + Chatlog).",
    ["/rl             - Reload the UI."] = "/rl             - UI neu laden.",
    ["Actions"] = "Aktionen",
    ["Any debuff"] = "Irgendein Debuff",
    ["Any dispel-type debuff"] = "Jeder Bannungs-Debuff",
    ["Arcane Surge"] = "Arkane Woge",
    ["Astral Warden"] = "Astraler Wächter",
    ["Auras 2.0 shared settings, per-unit aura overrides, filters, caps, layout, timer text and reminders"] = "Gemeinsame Auras 2.0-Einstellungen, Aura-Überschreibungen pro Einheit, Filter, Obergrenzen, Layout, Timertext und Erinnerungen",
    ["Auto"] = "Automatisch",
    ["Backdrop"] = "Hintergrund",
    ["Blizzard draws these icons on MSUF's frame container. If icons appear behind frames, adjust the advanced layering controls."] = "Blizzard zeichnet diese Symbole auf dem Frame-Container von MSUF. Wenn Symbole hinter Rahmen angezeigt werden, passen Sie die erweiterten Ebenensteuerungen an.",
    ["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Border / Glow keeps Blizzard icons while allowing MSUF's dispel highlight visuals."] = "Im Blizzard-Modus kann WoW die ausgewählten Auratypen platzieren. Im benutzerdefinierten MSUF-Modus kann MSUF die Größe, das Wachstum, die Position, die Filter und das Styling der Aura steuern. MSUF Dispel Border/Glow behält die Blizzard-Symbole bei und ermöglicht gleichzeitig die visuelle Darstellung der Dispel-Highlights von MSUF.",
    ["CDM + Class Power detected"] = "CDM + Klassenressource erkannt",
    ["CDM not visible - will center on screen"] = "CDM nicht sichtbar – wird auf dem Bildschirm zentriert",
    ["Click to apply. Undo available in popup."] = "Zum Anwenden klicken. Rückgängig im Popup verfügbar.",
    ["Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "Bestätigen bereitet das Zurücksetzen vor; neu laden über /reload oder MSUF Menü > Erweitert > Werksreset.",
    ["Custom:"] = "Benutzerdefiniert:",
    ["Density"] = "Dichte",
    ["Detaches power bar from unit frame"] = "Trennt die Ressourcenleiste vom Unitframe",
    ["Dispellable by me"] = "Von mir entfernbar",
    ["Drag this preview element to adjust the same X/Y offsets used by Edit Mode."] = "Ziehen Sie dieses Vorschauelement, um die gleichen X/Y-Offsets anzupassen, die im Bearbeitungsmodus verwendet werden.",
    ["Edit"] = "Bearbeiten",
    ["For bar backgrounds: Bar Background Tint. White in Dark Mode needs Custom color in Dark Mode; black track? check Preserve HP color."] = "Für Balkenhintergründe: Balken-Hintergrundtönung. Weiß im Dunkelmodus erfordert „Benutzerdefinierte Farbe im Dunkelmodus“; schwarze Spur? „HP-Farbe erhalten“ prüfen.",
    ["Global Style > Fonts controls shared font settings. Unit pages contain per-unit name, health, and power text position and pattern settings."] = "Globaler Stil > Schriftarten steuert gemeinsame Schriftarteinstellungen. Die Einheitenseiten enthalten die Textposition und Mustereinstellungen für den Namen, die Gesundheit und die Ressource pro Einheit.",
    ["Global Style > Fonts has Shared settings plus per-scope font overrides. If Party or Raid uses custom font settings, its Name Shortening can stay enabled even when Shared is off. Select Party/Raid in Fonts or reset the font override."] = "„Globaler Stil“ > „Schriftarten“ verfügt über gemeinsame Einstellungen sowie Überschreibungen von Schriftarten pro Bereich. Wenn Gruppe oder Raid benutzerdefinierte Schriftarteneinstellungen verwenden, kann die Namensverkürzung auch dann aktiviert bleiben, wenn „Geteilt“ deaktiviert ist. Wählen Sie Gruppe/Raid unter Schriftarten aus oder setzen Sie die Schriftartüberschreibung zurück.",
    ["Global absorb styling is in Global Style > Bars > Absorb Display. Group incoming heals are in Group Frames > Health & Text > Heal Prediction."] = "Der globale Absorptionsstil befindet sich unter „Globaler Stil“ > „Balken“ > „Absorptionsanzeige“. Eingehende Gruppenheilungen finden Sie unter Gruppenrahmen > Gesundheit & Text > Eingehende Heilung.",
    ["How do I make missing health white in Dark Mode?"] = "Wie mache ich fehlende Gesundheit im Dunkelmodus weiß?",
    ["Limits"] = "Grenzen",
    ["MSUF Dispel Border / Glow"] = "MSUF-Bannrahmen/-Leuchten",
    ["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from Unit Auras or Group Frames > Buffs & Debuffs."] = "Der MSUF-Bearbeitungsmodus verschiebt Frames und unterstützte Zauberleisten. Die Platzierung der Aura-Symbole steuerst du über Einheitenauren oder Gruppenframes > Buffs & Debuffs.",
    ["MSUF group frames do not use per-player castbars over the health frame. For MSUF castbar positioning, use MSUF Edit Mode and Global Style > Castbar."] = "MSUF-Gruppenframes verwenden keine Zauberleisten pro Spieler über der Lebensleiste. Für die Positionierung der MSUF-Zauberleiste nutzt du den MSUF-Bearbeitungsmodus und Globaler Stil > Zauberleiste.",
    ["Match width: Essential Cooldowns"] = "Breite anpassen: Haupt-Cooldowns",
    ["Most shared colors are in Global Style > Colors. Bar texture and border style controls are in Global Style > Bars."] = "Die meisten freigegebenen Farben finden Sie unter „Globaler Stil“ > „Farben“. Die Steuerelemente für Balkentextur und Rahmenstil befinden sich unter „Globaler Stil“ > „Balken“.",
    ["New character profile"] = "Profil für neue Charaktere",
    ["Not Now"] = "Nicht jetzt",
    ["Okay"] = "OK",
    ["One-click setup for a ready-to-use class bar:"] = "Ein-Klick-Setup für eine gebrauchsfertige Klassenleiste:",
    ["Open Class Resources for combo points, holy power, soul shards, chi, maelstrom, essence, runes, stagger, detached power, and alternative mana."] = "Öffnen Sie Klassenressourcen für Combopunkte, heilige Kraft, Seelensplitter, Chi, Mahlstrom, Essenz, Runen, Staffelung, losgelöste Ressourcenleiste und alternatives Mana.",
    ["Open Class Resources for global class-resource bars. Per-unit detached power options are in the unit page > Power Bar."] = "Öffne Klassenressourcen für globale Klassenressourcenleisten. Die Optionen für abgetrennte Ressourcenleisten pro Einheit findest du auf der Einheitenseite > Ressourcenleiste.",
    ["Open Class Resources. Check Enable, Auto-Hide, class-specific behavior, detached power, and alternative mana settings."] = "Öffne Klassenressourcen. Prüfe Aktivieren, Automatisch ausblenden, klassenspezifisches Verhalten, abgetrennte Ressourcenleiste und alternative Mana-Einstellungen.",
    ["Open Focus Target. Use Frame Basics to enable it; it only appears when Focus is enabled and your focus has a target."] = "Fokusziel öffnen. Verwenden Sie Frame-Grundlagen, um es zu aktivieren. Es erscheint nur, wenn der Fokus aktiviert ist und Ihr Fokus ein Ziel hat.",
    ["Open Gameplay for crosshair, click-cast, focus/target modifier, mouseover, interaction, and targeting options."] = "Öffne Spielverhalten für Fadenkreuz, Click-Cast, Fokus-/Ziel-Modifikator, Mouseover, Interaktion und Zieloptionen.",
    ["Open Global Style > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders."] = "Öffnen Sie „Globaler Stil“ > „Balken“. „Texturen und Farbverlauf“ steuert die Texturen gemeinsam genutzter Balken. Rahmenumriss und Hervorhebungsränder steuern die Ränder.",
    ["Open Global Style > Castbar > GCD Bar. It controls instant-cast GCD display, time text, spell name, and icon."] = "Öffnen Sie Globaler Stil > Zauberleiste > GCD-Leiste. Es steuert die Anzeige von Sofortzaubern, den Zeittext, den Namen des Zaubers und das Symbol.",
    ["Open Global Style > Castbar > Name Shortening for castbar spell name shortening, max length, and reserved space."] = "Öffne Globaler Stil > Zauberleiste > Namensverkürzung für die Verkürzung des Zaubernamens, die maximale Länge und den reservierten Platz.",
    ["Open Global Style > Castbar and use Empowered Casts for Evoker stage color, stage blink, and blink timing."] = "Öffnen Sie „Globaler Stil“ > „Zauberleiste“ und verwenden Sie „Ermächtigte Zauber“ für die Stufenfarbe, das Stufenblinken und das Blink-Timing des Rufers.",
    ["Open Global Style > Castbar for Focus Kick and Interrupt Ready Indicator. Per-unit castbar interrupt toggles are on each unit page."] = "Öffnen Sie Globaler Stil > Zauberleiste für Fokus-Kick und Kick-bereit-Symbol. Auf jeder Einheitenseite befinden sich die Unterbrechungsschalter der Zauberleiste pro Einheit.",
    ["Open Global Style > Colors for class bar colors and unitframe colors. Group health colors are in Group Frames > Health & Text."] = "Öffnen Sie Globaler Stil > Farben für Klassen-Balkenfarben und Unitframe-Farben. Die Farben der Gruppengesundheit finden Sie unter Gruppenrahmen > Gesundheit und Text.",
    ["Open Global Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides."] = "Öffnen Sie „Globaler Stil“ > „Farben“. Balkenfarben und Ressourcenleistenfarben steuern HP-/Ressourcenfarben; Klassen-Balkenfarben steuern Klassenüberschreibungen.",
    ["Open Global Style > Fonts > Name Shortening for unit names. Castbar spell name shortening is in Global Style > Castbar > Name Shortening."] = "Öffnen Sie „Globaler Stil“ > „Schriftarten“ > „Namensverkürzung“ für Einheitennamen. Die Verkürzung des Zaubernamens auf der Zauberleiste erfolgt unter „Globaler Stil“ > „Zauberleiste“ > „Namensverkürzung“.",
    ["Open Global Style > Fonts > Name Shortening. It controls name shortening globally; unit text placement is on each unit page > Text."] = "Öffnen Sie „Globaler Stil“ > „Schriftarten“ > „Namensverkürzung“. Es steuert die Namensverkürzung global; Die Platzierung des Einheitentextes erfolgt auf jeder Einheitenseite > Text.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Play sound on Target/Target Lost."] = "Öffnen Sie Globaler Stil > Verschiedenes > Blizzard-Frames und verwenden Sie Sound bei Ziel/Ziel verloren abspielen.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Show MSUF minimap icon."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ > „Blizzard-Frames“ und verwenden Sie „MSUF-Minimap-Icon anzeigen“.",
    ["Open Global Style > Miscellaneous > Language. Translation coverage can also be checked with the /msuf locale command."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ > „Sprache“. Die Übersetzungsabdeckung kann auch mit dem Befehl /msuf locale überprüft werden.",
    ["Open Global Style > Miscellaneous > Menu behavior for edge snap and related menu behavior."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ > „Menüverhalten“ für den Kantenfang und das zugehörige Menüverhalten.",
    ["Open Global Style > Miscellaneous > Range Fade. It controls target, focus, and boss out-of-range fading; group range fade is in Group Frames > Health & Text."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ > „Reichweiten-Fade“. Es steuert das Ausblenden von Ziel, Fokus und Boss außerhalb der Reichweite. Der Reichweiten-Fade für Gruppen liegt unter Gruppenrahmen > Gesundheit und Text.",
    ["Open Global Style > Miscellaneous > Unitframe tooltips to control mouseover tooltip behavior."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ > „Unitframe-Tooltips“, um das Verhalten der Mouseover-Tooltips zu steuern.",
    ["Open the unit page > Frame Basics and use Force Blizzard frame on."] = "Öffnen Sie die Einheitenseite > Frame-Grundlagen und verwenden Sie Blizzard-Frame erzwingen.",
    ["Open Global Style > Miscellaneous and use the Range Fade section for affected units, alpha, and portrait fading."] = "Öffnen Sie „Globaler Stil“ > „Verschiedenes“ und verwenden Sie den Bereich „Reichweiten-Fade“ für betroffene Einheiten, Alpha und Porträtüberblendung.",
    ["Open Group Frames > Buffs & Debuffs for raid/party aura handling and Aura Utilities. Unit-frame aura filters are in Unit Auras."] = "Öffnen Sie Gruppenrahmen > Buffs und Debuffs für die Aura-Verwaltung von Raid/Gruppe und Aura-Hilfen. Unit-Frame-Aurafilter sind in Einheitenauren enthalten.",
    ["Open Group Frames > Buffs & Debuffs. Use Buffs, custom buffs, and aura filters to prioritize your own HoTs, externals, and healer buffs."] = "Öffnen Sie Gruppenrahmen > Buffs & Debuffs. Verwenden Sie Buffs, benutzerdefinierte Buffs und Aura-Filter, um Ihre eigenen HoTs, Externals und Heiler-Buffs zu priorisieren.",
    ["Open Group Frames > Health & Text > Range Fade. That controls party and raid out-of-range fading."] = "Öffnen Sie Gruppenrahmen > Gesundheit & Text > Reichweiten-Fade. Dadurch wird das Verblassen außerhalb der Reichweite von Gruppen und Schlachtzügen gesteuert.",
    ["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, heal prediction, dispel overlay, debuff stripe, and range fade."] = "Öffnen Sie Gruppenrahmen > Gesundheit und Text. Es steuert Gesundheitsfarben, Balken, Ressourcenleiste, Text, Heilungsvorhersage, Bannungsüberlagerung, Schwächungsstreifen und Reichweitenausblendung.",
    ["Open Group Frames > Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Öffnen Sie Gruppenrahmen > Indikatoren für Statussymbole, Rolle/Anführer/Assistent, Bereitschaftsprüfung, Fokus-Leuchten und andere Gruppenrahmen-Statusindikatoren.",
    ["Open Group Frames > Layout and check the solo/player visibility options. That is where MSUF controls whether party-style frames appear when you are alone."] = "Öffnen Sie Gruppenrahmen > Layout und überprüfen Sie die Sichtbarkeitsoptionen für Solo/Spieler. Hier steuert MSUF, ob Rahmen im Gruppenstil angezeigt werden, wenn Sie alleine sind.",
    ["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Health & Text > Power Bar > Smooth fill."] = "Öffnen Sie Gruppenrahmen > Layout für Weiche Gesundheitsfüllung. Öffnen Sie für Gruppenrahmen-Ressourcenleisten „Gruppenrahmen“ > „Gesundheit und Text“ > „Ressourcenleiste“ > „Weiche Füllung“.",
    ["Open Group Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring."] = "Öffnen Sie Gruppenrahmen > Layout. Überprüfen Sie das Verhalten von Aktivieren/Anzeigen, die Sichtbarkeit von Spieler/Solo, den Layoutmodus, die Frame-Skalierung und die Verankerung.",
    ["Open Group Frames > Layout. General/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Öffnen Sie Gruppenrahmen > Layout. Allgemein/Layout steuert Rahmenbreite, Höhe, Abstand, Spalten und Wachstum; Frame-Skalierung steuert das Skalierungsverhalten.",
    ["Open Group Frames > Layout. The General and Sorting sections control player/self visibility and how player units are ordered in group frames."] = "Öffnen Sie Gruppenrahmen > Layout. Die Abschnitte „Allgemein“ und „Sortieren“ steuern die Sichtbarkeit des Spielers und die Reihenfolge der Spielereinheiten in Gruppenrahmen.",
    ["Open Group Frames > Layout. Use Layout, Frame Scaling, and Anchoring for party/raid position, growth, spacing, size, and anchor behavior."] = "Öffnen Sie Gruppenrahmen > Layout. Verwenden Sie Layout, Frame-Skalierung und Verankerung für die Position, das Wachstum, den Abstand, die Größe und das Ankerverhalten von Gruppe/Raid.",
    ["Open MSUF again with /msuf. If frame positions are broken, use Dashboard > Reset Positions or the profile/reset tools."] = "Öffnen Sie MSUF erneut mit /msuf. Wenn Rahmenpositionen fehlerhaft sind, verwenden Sie Übersicht > Positionen zurücksetzen oder die Profil-/Reset-Werkzeuge.",
    ["Open Modules > Style for optional style modules such as portrait decoration and dropdown styling."] = "Öffnen Sie Module > Stil für optionale Stilmodule wie Porträtdekoration und Dropdown-Stil.",
    ["Open Profiles for active profile, spec auto-switching, import/export strings, legacy imports, and reset options."] = "Öffnen Sie Profile für aktive Profile, automatische Spezialisierungsumschaltung, Import-/Export-Strings, Legacy-Importe und Optionen zum Zurücksetzen.",
    ["Open Profiles. Check active profile, spec profiles, import/export, and legacy imports. Large imports may need a reload."] = "Öffnen Sie Profile. Überprüfen Sie das aktive Profil, die Spezialisierungsprofile, den Import/Export und die Legacy-Importe. Bei großen Importen ist möglicherweise ein Nachladen erforderlich.",
    ["Open Target of Target. Use Frame Basics to enable it, Text for labels, and Anchoring/Edit Mode for placement."] = "Öffnen Sie das Ziel des Ziels. Verwenden Sie Frame-Grundlagen, um es zu aktivieren, Text für Beschriftungen und Verankerung/Bearbeitungsmodus für die Platzierung.",
    ["Open Unit Auras > Caps & Icons. Lower max buffs/debuffs, rows, icon size, and adjust filters."] = "Öffnen Sie Einheitenauren > Limits & Icons. Reduzieren Sie die maximalen Buffs/Debuffs, Zeilen, Symbolgröße und passen Sie die Filter an.",
    ["Open Unit Auras > Text Coloring for timer colors and text sizes. Group aura cooldown style is in Group Frames > Buffs & Debuffs > Cooldown Style."] = "Öffnen Sie Einheitenauren > Textfärbung für Timer-Farben und Textgrößen. Der Abklingstil der Gruppenaura ist unter „Gruppenrahmen“ > „Buffs & Debuffs“ > „Abklingstil“ zu finden.",
    ["Open Unit Auras and use Display plus Caps & Icons for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Öffnen Sie Einheitenauren und verwenden Sie Anzeige plus Limits & Icons für die Platzierung der Unit-Frame-Aura. Buff-/Debuff-Symbole werden als Aura-Layout konfiguriert und nicht durch den MSUF-Bearbeitungsmodus verschoben.",
    ["Open Unit Auras for unit-frame aura icon sizing and filters. For group frames, use Group Frames > Buffs & Debuffs and custom buff/debuff controls."] = "Öffnen Sie Einheitenauren, um die Größe und Filter der Aura-Symbole für den Einheitenrahmen anzuzeigen. Für Gruppenrahmen verwenden Sie Gruppenrahmen > Buffs & Debuffs und benutzerdefinierte Buff-/Debuff-Steuerelemente.",
    ["Open Unit Auras for unit-frame debuff filtering. For party/raid dispels, use Group Frames > Indicators and Group Frames > Buffs & Debuffs."] = "Öffnen Sie Einheitenauren für die Filterung von Debuffs nach Einheitsrahmen. Für Gruppen-/Raid-Dispels verwenden Sie Gruppenrahmen > Indikatoren und Gruppenrahmen > Buffs & Debuffs.",
    ["Open Unit Auras, select Player, enable Custom caps, then set Caps & Icons > Max Buffs to 0. Show Buffs is a shared master toggle, so it is locked outside Shared."] = "Öffne Einheitenauren, wähle Spieler aus, aktiviere „Eigene Limits“ und setze dann „Limits & Icons“ > „Max. Stärkungen“ auf 0. „Buffs anzeigen“ ist ein gemeinsamer Hauptschalter, daher ist er außerhalb von „Geteilt“ gesperrt.",
    ["Open Unit Auras. Check Display, Aura Filters & Sorting, Only Mine, boss aura filters, dispellable filters, and icon caps."] = "Öffne Einheitenauren. Überprüfen Sie die Anzeige, Aura-Filter und -Sortierung, Nur meine, Boss-Aura-Filter, entfernbare Filter und Symbol-Limits.",
    ["Open that unit page and use Frame Basics > Enable. Boss frames also have Boss Layout options."] = "Öffnen Sie diese Einheitenseite und verwenden Sie „Frame-Grundlagen“ > „Aktivieren“. Boss-Rahmen verfügen auch über Boss-Layout-Optionen.",
    ["Open that unit page and use Frame Basics for width, height, and scale. Text size is in Global Style > Fonts or the unit Text section."] = "Öffnen Sie diese Einheitenseite und verwenden Sie Frame-Grundlagen für Breite, Höhe und Skalierung. Die Textgröße ist unter „Globaler Stil“ > „Schriftarten“ oder im Abschnitt „Einheitstext“ angegeben.",
    ["Open the matching unit page and use Load Conditions to control when player, target, focus, boss, or pet frames are shown."] = "Öffnen Sie die Seite der passenden Einheit und verwenden Sie „Ladebedingungen“, um zu steuern, wann Spieler-, Ziel-, Fokus-, Boss- oder Begleiterrahmen angezeigt werden.",
    ["Open the unit page > Castbar to enable that unit's castbar. Shared castbar visuals are in Global Style > Castbar."] = "Öffnen Sie die Einheitenseite > Zauberleiste, um die Zauberleiste dieser Einheit zu aktivieren. Die geteilte Zauberleisten-Darstellung befindet sich unter „Globaler Stil“ > „Zauberleiste“.",
    ["Open the unit page > Status icons. Select Level in Indicator, then use Enabled, Anchor, X/Y Offset, Size, and Layer."] = "Öffnen Sie die Einheitenseite > Statussymbole. Wählen Sie „Stufe“ im Indikator aus und verwenden Sie dann „Aktiviert“, „Anker“, „X/Y-Versatz“, „Größe“ und „Ebene“.",
    ["Open the unit page > Text. Adjust anchors, offsets, font size, spacing, split spacing, and layer."] = "Öffnen Sie die Einheitenseite > Text. Passen Sie Anker, Versätze, Schriftgröße, Abstand, Teilungsabstand und Ebenenreihenfolge an.",
    ["Open the unit page > Transparency for in-combat/out-of-combat alpha. By default the sliders fade the whole frame; Keep text + portrait visible switches them to the selected layer: Bars, HP Bar, or Backdrop. Group frame transparency is in Group Frames > Layout > Transparency."] = "Öffnen Sie die Einheitenseite > Transparenz für In-Combat/out-of-Combat Alpha. Standardmäßig blenden die Schieberegler den gesamten Frame aus; Text und Porträt sichtbar halten schaltet sie auf die ausgewählte Ebene um: Balken, HP-Balken oder Hintergrund. Die Transparenz des Gruppenrahmens finden Sie unter „Gruppenrahmen > Layout > Transparenz“.",
    ["Open the unit page, then use Frame Basics > Smooth fill for the health bar. For that unit's power bar animation, open Power Bar > Smooth fill."] = "Öffnen Sie die Einheitenseite und verwenden Sie dann Frame-Grundlagen > Weiche Füllung für die Gesundheitsleiste. Für die Animation der Ressourcenleiste dieser Einheit öffnen Sie Ressourcenleiste > Weiche Füllung.",
    ["Open the unit page, then use the Portrait section for mode, render type, shape, size, offset, and border."] = "Öffnen Sie die Einheitenseite und verwenden Sie dann den Abschnitt „Porträt“ für Modus, Rendertyp, Form, Größe, Versatz und Rand.",
