    ["Opens: Target of Target > Frame Basics"] = "Öffnet: Ziel des Ziels > Frame-Grundlagen",
    ["Opens: Unit Auras > Aura Filters & Sorting"] = "Öffnet: Einheiten-Auren > Aura-Filter und -Sortierung",
    ["Opens: Unit Auras > Caps & Icons"] = "Öffnet: Einheitenauren > Limits & Icons",
