    ["Opens: Unit Auras > Player > Custom caps > Caps & Icons > Max Buffs"] = "Öffnet: Einheitenauren > Spieler > Eigene Limits > Limits & Icons > Max. Stärkungen",
    ["Opens: Unit Auras > Text Coloring"] = "Öffnet: Einheitenauren > Textfärbung",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "Gruppen-, Raid- und mythische Raid-Gruppenrahmenlayout, Balken, Auren, Indikatoren, Bereichs-Overrides und Positionen",
    ["Position"] = "Position",
    ["Positions class bar ABOVE Essential Cooldowns"] = "Positioniert die Klassenleiste ÜBER den Haupt-Cooldowns",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "Die Vorschau richtet sich nach den aktuellen Sichtbarkeits-, Symbol-, Text- und globalen Farbeinstellungen der Zauberleiste.",
    ["Profile actions"] = "Profilaktionen",
    ["Rows"] = "Reihen",
    ["Select:"] = "Wählen Sie:",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Stellen Sie die Hintergrundtönung der Leiste auf Weiß ein und aktivieren Sie die benutzerdefinierte Farbe im Dunkelmodus. Wenn schwarz, aktivieren Sie „HP-Farbe auf allen Einheitenrahmen beibehalten“.",
    ["Setup Now"] = "Jetzt einrichten",
    ["Slot"] = "Steckplatz",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Bei einigen Layoutänderungen werden Rahmen neu erstellt, während visuelle Änderungen sofort wirksam werden. Schließen Sie bei Bedarf das Menü und öffnen Sie es erneut oder laden Sie es nach großen Änderungen im Profil/import neu.",
    ["Syncs & anchors power bar to class resources"] = "Synchronisiert und verankert die Ressourcenleiste mit den Klassenressourcen",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "Das aktive Profil wird pro Charakter gespeichert. Neue Charaktere starten mit diesem Profil statt mit Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Diese Ebene ist in den Einstellungen deaktiviert und kann nicht in der Vorschau angezeigt werden.",
    ["Type a name here before creating or copying a profile."] = "Geben Sie hier einen Namen ein, bevor Sie ein Profil erstellen oder kopieren.",
    ["Undo"] = "Rückgängig machen",
    ["Unit Frame Preview"] = "Einheitenrahmenvorschau",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Die Statussymbole des Unitframes liegen auf jeder Einheitenseite. Gruppenframe-Indikatoren findest du unter Gruppenframes > Indikatoren.",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Verwenden Sie /msuf, um MSUF2 zu öffnen. Das Dashboard enthält außerdem Reset-, Support-, Profil- und Skalierungstools.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Verwenden Sie „Globaler Stil“ > „Balken“ für Hervorhebungsränder und „Gruppenrahmen“ > „Indikatoren“ für Rollen-, Bedrohungs-, Bannungs-, Zauber-, Ecken- und Schlachtzugsmarkierungsindikatoren.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Verwenden Sie Gruppenrahmen > Layout für Größe und Abstand, Buffs und Debuffs für Aura-Unordnung und Indikatoren für Statussymbole mit fester Position.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Verwenden Sie Gruppenrahmenseiten: Layout für Größe/Wachstum/Sortierung, Gesundheit und Text für Balken/Text, Buffs und Debuffs für Auren und Indikatoren für Statussymbole.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Verwenden Sie den MSUF-Bearbeitungsmodus, um einen einzelnen Einheitsrahmen zu ziehen. Verwenden Sie die Einheitenseite > Verankerung, wenn Sie genaue Ankerziele oder X/Y-Werte benötigen.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Verwende den MSUF-Bearbeitungsmodus, um unterstützte Zauberleisten zu ziehen. Die Optionen für Aktivierung, Symbol und Text pro Einheit findest du auf jeder Einheitenseite; der gemeinsame Stil liegt unter Globaler Stil > Zauberleiste.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Verwenden Sie den MSUF-Bearbeitungsmodus, um den Spielerrahmen zu ziehen. Für genaue Anker- oder X/Y-Werte öffnen Sie anschließend Spieler > Verankerung.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Verwenden Sie die Skalierungsregler der Übersicht für die Menüskalierung oder die UI-Skala. Sie können die Größe des MSUF2-Fensters auch von seiner Ecke aus ändern.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Nutze die Einheitenseite für die Zauberleisten-Schalter pro Einheit und Globaler Stil > Zauberleiste für gemeinsame Texturen, Richtung, GCD, Text und Unterbrechungsoptionen.",
    ["Value:"] = "Wert:",
    ["View"] = "Ansicht",
    ["Welcome to Class Resources!"] = "Willkommen bei den Klassenressourcen!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW blockiert einige geschützte Frame-Änderungen im Kampf. Verlassen Sie den Kampf und wenden Sie dann Layout-, Verankerungs-, Aktivierungs-, Profil- oder geschützte Frame-Änderungen an.",
    ["bottom"] = "unten",
    ["change background color unit frames"] = "Hintergrundfarbe der Unitframes ändern",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "Klassenressourcen-Layout, Verhalten, Stil, automatisches Ausblenden, abgetrennte Ressourcenleiste und alternative Mana-Einstellungen",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "Klicken Sie auf Ebenen, um sie auszublenden. Ziehen Sie Vorschauelemente. Pfeile verschieben die Auswahl",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "Rahmenfarben, Klassen-/NPC-Farben, Ressourcenfarben, Zauberleistenfarben, Aura-Farben und Gameplay-Farbeinstellungen",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "Gameplay-Verbesserungseinstellungen wie Kampftext, Fadenkreuz und Click-Cast-Verhalten",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "globales Zauberleisten-Verhalten, Texturen, GCD, Boss-Zauberleisten- und Unterbrechungsindikator-Einstellungen",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "Sprach-/Menüverhalten, Aktualisierungsgeschwindigkeit, Tooltips, Handhabung von Blizzard-Frames, Minimap-Symbol, Sounds und Reichweiten-Fade-Einstellungen",
    ["none"] = "keine",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "optionale Stil-/Moduleinstellungen wie MSUF-Stil und Dropdown-Stil",
    ["scope disabled"] = "Bereich deaktiviert",
    ["shared"] = "geteilt",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "Gemeinsame Balkentexturen, Farbverläufe, abgerundete Rahmenecken, Absorptionsanzeige, Umrisse, Hervorhebungsränder, Ressourcenglättung und alle Balken-Overrides pro Einheit/Gruppe",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "Gemeinsame Schriftartenfamilie, Textstil, Namens-/Ressourcentextfarbe, Namenskürzung und alle Schrift-Overrides pro Einheit/Gruppe",
    ["the entire active profile"] = "das gesamte aktive Profil",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_deDE) do
    if L[k] == nil or L[k] == k then L[k] = v end
end

L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r Gruppenframes auf Standardwerte zurückgesetzt."
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r HP-Farbe beibehalten nutzt dieselbe HP-Spurfarbe aus Farben, aber einige Leistentexturen können anders aussehen."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Klicke einen Griff zum Auswählen - ziehe eigene Ebenen - Pfeiltasten verschieben die Auswahl; Blizzard ist gesperrt"
L["Copy categories"] = "Kopierkategorien"
L["Copy Selected"] = "Auswahl kopieren"
L["Custom Anchor Frame"] = "Eigener Anker-Frame"
L["Custom anchor target (mouse picker)"] = "Eigenes Ankerziel (Mausauswahl)"
L["Don't show again"] = "Nicht erneut anzeigen"
L["Frame disabled"] = "Frame deaktiviert"
L["Growth Direction"] = "Wachstumsrichtung"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "HP-Farbe beibehalten erhält die HP-Füllfarbe, während Ebenen-Fade aktiv ist, und zeichnet fehlende Gesundheit separat mit derselben HP-Spurfarbe aus Farben.\n\nDas hilft, wenn HP-Bar-Fade den leeren HP-Bereich verschwinden lässt oder schwarz wirken lässt. Einige eigene Texturen können mit dieser Option weiterhin flach, dunkel oder anders aussehen."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "%s auf Standardwerte zurücksetzen?\n\nDies setzt %s für das aktive Profil zurück. Standardwerte werden aus dem aktuellen MSUF-Werksprofil gelesen, sodass zukünftige Standardänderungen automatisch verwendet werden."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "%s auf Standardwerte zurücksetzen?\n\nDies setzt das gesamte aktive Profil '%s' auf die aktuellen MSUF-Werksstandards zurück. Jedes Menü in diesem Profil ist betroffen."
L["Reset Scopes"] = "Bereiche zurücksetzen"

--- MSUF runtime coverage copied into direct locale file
L["                   Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "                   Bestätigen bereitet das Zurücksetzen vor; lade mit /reload neu oder nutze MSUF-Menü > Erweitert > Werkseinstellungen."
L["  !msuf help      - Print this help via chat (from your own character)."] = "  !msuf help      - Diese Hilfe über den Chat ausgeben (von deinem eigenen Charakter)."
L["  (then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "  (danach /reload ODER MSUF-Menü > Erweitert > Werkseinstellungen)"
