L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Wähle den Schwerpunkt der Tour und lerne Navigation, Suche, Autosave, Verlauf und Resets kennen."
