L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "Layout, Text, Indikatoren und Auren."
