L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "Layout, Text und Sichtbarkeit."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Gemeinsames Layout, Text, Indikatoren und Auren."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Framegröße, Wachstum, Sortierung, Skalierung und Anker."
