L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Texturen, Absorbs, Konturen, Hervorhebungen und Ressourcenverhalten."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Darstellung, Text, ermächtigte Zauber und Unterbrechungshinweise."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Frame-, Ressourcen-, Aura-, Klassen-, Text- und Zauberleistenfarben."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Globale Schrift, Textstil, Farben und Namenskürzung."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Auragröße, Abklingzeiten, Stapel, Dauerleisten und Sortierung."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Sprache, Menüverhalten, Start, Tooltips und Blizzard-Frames."
