L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Kampftimer, Zustandsverhalten, Klassenoptionen und Kampf-Fadenkreuz."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Profile, Spezialisierungszuordnung und Import-/Export-Sicherungen."
