L["Use the scope selector for shared, unit and group text; compare readability in Preview."] = "Wähle den Bereich für gemeinsamen, Unit- oder Gruppentext und vergleiche die Lesbarkeit in der Vorschau."
L["Live/Dummy = display only · colored handles = saved positions · scope = shared/unit/group/custom"] = "Live/Dummy = nur Anzeige · farbige Griffe = gespeicherte Positionen · Bereich = gemeinsam/Unit/Gruppe/benutzerdefiniert"
