L["Reset All affects only the current supported page and asks first."] = "Alles zurücksetzen betrifft nur die aktuelle unterstützte Seite und fragt vorher nach."
L["Move whole frames safely"] = "Ganze Frames sicher verschieben"
L["Preview moves inner elements; MSUF Edit Mode places complete frames."] = "Die Vorschau verschiebt innere Elemente; der MSUF-Bearbeitungsmodus platziert vollständige Frames."
L["What you can move"] = "Was du verschieben kannst"
L["Unitframes, supported castbars, group containers, aura groups and the tooltip preview. Boss 1 moves the shared Boss layout."] = "Unitframes, unterstützte Zauberleisten, Gruppencontainer, Auragruppen und die Tooltip-Vorschau. Boss 1 verschiebt das gemeinsame Bosslayout."
L["Drag, select and align"] = "Ziehen, auswählen und ausrichten"
L["Drag to place; click for quick controls. Arrow keys nudge, while Grid and Snap align."] = "Zum Platzieren ziehen, für Schnelloptionen klicken. Pfeiltasten verschieben fein; Raster und Einrasten richten aus."
L["Undo, Cancel All, Exit"] = "Rückgängig, alles abbrechen, beenden"
L["Undo and Redo affect individual moves. Cancel All restores the entry snapshot; Exit keeps your work."] = "Rückgängig und Wiederholen gelten für einzelne Bewegungen. Alles abbrechen stellt den Startzustand wieder her; Beenden behält deine Arbeit."
L["Combat pauses safely"] = "Kampf pausiert sicher"
L["Combat closes the menu and Edit Mode but keeps changes made so far. Reopen MSUF afterward to resume here."] = "Kampf schließt Menü und Bearbeitungsmodus, behält aber bisherige Änderungen. Öffne MSUF danach erneut, um hier fortzufahren."
L["Open MSUF Edit Mode"] = "MSUF-Bearbeitungsmodus öffnen"
L["MSUF Edit Mode is active"] = "MSUF-Bearbeitungsmodus ist aktiv"
L["Ready to place frames"] = "Bereit zum Platzieren der Frames"
L["Use the Edit Mode HUD; Exit keeps the result."] = "Nutze das Bearbeitungsmodus-HUD; Beenden behält das Ergebnis."
L["This opens the in-game placement HUD."] = "Dies öffnet das Platzierungs-HUD im Spiel."
L["Exit and keep changes"] = "Beenden und Änderungen behalten"
L["Open or exit MSUF Edit Mode"] = "MSUF-Bearbeitungsmodus öffnen oder beenden"
L["Moves whole MSUF frames and group containers; exiting keeps changes."] = "Verschiebt ganze MSUF-Frames und Gruppencontainer; Beenden behält Änderungen."
L["Finishing records the tour as complete and changes nothing else."] = "Abschließen markiert die Tour als beendet und ändert sonst nichts."
L["Your guide focus"] = "Dein Tourfokus"
L["%s · %s information"] = "%s · Informationsstil %s"
L["Reviewed sections"] = "Geprüfte Abschnitte"
L["%d discovered options were actively reviewed."] = "%d erkannte Optionen wurden aktiv geprüft."
L["Kept sections"] = "Unverändert gelassene Abschnitte"
