L["Skipped sections"] = "Übersprungene Abschnitte"
L["%d discovered options remain unchanged after warnings."] = "%d erkannte Optionen bleiben nach Warnhinweisen unverändert."
L["and %d more areas"] = "und %d weitere Bereiche"
L["and %d more skipped items"] = "und %d weitere übersprungene Punkte"
L["Skipped areas"] = "Übersprungene Bereiche"
L["Nothing was skipped"] = "Nichts wurde übersprungen"
L["Every guided section was reviewed or deliberately kept as is."] = "Jeder geführte Abschnitt wurde geprüft oder bewusst unverändert gelassen."
L["Guided Setup"] = "Geführte Einrichtung"
L["Your current frames stay active. Follow the complete guided setup, import a profile safely, or keep playing with your existing setup."] = "Deine aktuellen Frames bleiben aktiv. Folge der vollständigen geführten Einrichtung, importiere sicher ein Profil oder spiele mit deiner bestehenden Einrichtung weiter."
L["Your frames are ready now. Follow the complete guided setup, import a profile, or start playing with the defaults."] = "Deine Frames sind bereit. Folge der vollständigen geführten Einrichtung, importiere ein Profil oder spiele mit den Standardwerten los."
