L["~10 min"] = "~10 Min."
L["Start guided setup"] = "Geführte Einrichtung starten"
L["Learn movement, every menu area, interactive previews, auras, and profiles at your own pace."] = "Lerne in deinem Tempo das Verschieben, jeden Menübereich, interaktive Vorschauen, Auren und Profile kennen."
L["GUIDED SETUP IN PROGRESS"] = "GEFÜHRTE EINRICHTUNG LÄUFT"
