L["Move the colored Preview handle; Live Tracked is display-only."] = "Bewege den farbigen Vorschaugriff; Live-Tracking dient nur zur Anzeige."
L["Move the colored Custom handle; Live and dummy previews are display-only."] = "Bewege den farbigen Custom-Griff; Live- und Dummy-Vorschauen dienen nur zur Anzeige."
