L["Adjust this option live, keep its current/default value, or skip it with a clear warning."] = "Passe diese Option direkt an, behalte ihren aktuellen beziehungsweise Standardwert oder überspringe sie mit einem klaren Hinweis."
L["The green arrow points to %s: %s"] = "Der grüne Pfeil zeigt auf %s: %s"
L["The green arrow points to %s; use this action now or keep it untouched and continue."] = "Der grüne Pfeil zeigt auf %s; nutze diese Aktion jetzt oder lasse sie unverändert und fahre fort."
L["The green arrow points to %s; adjust this option live, keep its current/default value, or skip it."] = "Der grüne Pfeil zeigt auf %s; passe diese Option direkt an, behalte ihren aktuellen beziehungsweise Standardwert oder überspringe sie."
L["Click the highlighted preview button to jump directly to this element's settings below."] = "Klicke auf die hervorgehobene Vorschau-Schaltfläche, um direkt zu den Einstellungen dieses Elements darunter zu springen."
L["Keep action"] = "Aktion beibehalten"
L["Section %d / %d · Action %d / %d · %s"] = "Abschnitt %d / %d · Aktion %d / %d · %s"
L["All %d options in this section stay unreviewed: %s."] = "Alle %d Optionen in diesem Abschnitt bleiben ungeprüft: %s."
L["All %d options stay unreviewed: %s."] = "Alle %d Optionen bleiben ungeprüft: %s."
L["Current/default values stay unchanged. Use Confirm skip to continue."] = "Aktuelle beziehungsweise Standardwerte bleiben unverändert. Nutze Überspringen bestätigen, um fortzufahren."
L["Its current/default value stays unchanged. Use Confirm skip to continue."] = "Der aktuelle beziehungsweise Standardwert bleibt unverändert. Nutze Überspringen bestätigen, um fortzufahren."
L["Skip %s?"] = "%s überspringen?"
L["Skip the %s section?"] = "Abschnitt „%s“ überspringen?"
L["This section has no registered option, so only its guidance is skipped."] = "Dieser Abschnitt enthält keine erfasste Option; daher wird nur sein Hinweis übersprungen."
L["Try this action now, or keep it untouched and continue."] = "Probiere diese Aktion jetzt aus oder lasse sie unverändert und fahre fort."
L["You will not review %s."] = "Du prüfst Folgendes nicht: %s."
L["the %s option"] = "die Option %s"
L["Modules and style"] = "Module und Stil"
L["Skipping Modules leaves the optional MSUF Style module and its visual behavior unreviewed."] = "Beim Überspringen der Module bleiben das optionale MSUF-Stilmodul und sein Darstellungsverhalten ungeprüft."
L["This tour belongs to profile %s. You are now editing %s. Restart the tour here or switch back to continue safely."] = "Diese Tour gehört zu Profil %s. Du bearbeitest jetzt %s. Starte die Tour hier neu oder wechsle zurück, um sicher fortzufahren."
L["Active profile changed"] = "Aktives Profil geändert"
L["Tour profile: %s - Active profile: %s"] = "Tourprofil: %s – Aktives Profil: %s"
L["Restart tour"] = "Tour neu starten"
L["Guided setup"] = "Geführte Einrichtung"
L["The action is not run. Use Confirm skip to continue."] = "Die Aktion wird nicht ausgeführt. Nutze Überspringen bestätigen, um fortzufahren."
L["What you will miss: %s"] = "Das überspringst du: %s"
L["Starting setup saved"] = "Startzustand gesichert"
L["You can restore the profile state captured before this guided setup."] = "Du kannst den Profilstand wiederherstellen, der vor dieser geführten Einrichtung gesichert wurde."
L["Restore starting setup"] = "Startzustand wiederherstellen"
L["Confirm restore"] = "Wiederherstellen bestätigen"
L["This replaces the current profile values with the setup starting point. Click again to confirm."] = "Dadurch werden die aktuellen Profilwerte durch den Startzustand der Einrichtung ersetzt. Klicke zur Bestätigung erneut."
L["Starting setup restored"] = "Startzustand wiederhergestellt"
L["The starting profile values are active again. Finish when you are ready."] = "Die ursprünglichen Profilwerte sind wieder aktiv. Schließe ab, wenn du bereit bist."
L["The starting setup could not be restored. Your current values remain active."] = "Der Startzustand konnte nicht wiederhergestellt werden. Deine aktuellen Werte bleiben aktiv."
L["Restores the active profile values captured before guided setup began after a second confirmation."] = "Stellt nach einer zweiten Bestätigung die Werte des aktiven Profils wieder her, die vor Beginn der geführten Einrichtung gesichert wurden."

