L["double-click/settings opens options - right-click actions - arrows nudge"] = "Doppelklick: Einstellungen · Rechtsklick: Aktionen · Pfeile: verschieben"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Ziehen: bewegen · Doppelklick: Einstellungen · Rechtsklick: Aktionen · Strg+Rad: Zoom"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Klick: auswählen · Doppelklick: Einstellungen · Rechtsklick: Aktionen · Strg+Rad: Zoom"
