L["EM_HELP_DRAG"] = "Ziehe einen Mover, um den Frame zu verschieben. Loslassen speichert; X/Y zeigt den aktuellen Versatz."
L["EM_HELP_NUDGE"] = "Pfeiltasten verschieben das aktive Ziel: 1 px; Umschalt 5; Strg 10; Alt nutzt den Rasterabstand."
L["EM_HELP_POPUP"] = "Klicke einen Mover ohne zu ziehen, um Schnelleinstellungen zu öffnen. Zauberleisten- und Aura-Mover öffnen eigene Popups."
L["EM_HELP_SNAP"] = "Raster zeigt den Rasterabstand; klicken schaltet es um, scrollen ändert ihn. Einrasten richtet Mover am Bildschirm und an anderen Movern aus."
L["EM_HELP_OPACITY"] = "Scrolle über HG, um nur die Deckkraft des Bearbeitungsmodus-Hintergrunds zu ändern."
L["EM_HELP_PREVIEW"] = "Vorschau zeigt Platzhalter für Einheiten und Zauberleisten. Auren zeigt Aurasymbole und Mover-Boxen."
