L["EM_HELP_CDM"] = "Abklingzeit schaltet den Cooldown-Manager-Anker um. Mit Anheften wählst du per Strg+Linksklick einen benannten Frame; eigene Anker deaktivieren den Cooldown-Manager-Anker."
L["EM_HELP_COPYTO"] = "Kopieren nach kopiert Frame-Einstellungen und behält Position und Anker des Ziels."
L["EM_HELP_EXIT"] = "Verlassen behält deine Änderungen. Kampf beendet den Bearbeitungsmodus ebenfalls; Escape schließt nur das aktive Popup."
L["EM_HINT_NONE"] = "Mover auswählen. Ziehen verschiebt; Klicken öffnet Schnelleinstellungen."
