L["Click it to switch the value and watch the Live Preview."] = "Klicken Sie darauf, um den Wert zu ändern und die Live-Vorschau anzusehen."
L["Click its mover whenever you want the Width, Height, and Spacing popup."] = "Klicken Sie auf den Mover, wann immer Sie das Popup-Fenster „Breite“, „Höhe“ und „Abstand“ anzeigen möchten."
L["Click the highlighted Party Frames mover for Width, Height, and Spacing."] = "Klicken Sie für Breite, Höhe und Abstand auf den hervorgehobenen Gruppenrahmen-Mover."
L["Click the highlighted Player mover. Width and Height live in that popup."] = "Klicken Sie auf den hervorgehobenen Spieler-Mover. Breite und Höhe finden Sie in diesem Popup."
