L["Copies the complete Aura workspace: visibility, layout, Blizzard filters, Buff/Debuff blacklists, Custom 1-3, their whitelists, Strata, and Full-Frame effects."] = "Kopiert den gesamten Aura-Arbeitsbereich: Sichtbarkeit, Layout, Blizzard-Filter, Buff/Debuff-Blacklists, Benutzerdefiniert 1–3, ihre Whitelists, Strata und Vollrahmen-Effekte."
L["Copies the complete Group Aura configuration, including Buff/Debuff filters, exact and category blacklists, layout, cooldown presentation, Strata, and dispel options."] = "Kopiert die komplette Gruppen-Aura-Konfiguration, einschließlich Buff-/Debuff-Filter, exakte und Kategorie-Blacklists, Layout, Abklingzeitpräsentation, Strata und Bannoptionen."
L["Copies every text slot with its content, size and position, plus this unit's font overrides: font, outline, shadow, text color and name shortening."] = "Kopiert jeden Textslot mit Inhalt, Größe und Position sowie die Schrift-Überschreibungen dieser Einheit: Schriftart, Kontur, Schatten, Textfarbe und Namenskürzung."
L["Copies the frame toggle, fill direction and health coloring, plus this unit's Bars overrides: bar textures, outline, highlight priority, gradient, absorb and heal prediction."] = "Kopiert Frame-Schalter, Füllrichtung und Lebensfärbung sowie die Balken-Überschreibungen dieser Einheit: Balkentexturen, Kontur, Hervorhebungspriorität, Verlauf, Absorption und Heilvorhersage."
