L["While External Defensives is visible and Max is above 0, hides every aura Blizzard classifies as EXTERNAL_DEFENSIVE from the normal Buffs container. If External Defensives is disabled, those auras remain visible in Buffs."] = "Solange „Externe Verteidigung“ sichtbar und „Max“ größer als 0 ist, werden alle von Blizzard als EXTERNAL_DEFENSIVE klassifizierten Auren aus dem normalen Buff-Container ausgeblendet. Ist „Externe Verteidigung“ deaktiviert, bleiben diese Auren in Buffs sichtbar."
