L["MSUF POWER MOVE - Assign each corner or bind a custom spell to the selected slot."] = "MSUF POWER MOVE – Weisen Sie jede Ecke zu oder binden Sie einen benutzerdefinierten Zauber an den ausgewählten Slot."
L["MSUF POWER MOVE - Show incoming enemy casts directly on the Party member they target."] = "MSUF POWER MOVE – Zeigen Sie ankommende gegnerische Zauber direkt auf dem Gruppenmitglied an, auf das sie abzielen."
L["MSUF POWER MOVES - Scan the highlights, then press Continue."] = "MSUF POWER MOVES – Scannen Sie die Hervorhebungen und klicken Sie dann auf „Weiter“."
L["Try \"raid auras\" or \"how do I make text bigger?\""] = "Probiere „Raid-Auren“ oder „Wie mache ich Text größer?“"
L["Skipping leaves Spell Icons unchanged; you can find them later with Menu Search."] = "Beim Überspringen bleiben die Zaubersymbole unverändert; du findest sie später über die Menüsuche."
L["Finish the tour and use Menu Search to find other settings."] = "Schließe die Tour ab und nutze die Menüsuche, um weitere Einstellungen zu finden."
L["MISSION COMPLETE - Press Finish to return to the Dashboard."] = "MISSION ERFÜLLT – Klicke auf „Abschließen“, um zum Dashboard zurückzukehren."
L["Finish setup"] = "Einrichtung abschließen"
L["Find settings with Search"] = "Einstellungen über die Suche finden"
L["Search Menu2 in everyday language to jump to the exact setting. Search only includes controls available in your active modules."] = "Durchsuche Menu2 in Alltagssprache, um direkt zur passenden Einstellung zu springen. Die Suche umfasst nur Steuerelemente deiner aktiven Module."
L["Finish opens the Dashboard, where you can search settings across the active modules."] = "„Abschließen“ öffnet das Dashboard, wo du die Einstellungen aller aktiven Module durchsuchen kannst."
L["Try searches such as 'Party frame width', 'Spell Icons', or 'Class Resources'. Search opens the matching setting in Menu2."] = "Probiere Suchen wie „Gruppenframe-Breite“, „Zaubersymbole“ oder „Klassenressourcen“. Die Suche öffnet die passende Einstellung in Menu2."
L["Finish returns to the Dashboard. Smart Search stays ready for settings and questions."] = "„Abschließen“ bringt dich zurück zum Dashboard. Die Smart-Suche steht weiter für Einstellungen und Fragen bereit."
L["Use the Dashboard for common tasks, or type a setting or full question into Smart Search."] = "Nutze das Dashboard für häufige Aufgaben oder gib eine Einstellung oder eine ganze Frage in die Smart-Suche ein."
L["Anything else? Just ask"] = "Noch etwas? Frag einfach"
