L["No"] = "Nein"
L["No blacklisted spells. Add one above or use a preset."] = "Keine Zauber auf der schwarzen Liste. Fügen Sie oben eine hinzu oder verwenden Sie eine Voreinstellung."
L["No blacklisted spells. Add one from the presets above."] = "Keine Zauber auf der schwarzen Liste. Fügen Sie über die Voreinstellungen oben eine hinzu."
L["No blocked spells. Add one above or use a preset."] = "Keine blockierten Zauber. Fügen Sie oben eine hinzu oder verwenden Sie eine Voreinstellung."
L["No blocked spells. Add one from the presets above."] = "Keine blockierten Zauber. Fügen Sie über die Voreinstellungen oben eine hinzu."
L["No layers match this search."] = "Für diese Suche stimmen keine Ebenen überein."
L["No nameplate cast events are registered while disabled."] = "Im deaktivierten Zustand werden keine Nameplate-Cast-Ereignisse registriert."
L["No public aura category data is loaded."] = "Es werden keine öffentlichen Aura-Kategoriedaten geladen."
L["No spells tracked. Add up to 40 exact SpellIDs."] = "Keine Zauber verfolgt. Fügen Sie bis zu 40 exakte SpellIDs hinzu."
L["Normal"] = "Normal"
L["On previews every enabled spell of every tracked spec, including spells that only draw a frame effect. Off previews only the selected spell."] = "Ein: Vorschau für jeden aktivierten Zauber aller verfolgten Spezialisierungen, auch für Zauber, die nur einen Rahmeneffekt zeichnen. Aus: Vorschau nur für den ausgewählten Zauber."
L["Opacity remains beside the setting when that element supports it."] = "Die Deckkraft bleibt neben der Einstellung, wenn dieses Element sie unterstützt."
L["Open Aura Style"] = "Aura-Stil öffnen"
L["Open Bars"] = "Balken öffnen"
L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Öffnen Sie „Farben“ > „Balkenverlaufsfarben“, um im ausgewählten Balkenbereich separate Gesundheits- und Ressourcenverlaufsfarben anzuzeigen."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Öffnen Sie „Farben“ > „Gruppenrahmenfarben“ für gemeinsame Gruppen-, Raid- und Mythic-Raid-Farben."
L["Open Edit Mode and move Party Frames"] = "Öffnen Sie den Bearbeitungsmodus und verschieben Sie die Gruppenrahmen"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Öffnen Sie Gruppenrahmen > Auren für Buff/Debuff-Filter, Listen, Sichtbarkeit und Layout. Für Text, Abklingzeiten, Stapel und Dauerbalken verwenden Sie „Darstellung“ > „Auren“ und wählen Sie „Gruppe“ oder „Raid“-Bereich."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Öffnen Sie Gruppenrahmen > Layout. Text, Ressourcenleiste und Reichweiten-Fade sind neben „Frame-Grundlagen“ und „Transparenz“ angeordnet. Entfernbar-Farbfläche und Debuff-Streifen befinden sich auf der Seite „Entfernbar-Farbfläche“. Eingehende Heilung liegt unter „Globaler Stil“ > „Balken“ > „Schilde & Absorb“."
L["Open it and choose a different value."] = "Öffnen Sie es und wählen Sie einen anderen Wert."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Öffnen Sie den betroffenen UnitFrame > Auras > Debuffs und aktivieren Sie die native Dispellable-Regel. Für Gruppe/Raid verwenden Sie Gruppenrahmen > Auren > Debuffs."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Öffnen Sie den betroffenen UnitFrame > Auras > Debuffs und verwenden Sie die rahmenspezifische SpellID-Blacklist. Gruppenausschlüsse sind direkt in Gruppenrahmen > Auren > Debuffs verfügbar."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Öffnen Sie den betroffenen UnitFrame > Auras und wählen Sie Buffs oder Debuffs. Überprüfen Sie die rahmenspezifischen Blizzard-Filter, die Blacklist, den Aktivierungsstatus und die Symbolobergrenze. Für Gruppe/Raid verwenden Sie Gruppenrahmen > Auren."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Öffnen Sie den betroffenen UnitFrame > Auras für Sichtbarkeit, Layout, Filter und Blacklists. Verwenden Sie „Darstellung“ > „Auren“, um Abklingzeit, Stapel, Dauerbalken und Symbolstil für den Bereich anzupassen."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Öffnen Sie den Rahmen und erweitern Sie Auras. Buffs und Debuffs enthalten ihre eigenen Blizzard-Filter und Blacklists; Benutzerdefiniert 1–3 enthält eine eigene Whitelist. Es gibt keine separate Registerkarte „Filter“."
L["Open the matching color section below."] = "Öffnen Sie unten den Abschnitt mit den passenden Farben."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "Öffnet das Buff-Styling für diesen Rahmen. Auswahl des Zaubers, Platzierung, Größe, Ebene und Rahmenhervorhebung bleiben für diesen Indikator einzigartig."
L["Opens: Group Frames > Auras"] = "Öffnet: Gruppenrahmen > Auren"
L["Opens: Group Frames > Status & Indicators"] = "Öffnet: Gruppenrahmen > Status und Indikatoren"
L["Original"] = "Original"
L["Out of range"] = "Außerhalb der Reichweite"
L["Outline color"] = "Umrissfarbe"
L["Over-absorb overlay"] = "Over-Absorb-Overlay"
L["PART 1 - Build Player once, then copy the finished setup to the other Unitframes."] = "TEIL 1 – Spieler einmal erstellen, dann das fertige Setup auf die anderen Unitframes kopieren."
L["PART 2 - Build Party once, then copy it to Raid or Mythic Raid."] = "TEIL 2 – Erstellen Sie einmal eine Gruppe und kopieren Sie sie dann in Raid oder Mythic Raid."
L["PART 3 - Shape Class Resources with its interactive preview and cooldown-aware anchoring."] = "TEIL 3 – Gestalten Sie die Klassenressourcen mit ihrer interaktiven Vorschau und abklingzeitbewusster Verankerung."
L["PARTY CORE - Change the new green setting and watch the Party Preview update."] = "GRUPPEN-KERN – Ändern Sie die neue grüne Einstellung und beobachten Sie, wie sich die Gruppenvorschau aktualisiert."
L["PARTY IS THE MASTER - Adjust its frame basics, then copy the finished result to Raid or Mythic Raid."] = "GRUPPE IST DIE VORLAGE – Passen Sie die Frame-Grundlagen an und kopieren Sie das fertige Ergebnis dann in Raid oder Mythic Raid."
L["PLAYER CORE - Change the new green setting and watch the same Player Preview update."] = "SPIELERKERN – Ändern Sie die neue grüne Einstellung und sehen Sie sich das gleiche Spielervorschau-Update an."
L["PLAYER IS THE MASTER - Change the highlighted frame basics; the Live Preview updates immediately."] = "SPIELER IST DIE VORLAGE – Ändern Sie die hervorgehobenen Frame-Grundlagen; Die Live-Vorschau wird sofort aktualisiert."
