L["In combat - cannot move Focus Interrupt Tracker preview."] = "Im Kampf - die Vorschau des Fokus-Unterbrechungstrackers kann nicht verschoben werden."
L["Enable Focus Interrupt Tracker first to use the on-screen preview."] = "Aktiviere zuerst den Fokus-Unterbrechungstracker, um die Bildschirmvorschau zu nutzen."
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Benutzerdefiniert 1–3 werden immer pro Frame gespeichert. Hier ändern sich lediglich der Symbolstil und die Vollrahmen-Effekte"
L["Disabled or whitelist empty"] = "Deaktiviert oder Whitelist leer"
L["Enter text"] = "Text bei Kampfbeginn"
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Folgt der globalen Farbgebung von Unitframe. Das Farbfeld zeigt eine Vorschau der aktuellen globalen Balkenfarbe an."
L["Frames"] = "Rahmen"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Vererbt: Dieser Bereich folgt dem Shared-Aura-Stil. Aktivieren Sie den benutzerdefinierten Aura-Stil nur, wenn dieser Bereich andere Text-, Wisch-, Rahmen- oder Timereinstellungen benötigt."
L["Leave text"] = "Text bei Kampfende"
L["Live "] = "Live"
L["Live preview is unavailable for this container. Sample mode remains available."] = "Für diesen Container ist keine Live-Vorschau verfügbar. Der Sample-Modus bleibt verfügbar."
L["Live preview updates after combat. Sample mode remains available."] = "Live-Vorschau-Updates nach dem Kampf. Der Sample-Modus bleibt verfügbar."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Pinnen Sie manuell die Teamkollegen an, die Sie zur Überwachung oder zum Click-Casting sichtbar halten möchten. Prioritätsframes entscheiden nicht darüber, wer Voraussicht oder Schwarzmacht erhalten soll. Konfigurieren Sie Gruppenrahmen > Auren > Zauberindikatoren, wenn Sie möchten, dass geerbte Prioritätsrahmen Voraussicht, Schwarzmacht, Verändernde Sande, Sengende Schuppen oder andere konfigurierte Effekte anzeigen."
L["Mouseover highlight"] = "Mouseover-Highlight"
L["Native · "] = "Nativ ·"
L["No live "] = "Kein Live-"
L["No live member"] = "Kein Live-Mitglied"
L["No matching aura active"] = "Keine passende Aura aktiv"
L["OFF"] = "AUS"
L["ON"] = "EIN"
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Öffnen Sie Gruppenrahmen > Priorität > Platzierung. Befestigen Sie den Streifen rechts, links, oben oder unten am aktiven Gruppen-/Raid-Container oder wählen Sie die freie Position und verwenden Sie den eigenen Mover der Prioritätsframes im Bearbeitungsmodus. Die gleiche Seite steuert Wachstum, Abstand, Anheftabstand und Ausrichtungsversatz."
L["Options"] = "Optionen"
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Override aktiv: Dieser Bereich behält seinen eigenen Aura-Stil. Gemeinsame Stiländerungen ersetzen ihn erst, wenn die Überschreibung zurückgesetzt wird."
L["Rested"] = "Ausgeruht"
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Der gemeinsame Aura-Stil ist die Basis für die Aura-Text-, Wisch-, Rahmen- und Timer-Einstellungen für Einheitsrahmen. Gruppe und Raid sind Gruppenrahmen-Bereiche mit eigenen Einstellungen."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Texturen werden gemeinsam genutzt, mit Ausnahme von Gruppen-/Raid-Gruppenrahmen-Überschreibungen. Farbverläufe können pro Einheit oder Gruppenbereich angepasst werden."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Dieser Gruppenbereich kann benutzerdefinierte Texturen und Farbverläufe verwenden. Raid gilt auch für Mythic Raid."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Dieser Bereich kann benutzerdefinierte Farbverläufe und Balkeneinstellungen verwenden. Texturen folgen weiterhin Shared."
