L["Art for this frame's power bar, detached or not. Leave on the global option to follow the shared Bars power texture."] = "Grafik für die Ressourcenleiste dieses Rahmens, ob abgetrennt oder nicht. Auf der globalen Option belassen, um der gemeinsamen Ressourcentextur aus den Balken-Einstellungen zu folgen."
