L["Reset all frame positions and visibility to the defaults."] = "Setzt alle Frame-Positionen und die Sichtbarkeit auf die Standardwerte zurück."
L["Reset every setting in the active profile back to the defaults."] = "Setzt jede Einstellung im aktiven Profil auf die Standardwerte zurück."
L["Delete every MSUF profile and setting on this account."] = "Löscht alle MSUF-Profile und Einstellungen dieses Accounts."
L["Turn the Wago Analytics beta telemetry on or off."] = "Schaltet die Wago-Analytics-Beta-Telemetrie ein oder aus."
L["Debug the group-frame hover and tooltip paths."] = "Debuggt die Hover- und Tooltip-Pfade der Gruppenframes."
L["Print the keyboard-capture frames for movement-lock diagnosis."] = "Gibt die Tastatur-abfangenden Frames zur Diagnose blockierter Bewegung aus."
L["Toggle MSUF Edit Mode. Add a unit such as player or target to open it there."] = "Schaltet den MSUF-Bearbeitungsmodus um. Gib eine Einheit wie player oder target an, um dort zu starten."
L["Leave MSUF Edit Mode."] = "Beendet den MSUF-Bearbeitungsmodus."
L["Search the options menu and open the matching settings."] = "Durchsucht das Optionsmenü und öffnet die passenden Einstellungen."
L["Start or resume the guided setup."] = "Startet die geführte Einrichtung oder setzt sie fort."
L["Report how much of the current language is translated."] = "Meldet, wie viel der aktuellen Sprache übersetzt ist."
L["Fake an available update to test the version-check popup."] = "Simuliert ein verfügbares Update, um das Versions-Popup zu testen."
L["Replay the first-start flow or the upgrade highlights."] = "Spielt den Erststart-Ablauf oder die Upgrade-Highlights erneut ab."
L["Profile which events drive the group frames in combat."] = "Misst, welche Ereignisse die Gruppenframes im Kampf antreiben."
L["Dump the aura frame levels for a layering bug report."] = "Gibt die Frame-Ebenen der Auren für einen Layering-Fehlerbericht aus."
L["Check the options menu for structural problems."] = "Prüft das Optionsmenü auf strukturelle Probleme."
L["Toggle the position drift debugger."] = "Schaltet den Positionsdrift-Debugger um."
