L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Verwendung: /msuf load <name>. Gib /msuf profile ein, um sie aufzulisten."
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' passt auf mehrere Profile. Gib den vollen Namen ein."
