L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r Wiederhole |cffffff00/msuf delete %s|r, um dieses Profil endgültig zu löschen."
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r Im Kampf kann kein Profil zurückgesetzt werden."
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r Das setzt jede Einstellung im Profil '%s' zurück, nicht nur die Positionen."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r Gib |cffffff00/msuf default confirm|r ein, um fortzufahren."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r Gib zuerst |cffffff00/msuf default|r ein und bestätige dann."
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r Unbekannter Frame '%s'. Versuche player, target, focus, pet, boss oder priority."
