--- Castbar filtering & feedback tooltips (6.0)
L["Keeps crafting and gathering casts off every castbar.\n\nThe profession flag is never a protected value, so this filter also holds for units whose spell data is restricted in PvP."] = "Hält Handwerks- und Sammelzauber von jeder Zauberleiste fern.\n\nDas Berufs-Flag ist nie ein geschützter Wert, daher greift dieser Filter auch bei Einheiten, deren Zauberdaten im PvP eingeschränkt sind."
L["Appends the delay a cast has accumulated to the spell name, for example \"Fireball +0.4\".\n\nThe delay is read once per cast from the same event that starts the bar."] = "Hängt die aufgelaufene Verzögerung eines Zaubers an den Zaubernamen an, zum Beispiel \"Feuerball +0.4\".\n\nDie Verzögerung wird einmal pro Zauber aus demselben Event gelesen, das die Leiste startet."

--- Number abbreviation (6.0)
L["Number abbreviation"] = "Zahlenabkürzung"
L["Game default"] = "Spielstandard"
L["Compact"] = "Kompakt"
L["Compact keeps 12.3K / 1.23M on every client language. Game default follows the client, which adds spaces or different letters on some locales."] = "Kompakt behält 12.3K / 1.23M in jeder Client-Sprache. Spielstandard folgt dem Client, der je nach Sprache Leerzeichen oder andere Buchstaben einfügt."

--- Group class-colored health note (6.0)
L["Class-colored health uses one color per class. Open Colors > Class Colors to change them."] = "Klassenfarbige Lebensbalken nutzen eine Farbe pro Klasse. Öffne Farben > Klassenfarben, um sie zu ändern."

--- Group resource bar color list (6.0)
L["One color per resource type, shared with every frame."] = "Eine Farbe pro Ressourcentyp, geteilt mit allen Frames."

--- Dispel overlay preview toggle (6.0)
L["Preview overlay"] = "Overlay-Vorschau"
L["Paints a stand-in tint so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Zeichnet eine Platzhalter-Färbung, damit das Overlay ohne echten dispellbaren Debuff beurteilt werden kann. Schaltet sich beim Schließen dieser Seite selbst ab."

--- Dispel-type symbol indicator (6.0)
L["Dispel Symbol"] = "Dispel-Symbol"
L["UnitFrame Dispel Symbol"] = "UnitFrame Dispel-Symbol"
L["Symbol & Placement"] = "Symbol & Platzierung"
L["Symbol detects"] = "Symbol erkennt"
L["Preview symbol"] = "Symbol-Vorschau"
L["Preview symbol (drag to place)"] = "Symbol-Vorschau (zum Platzieren ziehen)"
L["Shows stand-in symbols so placement can be judged without a real debuff, and lets you drag them into position. Turns itself off when this page closes."] = "Zeigt Platzhalter-Symbole, damit die Platzierung ohne echten Debuff beurteilt werden kann, und lässt sie an die gewünschte Stelle ziehen. Schaltet sich beim Schließen dieser Seite selbst ab."
L["Group frame scopes use Group Frames > Dispel Symbol."] = "Gruppenrahmen-Bereiche nutzen Gruppenrahmen > Dispel-Symbol."

--- Spieler-Defensivbuffs (6.0)
L["Custom 1-3, player Defensive Buffs, and Dots on target are stored per frame. Icon styling and Full-Frame effects here only change %s."] = "Custom 1-3, Spieler-Defensivbuffs und DoTs auf dem Ziel werden pro Frame gespeichert. Icon-Stil und Vollrahmen-Effekte ändern hier nur %s."
L["No custom buffs added."] = "Keine eigenen Buffs hinzugefügt."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 use whitelists, player Defensive Buffs uses its class list plus custom IDs, and Dots on target uses its curated DoT list."] = "Öffne den Frame und klappe Auren aus. Buffs und Debuffs haben eigene Blizzard-Filter und Blacklists; Custom 1-3 verwenden Whitelists, Spieler-Defensivbuffs die Klassenliste plus eigene IDs und DoTs auf dem Ziel die kuratierte DoT-Liste."
L["Source: player buffs · "] = "Quelle: Spieler-Buffs · "

--- Vorschau-Auswahlleiste (6.0)
L["Animate"] = "Animieren"
L["Lock zoom"] = "Zoom sperren"
L["Locked: the preview keeps this zoom and position when you toggle layers."] = "Gesperrt: Die Vorschau behält diesen Zoom und diese Position, wenn du Ebenen umschaltest."
L["Unlocked: the preview refits itself whenever the frame footprint changes."] = "Entsperrt: Die Vorschau passt sich neu ein, sobald sich die Größe des Frames ändert."
L["No element selected"] = "Kein Element ausgewählt"
L["Open settings"] = "Einstellungen öffnen"
L["Reset offset"] = "Versatz zurücksetzen"
L["Exact offset"] = "Exakter Versatz"
L["Preview element"] = "Vorschau-Element"
L["Jumps to the options section that owns the selected preview element."] = "Springt zum Einstellungsbereich, der das gewählte Vorschau-Element besitzt."
L["Puts the selected element back to its default X/Y offset."] = "Setzt das gewählte Element auf seinen Standard-Versatz X/Y zurück."
L["Type an exact offset and press Enter. Arrow keys and dragging write the same setting."] = "Exakten Versatz eingeben und Enter drücken. Pfeiltasten und Ziehen schreiben dieselbe Einstellung."
L["Lists every element the preview placed, including those hidden behind another handle. Tab and Shift+Tab step through the same list."] = "Listet jedes Element auf, das die Vorschau platziert hat - auch solche, die hinter einem anderen Griff liegen. Tab und Umschalt+Tab gehen dieselbe Liste durch."
L["drag to move - Tab picks the next element - ? lists every control"] = "Ziehen zum Verschieben - Tab wählt das nächste Element - ? zeigt alle Steuerungen"
