--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Immer ausgeblendet"
L["Blizzard Raid Manager"] = "Blizzard-Schlachtzugsmanager"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "Blizzards Reiter am linken Bildschirmrand mit Bereitschaftsabfrage, Schlachtzugssymbolen und Rollenfiltern. Es gibt nur dieses eine gemeinsame Fenster, daher gilt die Einstellung für Gruppe, Raid und mythischen Raid gleichermaßen."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Blendet den Schlachtzugsmanager aus, bis die Maus ihn berührt. Bereitschaftsabfrage, Schlachtzugssymbole und Rollenfilter bleiben erreichbar, und ein ausgeklapptes Fenster bleibt sichtbar, bis du es wieder einklappst."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Hält den Schlachtzugsmanager dauerhaft unsichtbar und klickdurchlässig. Stelle wieder um, um seine Schaltflächen zu erreichen."
L["Show on mouseover"] = "Bei Mouseover anzeigen"
L["Automatic"] = "Automatisch"
L["Always visible"] = "Immer sichtbar"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Blendet den Schlachtzugsmanager aus, solange MSUF die aktiven Gruppenrahmen stellt, und überlässt ihn sonst WoW. So hat sich MSUF schon immer verhalten."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Hält den Schlachtzugsmanager auch bei aktiven MSUF-Gruppenrahmen erreichbar. Nimm das, wenn du seine Bereitschaftsabfrage, Schlachtzugssymbole und Rollenfilter weiter nutzen willst."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Gemeinsam für Gruppe, Raid und mythischen Raid. Automatisch hält den Reiter ausgeblendet, solange MSUF die Gruppenrahmen stellt."

--- Zustimmung zur Verankerung am Cooldown Manager
L["MSUF detected %s."] = "MSUF hat %s erkannt."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Soll MSUF das globale Unitframe-Layout am Essential Cooldown Manager verankern?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Es wird nichts verschoben, bis du im nächsten Schritt erneut bestätigst. Du kannst dies später im MSUF-Bearbeitungsmodus ändern."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Es wird nichts verschoben, bis du im nächsten Schritt erneut bestätigst. Wenn du jetzt Unabhängig lassen wählst, kannst du die CDM-Verankerung jederzeit im MSUF-Bearbeitungsmodus oder im MSUF-Menü unter Einheit > Verankerung einschalten."
L["Second confirmation for %s."] = "Zweite Bestätigung für %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF verankert das globale Unitframe-Layout jetzt am Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Bestätige nur, wenn sich das gesamte Unitframe-Layout zusammen mit deinen Cooldowns bewegen soll."
L["Confirm anchoring"] = "Verankerung bestätigen"
L["Continue"] = "Weiter"
L["Keep independent"] = "Unabhängig lassen"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s erkannt: Der globale Anker folgt dem Essential Cooldown Manager. Mit „Abklingzeit“ im MSUF-Bearbeitungsmodus kannst du dies ausschalten."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s erkannt: Die Cooldown-Manager-Verankerung ist aus. Mit „Abklingzeit“ im MSUF-Bearbeitungsmodus kannst du sie einschalten."
L["Cooldown Manager anchoring (%s)"] = "Cooldown-Manager-Verankerung (%s)"
L["Global anchor (%s Anchor)"] = "Globaler Anker (%s-Anker)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Blendet alle vier Außenkanten weich aus; 0 % behält die Originaltextur bei."
L["Use EllesmereUI Unlock Mode for MSUF"] = "EllesmereUI Unlock Mode für MSUF verwenden"
L["EllesmereUI Unlock Mode"] = "EllesmereUI Unlock Mode"
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "An (Standard): MSUF-Frames erscheinen im EllesmereUI Unlock Mode. Schalte dies aus, um den eigenen MSUF-Bearbeitungsmodus zu verwenden. Die MSUF-Profilpositionen bleiben maßgeblich."
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Dieser Schalter wird nur angezeigt, solange EllesmereUI geladen ist. Nach dem Ausschalten verwendet MSUF sofort wieder den eigenen Bearbeitungsmodus."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 zeigt die eingestellte Aura-Pixelgröße."
L["Aura Options"] = "Aura-Optionen"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "Aura-Optionen und Aura-Stil gehören zu diesem UnitFrame. Globale Symbol-Darstellung: Darstellung > Aura-Stil."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "Unterhalb dieses Werts kann die verbleibende Zeit mit einer Nachkommastelle angezeigt werden. 0 bedeutet nur ganze Sekunden."
L["Buff Appearance"] = "Buff-Darstellung"
L["Debuff Appearance"] = "Debuff-Darstellung"
L["Global Aura Appearance: Buffs"] = "Globale Aura-Darstellung: Buffs"
L["Global Aura Appearance: Debuffs"] = "Globale Aura-Darstellung: Debuffs"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Timerfarben werden von Live-Einheiten-/Gruppenauren und allen Vorschauen gemeinsam verwendet. Symbolrahmen- und Schattenfarben befinden sich unter Darstellung > Auren und sind nach Aura-Typ getrennt."
L["Click to open the setting that enables this layer."] = "Klicke, um die Einstellung zu öffnen, die diese Ebene aktiviert."
L["Controls native Aura tooltips for Spell Icons only."] = "Steuert die nativen Aura-Tooltips ausschließlich für Zaubersymbole."
L["Cooldown text format"] = "Format des Abklingzeit-Texts"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Kopiert die Darstellung von Buffs, Schwächungen, externen Defensiven und Zaubersymbolen, einschließlich Symbol-Zoom, Text, Wischeffekt, Dauerbalken und Sortierung. Aura-Optionen, verfolgte Zaubersymbole und das globale Darstellungs-Thema bleiben unverändert."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Kopiert Sichtbarkeit, Layout, Filter, exakte und kategoriebasierte schwarze Listen, Ebene und Entfernen-Optionen der Gruppen-Auren. Aura-Stil und das globale Darstellungs-Thema bleiben unverändert."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Kopiert Aura-Sichtbarkeit, Layout, Filter, schwarze Listen, benutzerdefinierte Auren und verfolgte Zauber dieses UnitFrames. Aura-Stil und das globale Darstellungs-Thema bleiben unverändert."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Kopiert die Darstellung von Buffs, Schwächungen, benutzerdefinierten Auren, Spieler-Defensiven und DoTs auf dem Ziel dieses UnitFrames, einschließlich Text, Wischeffekt, Symbol-Zoom, Dauerbalken, Pandemie und Vollrahmen-Effekten. Aura-Optionen und das globale Darstellungs-Thema bleiben unverändert."
L["Drag background (%dx)"] = "Hintergrund ziehen (%dx)"
L["Drag to move. Arrow keys nudge."] = "Zum Verschieben ziehen. Pfeiltasten für Feinschritte."
L["EllesmereUI"] = "EllesmereUI"
L["Exact X coordinate"] = "Exakte X-Koordinate"
L["Exact Y coordinate"] = "Exakte Y-Koordinate"
L["Fit shows the complete aura layout."] = "Einpassen zeigt das vollständige Aura-Layout."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Globales Darstellungs-Thema, nur nach Aura-Typ auswählbar. Layout, Filter, Timer, Text und Effekte bleiben im jeweiligen UnitFrame oder GroupFrame bereichsabhängig."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "Der individuelle Stil wird hier bearbeitet. Gemeinsames Symbol-Thema: Darstellung > Aura-Stil."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "Layout, Filter, Listen und jeder container-spezifische Stil liegen im jeweiligen Frame. Darstellung > Aura-Stil verwaltet nur das globale Symbol-Thema."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Gemessen von der Mitte des in der Vorschau gezeigten Frames. Positive Werte verschieben nach rechts. Pfeiltasten und Ziehen aktualisieren dieselbe Position."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Gemessen von der Mitte des in der Vorschau gezeigten Frames. Positive Werte verschieben nach oben. Pfeiltasten und Ziehen aktualisieren dieselbe Position."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Öffne den Frame und klappe Auren auf. Buffs und Schwächungen besitzen eigenes Layout, eigene Filter, schwarze Listen und einen eigenen Stil; Benutzerdefiniert 1-3, Defensive Buffs und DoTs auf dem Ziel zeigen die zu ihrem Inhalt passenden Optionen."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Öffnet das globale Aura-Symbol-Thema: Rahmen, Schatten, Farben, Spurenabstand und native Waffenverzauberungen des Spielers. Der individuelle Stil dieses GroupFrames bleibt hier."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "LEISTUNGSWARNUNG (12.1): Blizzard kann für jeden sichtbaren Aura-Button in jedem gerenderten Bild ein OnUpdate ausführen, solange die Aura ein berechnetes Pandemie-Fenster besitzt, und nicht nur während die Warnung angezeigt wird. Aktiviere dies nur, wenn du diese möglicherweise hohen Kosten im Kampf in Kauf nimmst."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Färbt die aktiven GroupFrames mit einer Platzhalter-Tönung, damit sich das Overlay ohne echte entfernbare Schwächung beurteilen lässt. Schaltet sich beim Schließen dieser Seite selbst ab."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Färbt das aktive UnitFrame mit einer Platzhalter-Tönung, damit sich das Overlay ohne echte entfernbare Schwächung beurteilen lässt. Schaltet sich beim Schließen dieser Seite selbst ab."
L["Position is controlled by the colored aura handle in Preview."] = "Die Position wird über den farbigen Aura-Griff in der Vorschau gesteuert."
L["Preview position"] = "Vorschau-Position"
L["Runtime Preview"] = "Laufzeit-Vorschau"
L["Runtime Preview: live GroupFrames"] = "Laufzeit-Vorschau: aktive GroupFrames"
L["Runtime Preview: live UnitFrame"] = "Laufzeit-Vorschau: aktives UnitFrame"
L["Runtime Preview: live UnitFrame (drag)"] = "Laufzeit-Vorschau: aktives UnitFrame (ziehen)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Form, Rahmen und Schatten: Darstellung > Aura-Stil > Buffs. Alle Optionen hier bleiben Gruppen-bereichsabhängig."
L["Shared Aura Style"] = "Gemeinsamer Aura-Stil"
L["Shared Aura Style: Buffs"] = "Gemeinsamer Aura-Stil: Buffs"
L["Shared Aura Style: Debuffs"] = "Gemeinsamer Aura-Stil: Schwächungen"
L["Shared Preview - "] = "Gemeinsame Vorschau - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Zeigt Platzhalter-Symbole auf dem aktiven UnitFrame und lässt dich diese ohne echte Schwächung an ihre Position ziehen. Schaltet sich beim Schließen dieser Seite selbst ab."
L["Spell Icon Style"] = "Zaubersymbol-Stil"
L["Spell Icon tooltip"] = "Zaubersymbol-Tooltip"
L["Swipe Direction"] = "Wischrichtung"
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Mit - / + oder Strg + Mausrad zoomen."
L["Use the colored Texture handle in Preview for exact placement."] = "Verwende den farbigen Textur-Griff in der Vorschau für die genaue Platzierung."
L["Zoom changes only this preview, not your Aura settings."] = "Der Zoom ändert nur diese Vorschau, nicht deine Aura-Einstellungen."

