L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Fügt Blizzards temporäre Waffenverzauberungs-Buttons zum Buff-Container des Spielers hinzu. Dies ist eine gemeinsame Einstellung und nutzt den nativen Aura-Ablauf ohne MSUF-Ticker oder OnUpdate."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Fügt eine exakte schädliche Aura-ID hinzu, die in der kuratierten Liste fehlt. Die Aura bleibt auf dein aktuelles Ziel und deine eigene Aura-Quelle beschränkt."
L["Adds one exact buff to this frame's blacklist."] = "Fügt genau einen Buff zur schwarzen Liste dieses Frames hinzu."
L["Adds one exact buff to this group's blacklist."] = "Fügt genau einen Buff zur schwarzen Liste dieser Gruppe hinzu."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Fügt genau eine schädliche Aura zur schwarzen Liste von Ziel, Fokus oder Boss hinzu. Blizzard wendet beliebige SpellID-Filter nur an, solange die Einheit nicht unterstützbar ist."
L["All Buffs"] = "Alle Buffs"
L["All Debuffs"] = "Alle Schwächungen"
L["All roles"] = "Alle Rollen"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "Schließt Auren ohne Dauer immer aus, selbst wenn die Blizzard-Token-Filter deaktiviert sind."
L["Always excludes auras without a duration."] = "Schließt Auren ohne Dauer immer aus."
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "Schließt Auren ohne Dauer immer aus. Bleibt aktiv, wenn die Token-Filter deaktiviert sind."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "Schließt Auren ohne Dauer immer aus. Diese native Regel hat Vorrang vor SpellID-Schwarzlisten und -Weißlisten."
L["Anchor To Class Resource"] = "An Klassenressource anheften"
L["Any Dispel Type"] = "Beliebige Bannart"
