L["Applicable by Me (Raid)"] = "Von mir anwendbar (Schlachtzug)"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "Gilt für jedes UnitFrame- und GroupFrame-Symbol dieses Aura-Typs. Zaubersymbole verwenden die Buff-Darstellung."
