L["Blocks every aura in the selected curated MSUF set."] = "Blockiert jede Aura im ausgewählten kuratierten MSUF-Satz."
L["Blocks only the selected aura from the curated set."] = "Blockiert nur die ausgewählte Aura aus dem kuratierten Satz."
L["Cancelable Player"] = "Abbrechbar (Spieler)"
L["Castbar Border"] = "Zauberleisten-Rahmen"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Ändert nur die abgetrennte Spieler-Ressourcenleiste. Die Klassenressourcen-Form links ändert nur Klassenressourcen."
L["Class Resource Preview"] = "Klassenressourcen-Vorschau"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "Klassenressource und Spielerressource folgen vorhandenen Frames. Benutzerdefiniert verwendet den Regler unten. Die Breite wird erst beim Layout-Neuaufbau aufgelöst."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Steuert nur die Kontur der zweiten HP-Leiste. Balken nutzt vier äußere Rahmenkanten; Formen nutzen ihre feste Kantentextur. 0 deaktiviert nur die Kontur."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Steuert nur diese zweite HP-Leiste. Der normale HP-Text des Spieler-Unitframes bleibt davon getrennt."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Steuert diese Aura-Spur unabhängig. Immer / Außerhalb des Kampfes / Modifikator / Nie unter Globaler Stil > Verschiedenes betreffen nur Unit- und Gruppenframes. Auren übernehmen lediglich den gewählten Blizzard/MSUF-Look und die Cursor-Platzierung."
L["Cooldown swipe direction"] = "Richtung des Abklingzeit-Wischeffekts"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Kernfunktion, die für neue Profile standardmäßig und für bestehende Profile einmalig aktiviert wird. Sie funktioniert auch ohne aktiviertes Porträt als normale defensive Buff-Leiste. Schalte dies aus, um sowohl die Leiste als auch die Anzeige an der Porträtposition zu deaktivieren."
L["Crowd Control"] = "Massenkontrolle"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Kuratierte DoT-Auren für Retail 12.0+ und 12.1. Die Verfolgung ist auf die Einheit dieses UnitFrames und deine eigene Aura-Quelle beschränkt; Boss-Einstellungen binden separat an boss1 bis boss5."
L["Curated DoT auras for this game version. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Kuratierte DoT-Auren für diese Spielversion. Die Verfolgung ist auf die Einheit dieses UnitFrames und deine eigene Aura-Quelle beschränkt; Boss-Einstellungen binden separat an boss1 bis boss5."
L["Custom Spell ID"] = "Benutzerdefinierte Zauber-ID"
L["Dark Border"] = "Dunkler Rahmen"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Standardmäßig deaktiviert. Blizzards native Umsetzung aktiviert ein OnUpdate pro Bild für jeden sichtbaren Aura-Button, sobald diese Aura ein berechnetes Pandemie-Fenster besitzt; das kann bereits beginnen, bevor die Warnung sichtbar wird."
L["Dispellable by Group"] = "Von der Gruppe entfernbar"
