L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "Kantenstärke jeder abgetrennten Spielerressourcen-Form, einschließlich Balken, Rund, Kristall und Kugel. 0 deaktiviert nur diese Kante."
