L["Fill Mode"] = "Füllmodus"
L["Focus off"] = "Fokus aus"
L["Focus on"] = "Fokus an"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global folgt dem normalen MSUF-Lebensfarbmodus. Klassenfarbe erzwingt deine Klassenfarbe. Dunkelmodus erzwingt die eingestellte dunkle Leistenfarbe. HP-Gradient färbt nur diese zweite HP-Leiste nach dem aktuellen Leben."
L["Global icon shape"] = "Globale Symbolform"
L["HP Color"] = "HP-Farbe"
L["HP Outline"] = "HP-Kontur"
L["HP Shape"] = "HP-Form"
L["HP only"] = "Nur HP"
L["Healers only"] = "Nur Heiler"
L["Hide permanent auras"] = "Permanente Auren ausblenden"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Blendet die in diesem Bereich ausgewählten DoT-Zauber-IDs aus dem normalen Schwächungs-Container desselben UnitFrames aus, solange DoTs auf dem Ziel aktiv ist. Blizzards schwarze Liste arbeitet SpellID-basiert, daher wird derselbe Zauber auch dann ausgeblendet, wenn ihn ein anderer Spieler wirkt."
L["Highest priority only"] = "Nur höchste Priorität"
L["Icon Border & Shadow"] = "Symbolrahmen & Schatten"
L["Include Nameplate-only"] = "Nur-Namensplaketten einschließen"
L["Inside Left"] = "Innen links"
L["Inside Right"] = "Innen rechts"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Hält die abgetrennte Spielerressource an der Klassenressourcen-Leiste. Die Regler für die Spielerressource sind deaktiviert, solange diese Verbindung aktiv ist."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Behält die eingestellte Porträtgröße und -position als unsichtbaren Anker bei, damit das Defensivsymbol dort bleiben kann, während das Porträt selbst deaktiviert ist."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Behält die eingestellte Porträtgröße, -position und -form als unsichtbaren Anker für verfolgte DoTs bei, während das Porträt selbst deaktiviert ist."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Begrenzt die gleichzeitigen DoT-Symbole am Porträt auf 1 bis 8. Weitere Symbole wachsen in der für diese DoT-Spur eingestellten Wachstumsrichtung nach außen."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Begrenzt die Anzahl gleichzeitiger Defensivsymbole am Porträt auf 1 bis 8. Bestehende Profile bleiben bei 1, bis dieser Wert geändert wird."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Listet alle MSUF-Slash-Befehle im Chat auf, Diagnose inbegriffen."
L["Max portrait icons"] = "Max. Porträtsymbole"
L["Maximum debuff duration"] = "Maximale Schwächungsdauer"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Verschiebt alle Textfelder der abgetrennten Spielerressource gemeinsam. Die Slot-X/Y-Regler unten fügen Versätze pro Slot hinzu."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Verschiebt die Spieler-Ressourcenleiste aus dem Unit-Frame heraus. Anheften verbindet sie mit dem Klassenressourcen-Stapel; Synchronisieren übernimmt nur dessen Breite."
L["Native Aura Flow"] = "Nativer Aura-Ablauf"
L["Blizzard Buff & Debuff Frames"] = "Blizzard-Buff- und Debuffleisten"
L["Hide Blizzard Buff and Debuff Frames"] = "Blizzard-Buff- und Debuffleisten ausblenden"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Blendet nur Blizzards Spieler-Buffleiste und die normalen Debuffsymbole neben der Minikarte aus. Private Auren und Warnungen für tödliche Debuffs bleiben sichtbar."
L["Buffs hidden"] = "Buffs ausgeblendet"
L["Buffs visible"] = "Buffs sichtbar"
L["Debuffs hidden"] = "Debuffs ausgeblendet"
L["Debuffs visible"] = "Debuffs sichtbar"
L["Hide Blizzard Buff Frame"] = "Blizzard-Buffleiste ausblenden"
L["Hide Blizzard Debuff Frame"] = "Blizzard-Debuffleiste ausblenden"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Blendet Blizzards Spieler-Buffleiste neben der Minikarte aus."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Blendet nur Blizzards normale Debuffsymbole neben der Minikarte aus. Private Auren und Warnungen für tödliche Debuffs bleiben sichtbar."
L["Native size"] = "Native Größe"
L["Native stealable marker"] = "Nativer Stehlbar-Marker"
L["Native weapon enchant auras"] = "Native Waffenverzauberungs-Auren"
L["No roles"] = "Keine Rollen"
L["No width limit"] = "Keine Breitenbegrenzung"
L["Not Cancelable"] = "Nicht abbrechbar"
L["Not Cancelable Player"] = "Nicht abbrechbar (Spieler)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Aus zeigt Schwächungen jeder Dauer. Andernfalls werden Schwächungen ausgeblendet, deren Gesamtdauer diese Sekundenzahl überschreitet."
L["One per dispel type"] = "Eines pro Bannart"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Öffnet das globale Aura-Symbol-Thema: Rahmen, Schatten, Farben, Spurenabstand und native Waffenverzauberungen des Spielers. Der Container-Stil dieses Frames bleibt hier."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Optionale Interpolation für diese zweite HP-Leiste. Aus behält direkte native SetValue-Aktualisierungen bei."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Optionaler Darstellungsmodus; die Funktion Defensive Buffs selbst benötigt kein Porträt. Bei aktiviertem Porträt belegt das erste Symbol dieses. Ist das Porträt aus, aktiviere die Positionsoption unten, damit die Symbole dort bleiben; andernfalls fällt MSUF sicher auf die normale Defensivleiste zurück."
L["Orb Size"] = "Kugelgröße"
L["Pandemic Warning & Style"] = "Pandemie-Warnung & Stil"
L["Pandemic color"] = "Pandemie-Farbe"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Platziert den Text der Spielerressource auf der abgetrennten Ressourcenleiste. Ist dies aus, bleibt derselbe Text durch das normale Textlayout positioniert."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Platziert den Dauerbalken an der oberen oder unteren Kante des Aura-Slots."
L["Player Text Outline"] = "Spieler-Textkontur"
L["Power Bar Outline"] = "Ressourcenleisten-Kontur"
L["Power Text On Bar"] = "Ressourcentext auf der Leiste"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "Ressourcen-Anker nutzen die Spieler-Ressourcenleiste, solange sie sichtbar ist; andernfalls fällt die HP-Leiste auf den Klassenressourcen-Anker zurück."
L["Raid In Combat"] = "Schlachtzug im Kampf"
L["Raid In Combat Player"] = "Schlachtzug im Kampf (Spieler)"
L["Raid Player"] = "Schlachtzug (Spieler)"
L["Remaining / Total"] = "Verbleibend / Gesamt"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Verbleibend schrumpft, während die Aura ausläuft. Vergangen wächst, bis die Aura ausläuft."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "Unterhalb dieses Werts wird die verbleibende Zeit mit einer Nachkommastelle angezeigt. Timer zeigen unter 1 Minute einheitenlose Sekunden und darüber lokalisierte Minuten. 0 bedeutet nur ganze Sekunden."
L["Remove from blacklist"] = "Von der schwarzen Liste entfernen"
L["Remove from whitelist"] = "Von der weißen Liste entfernen"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Zeichnet eine zweite native Lebensleiste des Spielers. Die normale HP-Leiste des Spieler-Unitframes bleibt unangetastet, sodass du HP zweimal anzeigen kannst."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Ersetzt die normale DoT-Spur durch porträtgroße Symbole. Das erste Symbol folgt exakt Breite, Höhe und Form des Porträts dieses Frames."
L["Runs /msuf reset for frame positions and visibility."] = "Führt /msuf reset für Frame-Positionen und Sichtbarkeit aus."
L["Second Player HP Bar"] = "Zweite HP-Leiste des Spielers"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Legt den Spieler-Schriftbereich fest, den der abgetrennte Ressourcentext verwendet. Spielername und HP-Text teilen sich diese Kontureinstellung."
L["Show DoTs at portrait position"] = "DoTs an der Porträtposition anzeigen"
L["Show buffs at portrait position"] = "Buffs an der Porträtposition anzeigen"
L["Show cooldown text on portrait"] = "Abklingzeit-Text auf dem Porträt anzeigen"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Zeigt die verbleibende Dauer des aktiven defensiven Buffs über seinem Porträtsymbol. Blizzard aktualisiert den Text nativ."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Zeigt die ausgewählte Klassen-/Spezialisierungsressource unten an, ohne deinen Charakter, deine Spezialisierung oder gespeicherte Einstellungen zu ändern."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Zeigt die verbleibende Dauer des verfolgten DoTs über seinem Porträtsymbol. Blizzard aktualisiert die Dauer nativ."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Einfache Vorlagen für den Text der Spielerressource, während die abgetrennte Ressource von Klassenressourcen verwaltet wird. Benutzerdefinierte Slots bedeutet, dass das bestehende Slot-Layout beibehalten wird, bis du eine Vorlage wählst."
L["Smooth Fill"] = "Weiche Füllung"
L["Spell Text"] = "Zaubertext"
L["Stops blocking this aura."] = "Hebt die Blockierung dieser Aura auf."
L["Sync Width"] = "Breite synchronisieren"
L["Tanks only"] = "Nur Tanks"
L["Target DoT"] = "Ziel-DoT"
L["Target off"] = "Ziel aus"
L["Target on"] = "Ziel an"
L["Time Text"] = "Zeittext"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Diesen vordefinierten defensiven Buff verfolgen. Die Einstellung gilt sowohl für die Defensivleiste als auch für das optionale Porträtsymbol."
L["Tracked buffs viewer"] = "Anzeige verfolgter Buffs"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Verfolgt deine ausgewählten schädlichen Auren auf der Einheit dieses UnitFrames. Boss-Frames verwenden ihre eigenen Einheiten-Token boss1 bis boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Schaltet die Blizzard-Token-Filter für diesen Frame ein oder aus. Die erste Änderung erstellt automatisch frame-spezifische Regeln; migrierte gemeinsame Regeln bleiben gemeinsam, bis sie bearbeitet werden."
L["Unavailable cast fill"] = "Füllung für nicht verfügbaren Zauber"
L["Up (Single Column)"] = "Aufwärts (einspaltig)"
L["Use Player HP Text"] = "Spieler-HP-Text verwenden"
L["Use portrait position while portrait is off"] = "Porträtposition verwenden, während das Porträt aus ist"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Wird nur verwendet, wenn diese HP-Leiste ausdrücklich auf Kugel gesetzt ist. Spielerressource folgen übernimmt stattdessen die Kugelgröße der Spielerressource."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Verwendet Blizzards 12.1-AuraButton-Filter für Stehlbarkeit. Er fügt keinen MSUF-Aura-Scan, keinen Ticker und kein OnUpdate hinzu."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Verwendet die Einstellungen des Spieler-HP-Texts und kopiert den bereits gezeichneten Spieler-HP-Text, sofern er aktuell ist. Lokales Text-X/Y gehört weiterhin zu dieser Leiste."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Verwendet die Klassenressourcen-Breite für die abgetrennte Spielerressource, ohne dass Klassenressourcen die Regler der Spielerressource übernehmen."
L["Utility cooldown viewer"] = "Anzeige hilfreicher Abklingzeiten"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Sichtbar hinter der gefüllten HP-Menge. Bei 100 % HP verdeckt die Füllung den Hintergrund; Kontur 0 deaktiviert diese Textur nicht."
L["Weapon Enchants Off"] = "Waffenverzauberungen aus"
L["Weapon Enchants On"] = "Waffenverzauberungen an"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Solange die Defensivleiste oder das Porträtsymbol aktiviert ist, wird jede aktivierte verfolgte Defensive aus der normalen Buff-Spur des Spielers ausgeblendet. Deaktivierte Defensiv-Einträge bleiben dort sichtbar."
L["Whole frame"] = "Ganzer Frame"
L["Width Mode"] = "Breitenmodus"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Balkenhintergrund-Tönung Eigene Farbe im Dunkelmodus Hintergrund Untergrund bg Deckkraft Alpha background backdrop opacity"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Frame-Grundlagen Aktivieren Ladebedingungen Deckkraft Reichweiten-Fade Spieler Ziel Fokus Begleiter fehlt unsichtbar"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Frame-Grundlagen Weiche Füllung Ressourcenleiste Weiche Füllung Lebensanimation Ressourcenanimation smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "Allgemein MSUF-Gruppenframes verwenden Wenn dieser Schalter aus ist aktivieren deaktivieren ausschalten ausblenden Schlachtzug Gruppe mythisch"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Gruppen-/Raidframes Layout Weiche Lebensfüllung Lebenstext Ressourcenleiste Weiche Füllung Gruppe Schlachtzug smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Gruppen-/Raidframes Layout Deckkraft Transparenz ausblenden Ziel im Kampf außerhalb des Kampfes Alpha ganzer Frame Balken HP Hintergrund HP-Füllung HP-Spur HP-Farbe erhalten"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "Der MSUF-Bearbeitungsmodus verschiebt Frames und unterstützte Zauberleisten. Die Platzierung der Aura-Symbole wird auf der jeweiligen Unit-Seite > Auren oder unter Gruppen-/Raidframes > Auren gesteuert."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Verschiedenes Sonstiges Globaler Stil Sprache Menüverhalten Startmeldungen Tooltips Blizzard-Frames Minimap Töne"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Namenskürzung Eigene Einstellungen für diesen Bereich verwenden Überschreibt Gruppe Schlachtzug Gruppenframe-Namenskürzung Schriftüberschreibung gemeinsame Änderungen"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Öffne Darstellung > Auren für bereichsabhängigen Abklingzeit-Text, Stapeltext, Wischeffekt und Dauerbalken-Stil. Die Timer-Farben bleiben unter Farben > Auren."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Öffne Bossfenster > Auren > Schwächungen. SpellID-Einträge der schwarzen Liste, Blizzard-Filter, Platzierung und Vorschau liegen dort zusammen; der Stil bleibt unter Darstellung > Auren."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Öffne Globaler Stil > Verschiedenes > Unitframe-Tooltips, um Tooltip-Quelle, Anker, Sichtbarkeitsmodus und Modifikatortaste für MSUF-Unit- und Gruppenframes zu steuern."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Öffne Globaler Stil > Verschiedenes für Sprache, Menüverhalten, Startmeldungen, Tooltips, Blizzard-Frames, Minimap-Symbol und Töne."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Öffne Gruppen-/Raidframes > Layout > Reichweiten-Fade. Betrifft wählt zwischen Frame- und HP-Ausblendung, und die Alpha-Regler steuern die Deckkraft außerhalb der Reichweite und im Offline-Zustand."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Öffne Gruppen-/Raidframes > Layout > Deckkraft. Deckkraft steuert Alpha im und außerhalb des Kampfes; Fade-Ziel wählt ganzer Frame, Balken, HP oder Hintergrund. Die Ebenen Hintergrund und Leben legen Grundfarbe, HP-Füllung und HP-Spur-Deckkraft fest."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Öffne Gruppen-/Raidframes > Layout für Weiche Lebensfüllung. Für Ressourcenleisten der Gruppenframes öffne Gruppen-/Raidframes > Layout > Ressourcenleiste > Weiche Füllung."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Öffne Gruppen-/Raidframes > Layout, wähle oben Gruppe, Schlachtzug oder Mythisch und schalte dann MSUF-Gruppenframes verwenden aus. Über Wenn dieser Schalter aus ist legst du fest, ob die Blizzard-Frames normal erscheinen oder beide Frame-Systeme ausgeblendet bleiben."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Öffne Gruppen-/Raidframes > Layout. Frame-Grundlagen und Sortierung steuern die Sichtbarkeit von Spieler und eigenem Frame sowie die Reihenfolge der Spieler in den Gruppenframes."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Öffne Gruppen-/Raidframes > Layout. Frame-Grundlagen/Layout steuert Breite, Höhe, Abstand, Spalten und Wachstum; Frame-Skalierung steuert das Skalierungsverhalten."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Öffne Gruppen-/Raidframes > Status und Indikatoren für Statussymbole, Rolle/Anführer/Assistent, Bereitschaftsprüfung, Fokus-Glühen und weitere Zustandsanzeigen der Gruppenframes."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Öffne Spieler > Auren und schalte dann Buffs für den Spieler-Frame aus. Der bereichsabhängige Text- und Abklingzeit-Stil bleibt unter Darstellung > Auren."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Öffne eine Unit-Seite und verwende dann Reichweiten-Fade. Es ist für Ziel, Ziel des Ziels, Fokus, Fokusziel, Begleiter und Boss verfügbar."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Öffne das betroffene UnitFrame > Auren für Symbolgröße, Platzierung und Filter. Verwende Darstellung > Auren für bereichsabhängigen Text- und Abklingzeit-Stil."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Öffne das betroffene UnitFrame > Auren oder Gruppen-/Raidframes > Auren und reduziere die sichtbare Anzahl, den Timer-Text oder unnötige native Filterregeln."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Öffne das betroffene UnitFrame > Auren, wähle Buffs oder Schwächungen und passe dann Filter, Symbolgröße, Reihen, Obergrenzen und Abstände an. Die Einstellungen für Gruppe/Schlachtzug findest du unter Gruppen-/Raidframes > Auren."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Öffne die Unit-Seite > Auren oder das Aura-Positions-Popup für die Platzierung der Auren am UnitFrame. Buff- und Schwächungssymbole werden als Aura-Layout eingestellt und nicht über den MSUF-Bearbeitungsmodus verschoben."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Reichweiten-Fade Gruppenframe Reichweitenprüfung Schlachtzug Gruppe außerhalb der Reichweite Alpha Offline-Deckkraft betrifft Frame HP"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Reichweiten-Fade Unitframe Reichweitenprüfung Entfernungsprüfung außerhalb der Reichweite Reichweiten-Alpha Entfernungs-Fade Ziel Ziel des Ziels Fokus Fokusziel Begleiter Boss"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Abgerundete Textur Abgerundete Frame-Textur Unit-Frames Gruppenframes Ressourcenleisten Mouseover-Hervorhebungen abgerundete Frames runde Ecken"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Statussymbole Indikator Stufe Aktiviert Anheften X-Versatz Y-Versatz Größe Ebene Stufentext Stufenanzeige Spielerstufe Zielstufe"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Text Anheften Versatz Schriftgröße Ebene Zeichenreihenfolge Abstand geteilter Abstand Überlappungen Balken Porträts Statussymbole"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Verwende Gruppen-/Raidframes > Layout für Framegröße und Abstände, Auren für die Platzierung von Buffs/Schwächungen und Status und Indikatoren für Statussymbole an fester Position."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Verwende die Seiten der Gruppen-/Raidframes: Layout für Größe, Wachstum, Sortierung, Balken und Text; Auren für die Platzierung von Buffs/Schwächungen und Status und Indikatoren für Statussymbole."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Verwende die Unit-Seite für die Zauberleisten-Schalter pro Einheit und Globaler Stil > Zauberleiste für gemeinsame Texturen, Richtung, Text und Unterbrechungsoptionen."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "Willkommen bei den Klassenressourcen!\n\nMöchtest du automatisch eine abgetrennte\nKlassenleiste über deinen wichtigen\nAbklingzeiten einrichten?\n\nDies stellt Sichtbarkeit, Verankerung,\nBreitenanpassung und abgetrennte\nSpielerressource in einem Klick ein.\n\nDu kannst dies später jederzeit über die\nSchaltfläche |cff00ff00Schnellsetup: Klassenleiste|r unten ausführen."
L["Show Grid2 in MSUF Edit Mode"] = "Grid2 im MSUF-Bearbeitungsmodus anzeigen"
L["Grid2 Edit Mode integration"] = "Grid2-Bearbeitungsmodus-Integration"
L["Show Details! in MSUF Edit Mode"] = "Details! im MSUF-Bearbeitungsmodus anzeigen"
L["Details! Edit Mode integration"] = "Details!-Bearbeitungsmodus-Integration"

