-- Menu localization pass 2026-08-06 (part 5): external Edit Mode integration (Details!, Grid2).
L["External Edit Mode"] = "Externer Bearbeitungsmodus"
L["Show Grid2 in MSUF Edit Mode"] = "Grid2 im MSUF-Bearbeitungsmodus anzeigen"
L["Show Details! in MSUF Edit Mode"] = "Details! im MSUF-Bearbeitungsmodus anzeigen"
L["Details! Edit Mode integration"] = "Details!-Bearbeitungsmodus-Integration"
L["Grid2"] = "Grid2"
L["Grid2 Edit Mode integration"] = "Grid2-Bearbeitungsmodus-Integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "An (Standard): Der MSUF-Bearbeitungsmodus kann jedes aktive Details!-Fenster verschieben. Von Details! aneinandergeheftete Fenster bewegen sich als eine native Gruppe."
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "An (Standard): Der MSUF-Bearbeitungsmodus kann das Grid2-Layout und dessen aktive abgetrennte Gruppen verschieben. Grid2 bleibt Eigentümer seines Layouts und seiner gespeicherten Positionen."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Schalte einen der beiden Schalter aus, um nur diese externen Mover zu entfernen. Das Drittanbieter-Addon und seine Einstellungen werden nicht verändert."

