L["Dominos"] = "Dominos"
L["Show Dominos in MSUF Edit Mode"] = "Dominos im MSUF-Bearbeitungsmodus anzeigen"
L["Dominos Edit Mode integration"] = "Dominos-Bearbeitungsmodus-Integration"
L["On (default): MSUF Edit Mode can move every Dominos bar that is not docked to another bar. Docked bars follow their host bar, and Dominos remains the owner of all bar positions."] = "An (Standard): Der MSUF-Bearbeitungsmodus kann jede Dominos-Leiste verschieben, die nicht an eine andere Leiste angedockt ist. Angedockte Leisten folgen ihrer Trägerleiste, und Dominos bleibt Eigentümer aller Leistenpositionen."
L["Turn any of these switches off to remove only those external movers. The third-party addons and their settings are not modified."] = "Schalte einen dieser Schalter aus, um nur diese externen Mover zu entfernen. Die Drittanbieter-Addons und ihre Einstellungen werden nicht verändert."
L["Scale"] = "Skalierung"
