L["DandersFrames Edit Mode integration"] = "DandersFrames-Bearbeitungsmodus-Integration"
L["On (default): MSUF Edit Mode can move the DandersFrames party and raid containers and free pinned sets. Sets glued to the frames follow them, and DandersFrames remains the owner of all saved positions."] = "An (Standard): Der MSUF-Bearbeitungsmodus kann die Gruppen- und Raid-Container von DandersFrames sowie freie angepinnte Sets verschieben. An die Frames geheftete Sets folgen ihnen, und DandersFrames bleibt Eigentümer aller gespeicherten Positionen."

