L["On (default): MSUF Edit Mode can move the Blizzard Minimap, Chat, Micro Menu and Tooltip through the game's own Edit Mode layout. If a Blizzard preset is active, selecting an element creates and activates a saved 'MSUF' layout automatically."] = "An (Standard): Der MSUF-Bearbeitungsmodus kann Blizzards Minimap, Chat, Mikromenü und Tooltip über das spieleigene Bearbeitungsmodus-Layout verschieben. Ist ein Blizzard-Preset aktiv, legt die Auswahl eines Elements automatisch ein gespeichertes Layout 'MSUF' an und aktiviert es."

