L["Off (default): profile strings never carry or change the Blizzard Edit Mode arrangement. On: full-profile exports include it and imports apply it."] = "Aus (Standard): Profil-Strings enthalten oder ändern die Blizzard-Bearbeitungsmodus-Anordnung nie. An: Vollprofil-Exporte enthalten sie und Importe wenden sie an."

-- Menu localization pass 2026-08-08 (part 3): Blizzard layout dialog status line.
