-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Native Spieler-Ressourcen-Pings aktivieren (12.1)"
L["Native Player resource pings"] = "Native Spieler-Ressourcen-Pings"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "Kontextuelle Pings über dem MSUF-Spielerframe können Gesundheit und, wenn Blizzard es unterstützt, Mana melden. Blizzard stellt keine getrennte Auswahl für Gesundheit/Ressource und keine Pings für Energie, Wut oder Fokus bereit. Über dem Porträt bleiben der normale Spieler-Einheiten-Ping und das Ping-Radialmenü erhalten."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Bearbeitet die X-Position des ausgewählten Elements. Positive Werte verschieben es nach rechts. Pfeiltasten und Ziehen aktualisieren dieselbe Position."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Bearbeitet die Y-Position des ausgewählten Elements. Positive Werte verschieben es nach oben. Pfeiltasten und Ziehen aktualisieren dieselbe Position."
L["Exact X position"] = "Genaue X-Position"
L["Exact Y position"] = "Genaue Y-Position"
L["External frame"] = "Externer Frame"
L["Next page"] = "Nächste Seite"
L["Previous page"] = "Vorherige Seite"

L["UnitFrame Debuff blacklist"] = "UnitFrame-Debuff-Blacklist"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID. The debuff on the unit can carry a different Spell ID than the spell you cast - use the ID from the debuff itself."] = "Du kannst jeden vom Spieler verursachten Debuff auf dem %s-UnitFrame über seine exakte Zauber-ID ausblenden. Der Debuff auf der Einheit kann eine andere Zauber-ID haben als der von dir gewirkte Zauber - nutze die ID des Debuffs selbst."
L["Spell ID vs. aura ID"] = "Zauber-ID vs. Aura-ID"
L["The aura on the unit can use a different Spell ID than the spell you cast. Enter the ID shown on the aura itself. After adding, MSUF checks the live unit and warns when only a same-named aura with a different ID is active."] = "Die Aura auf der Einheit kann eine andere Zauber-ID verwenden als der von dir gewirkte Zauber. Gib die ID ein, die die Aura selbst anzeigt. Nach dem Hinzufügen prüft MSUF die Einheit und warnt, wenn nur eine gleichnamige Aura mit anderer ID aktiv ist."
L["%s (#%d) is active on this frame right now - blacklist entry verified."] = "%s (#%d) ist gerade auf diesem Frame aktiv - Blacklist-Eintrag bestätigt."
L["#%d is not active on this frame, but %s is currently active as #%d. The aura's ID can differ from your cast's Spell ID."] = "#%d ist auf diesem Frame nicht aktiv, aber %s ist gerade als #%d aktiv. Die ID der Aura kann von der Zauber-ID deines gewirkten Zaubers abweichen."
L["Block #%d instead"] = "Stattdessen #%d blockieren"
L["Active auras on this frame"] = "Aktive Auren auf diesem Frame"
L["Shows the result of the last scan: every readable aura with the exact ID it carried, plus everything captured earlier this session. Press Rescan to scan the current unit - blocking from this list always uses the aura's own ID. Secret auras cannot be listed."] = "Zeigt das Ergebnis des letzten Scans: jede lesbare Aura mit ihrer exakten ID plus alles in dieser Sitzung Erfasste. Drücke Neu scannen, um die aktuelle Einheit zu scannen - Blockieren aus dieser Liste nutzt immer die ID der Aura selbst. Geheime Auren können nicht gelistet werden."
L["No scan yet - click Rescan"] = "Noch kein Scan - klicke auf Neu scannen"
L["Start combat scan"] = "Kampf-Scan starten"
L["Closes the menu and keeps scanning this frame's auras until combat ends or you press Stop. Every aura an addon can block is captured with its icon - auras Blizzard keeps secret cannot be blocked by any addon."] = "Schließt das Menü und scannt die Auren dieses Frames weiter, bis der Kampf endet oder du auf Scan stoppen drückst. Jede Aura, die ein Addon überhaupt blockieren kann, wird mit Icon erfasst - von Blizzard geheim gehaltene Auren kann kein Addon blockieren."
L["Scanning auras - creating a list"] = "Auren werden gescannt - Liste wird erstellt"
L["%d captured so far"] = "%d bisher erfasst"
L["%d captured so far - %d hidden by Blizzard"] = "%d bisher erfasst - %d von Blizzard verborgen"
L["Hidden auras are Blizzard-secret - no addon can block them. Everything blockable was captured."] = "Verborgene Auren sind Blizzard-Secrets - kein Addon kann sie blockieren. Alles Blockierbare wurde erfasst."
L["Blocked by Blizzard during this fight - resumes automatically. In instances, use the curated presets."] = "Von Blizzard während dieses Kampfes blockiert - setzt automatisch wieder ein. Nutze in Instanzen die kuratierten Sets."
L["Blizzard is blocking aura scanning right now (encounter, Mythic+, or PvP match). Use the curated presets - they cover everything blockable in instanced content."] = "Blizzard blockiert das Aura-Scannen gerade (Encounter, Mythic+ oder PvP-Match). Nutze die kuratierten Sets - sie decken alles ab, was in Instanzen blockierbar ist."
L["Scan complete: %d auras readable right now, %d captured this session. %d more are hidden by Blizzard and cannot be blocked by any addon."] = "Scan abgeschlossen: %d Auren aktuell lesbar, %d in dieser Sitzung erfasst. %d weitere verbirgt Blizzard - kein Addon kann sie blockieren."
L["Stop scan"] = "Scan stoppen"
L["Block selected aura"] = "Ausgewählte Aura blockieren"
L["Blocks the selected aura using the exact ID it carries right now."] = "Blockiert die ausgewählte Aura über die exakte ID, die sie gerade trägt."
L["No readable auras right now"] = "Gerade keine lesbaren Auren"
L["Rescan"] = "Neu scannen"
L["Re-reads the auras on the current unit and adds everything it sees to this session's captured list - works in combat too. Shift-click clears the captured list."] = "Liest die Auren der aktuellen Einheit neu ein und nimmt alles Gesehene in die Erfassungsliste dieser Sitzung auf - funktioniert auch im Kampf. Shift-Klick leert die Erfassungsliste."
L["%s - captured"] = "%s - erfasst"
L["Scan complete: %d auras readable right now, %d captured this session."] = "Scan abgeschlossen: %d Auren aktuell lesbar, %d in dieser Sitzung erfasst."

-- Vollständige Lokalisierung der aus Menu2-Quellen abgeleiteten Texte.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "Aura-Einstellungen sind nur für Spieler-, Ziel-, Fokus- und Bossframes verfügbar."
L["Aura settings were skipped for unsupported UnitFrames."] = "Aura-Einstellungen wurden für nicht unterstützte Unitframes übersprungen."
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "Zauberleisten-Einstellungen sind nur für Spieler-, Ziel-, Fokus- und Bossframes verfügbar."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "Zauberleisten-Einstellungen wurden für Unitframes ohne Zauberleisten übersprungen."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "Durch Ändern dieses Werts wird Manuelle Breite ausgewählt. Beim Spieler wird außerdem Breite mit Klassenressource synchronisieren deaktiviert, damit die neue Breite sofort wirksam wird."
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Bearbeitet den lokalen X-Versatz des ausgewählten untergeordneten Elements. Positive Werte verschieben es nach rechts. Pfeiltasten und Ziehen aktualisieren denselben Versatz."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Bearbeitet den lokalen Y-Versatz des ausgewählten untergeordneten Elements. Positive Werte verschieben es nach oben. Pfeiltasten und Ziehen aktualisieren denselben Versatz."
L["Exact X offset"] = "Genauer X-Versatz"
L["Exact Y offset"] = "Genauer Y-Versatz"
L["No copy categories selected."] = "Keine Kopierkategorien ausgewählt."
L["Nothing was copied."] = "Es wurde nichts kopiert."
L["Outline style"] = "Konturstil"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "Abgerundete Frames ignorieren die Stile Echte Kontur und Textur und behalten die einfarbige Konturfarbe bei."
L["True Outline"] = "Echte Kontur"
L["offset, size, and layer"] = "Versatz, Größe und Ebene"

L["Requires a UI reload."] = "Erfordert ein UI-Reload."
L["Shared entries apply to every spec."] = "Gemeinsame Einträge gelten für jede Spezialisierung."
L["down"] = "unten"
L["left"] = "links"
L["No target"] = "Kein Ziel"
L["Out of combat and no target"] = "Außerhalb des Kampfes und kein Ziel"

L["Class Resource Text"] = "Klassenressourcen-Text"
L["Click to select the value, then press Ctrl+C to copy it."] = "Klicken, um den Wert auszuwählen, dann Strg+C zum Kopieren drücken."
L["HEX color"] = "HEX-Farbe"
L["NSRT nickname integration"] = "NSRT-Spitznamenintegration"
L["Nickname Integration"] = "Spitznamenintegration"
L["On (default): names supplied by Northern Sky Raid Tools replace character names on MSUF unit and group frames. Turn this off to always show character names in MSUF. NSRT and its settings are not modified."] = "Ein (Standard): Von Northern Sky Raid Tools bereitgestellte Spitznamen ersetzen Charakternamen auf MSUF-Einheiten- und Gruppenfenstern. Deaktiviere dies, um in MSUF immer Charakternamen anzuzeigen. NSRT und dessen Einstellungen werden nicht verändert."

-- Native 12.1 spell-ID tooltip CVar (Global > Misc > Unitframe tooltips).
L["Show spell IDs in aura tooltips"] = "Zauber-IDs in Aura-Tooltips anzeigen"
L["Aura tooltip spell IDs"] = "Zauber-IDs in Aura-Tooltips"
L["On: aura tooltips show the numeric spell ID through the game's own 12.1 option, and MSUF re-enables that option after every login because the game forgets it between sessions. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Ein: Aura-Tooltips zeigen die numerische Zauber-ID über die spieleigene 12.1-Option, und MSUF aktiviert diese Option nach jedem Login neu, da das Spiel sie zwischen Sitzungen vergisst. Aus (Standard): MSUF rührt die Spieloption nie an, sodass andere Addons oder eine manuelle Konsoleneinstellung die Kontrolle behalten; das Ausschalten dieses Schalters setzt die Option einmalig zurück."

-- Guided setup restart confirmation.
L["Run the guided setup again? The walkthrough starts over at the first step."] = "Das geführte Setup erneut ausführen? Die Tour beginnt wieder beim ersten Schritt."

-- Überarbeiteter Texture-Layer-Ablauf.
L["HP & Visibility"] = "HP & Sichtbarkeit"
L["Basic setup"] = "Grundeinrichtung"
L["Advanced texture options"] = "Erweiterte Texturoptionen"
L["Quick setup"] = "Schnelleinrichtung"
L["Text background"] = "Texthintergrund"
L["Highlight"] = "Hervorhebung"
L["Texture 1"] = "Textur 1"
L["Texture 2"] = "Textur 2"
L["Texture 3"] = "Textur 3"
L["Texture:"] = "Textur:"
L["Options:"] = "Optionen:"
L["Health behavior"] = "HP-Verhalten"
L["Show by health"] = "Nach HP anzeigen"
L["Color above threshold"] = "Farbe oberhalb des Grenzwerts"
L["Change opacity below threshold"] = "Deckkraft unterhalb des Grenzwerts ändern"
L["Opacity below threshold"] = "Deckkraft unterhalb des Grenzwerts"
L["All selected visibility conditions must match (AND)."] = "Alle gewählten Sichtbarkeitsbedingungen müssen zutreffen (UND)."
L["HP color: Off"] = "HP-Farbe: Aus"
L["HP color: Gradient"] = "HP-Farbe: Verlauf"
L["HP color: Off; threshold still affects opacity or visibility"] = "HP-Farbe: Aus; der Grenzwert wirkt weiterhin auf Deckkraft oder Sichtbarkeit"
L["Creates a simple monochrome texture on the health bar. You can then choose any bar texture and place HP text above it."] = "Erstellt eine einfache einfarbige Textur auf der Gesundheitsleiste. Danach kannst du eine beliebige Leistentextur wählen und den HP-Text darüber platzieren."
L["Applies the built-in additive highlight style to this texture slot."] = "Wendet den integrierten additiven Hervorhebungsstil auf diesen Texturplatz an."
L["Below threshold hides this texture until the unit reaches the configured HP threshold."] = "Unter Grenzwert blendet diese Textur aus, bis die Einheit den eingestellten HP-Grenzwert erreicht."
L["With HP gradient selected, choose what the texture uses after it passes the threshold."] = "Bei gewähltem HP-Verlauf bestimmst du hier die Farbe oberhalb des Grenzwerts."
L["Uses a separate texture opacity below the HP threshold. The normal Opacity from Setup remains active above it."] = "Verwendet unterhalb des HP-Grenzwerts eine eigene Texturdeckkraft. Oberhalb bleibt die normale Deckkraft aus der Einrichtung aktiv."
L["Dispel Type Colors"] = "Farben der Bannungstypen"
L["Magic custom"] = "Magie benutzerdefiniert"
L["Magic color"] = "Magiefarbe"
L["Curse custom"] = "Fluch benutzerdefiniert"
L["Curse color"] = "Fluchfarbe"
L["Disease custom"] = "Krankheit benutzerdefiniert"
L["Disease color"] = "Krankheitsfarbe"
L["Poison custom"] = "Gift benutzerdefiniert"
L["Poison color"] = "Giftfarbe"
L["Bleed custom"] = "Blutung benutzerdefiniert"
L["Bleed color"] = "Blutungsfarbe"
L["Optional global overrides for harmful Magic, Curse, Disease, Poison and Bleed indicators. Off uses Blizzard's current default. The last edited type is shown first in every aura preview."] = "Optionale globale Farben für schädliche Magie-, Fluch-, Krankheits-, Gift- und Blutungsanzeigen. Aus verwendet Blizzards aktuellen Standard. Der zuletzt bearbeitete Typ wird in jeder Auravorschau zuerst angezeigt."
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Timer- und Bannungsfarben gelten für aktive Einheiten- und Gruppenauren sowie alle Vorschauen. Symbolrahmen- und Schattenfarben befinden sich unter Darstellung > Auren und gelten je Auratyp."
L["Cooldown timer urgency, global Dispel types, icon borders and shadows."] = "Dringlichkeit der Abklingzeittimer, globale Bannungstypen sowie Symbolrahmen- und Schattenfarben."
L["Safe, Warning, Urgent, Magic, Curse, Disease, Poison, Bleed, icon border and icon shadow."] = "Sicher, Warnung, Dringend, Magie, Fluch, Krankheit, Gift, Blutung, Symbolrahmen und Symbolschatten."
L["Custom Priority"] = "Feste Priorität"
L["Custom priority"] = "Feste Priorität"
L["Custom Priority packs active tracked DoTs into the configured order. Inactive entries leave no gap; when A appears after B, the display automatically changes from B to A-B."] = "Feste Priorität ordnet aktive verfolgte DoTs kompakt in der festgelegten Reihenfolge an. Inaktive Einträge lassen keine Lücke; erscheint A nach B, wechselt die Anzeige automatisch von B zu A-B."
L["Up"] = "Hoch"
L["Down"] = "Runter"
L["Move up"] = "Nach oben"
L["Move down"] = "Nach unten"
L["Remove DoT"] = "DoT entfernen"
L["Raises this DoT in the fixed priority order."] = "Verschiebt diesen DoT in der festen Prioritätsreihenfolge nach oben."
L["Lowers this DoT in the fixed priority order."] = "Verschiebt diesen DoT in der festen Prioritätsreihenfolge nach unten."
L["Stops tracking this DoT."] = "Beendet die Überwachung dieses DoTs."
L["%d tracked DoTs"] = "%d überwachte DoTs"
L[" - clear Search to reorder"] = " - Suche leeren, um neu zu sortieren"
L[" - dynamic priority active"] = " - dynamische Priorität aktiv"
L[" - choose Custom Priority under Ordering to use this order"] = " - unter Sortierung Feste Priorität wählen, um diese Reihenfolge zu verwenden"
L["While unlocked, the Combat Enter/Leave text is shown permanently as a movable handle. Drag it with the mouse or nudge it with the arrow keys. Lock it so the text only appears when entering or leaving combat."] = "Solange die Position entsperrt ist, wird der Kampf-Betreten/Verlassen-Text dauerhaft als verschiebbarer Anfasser angezeigt. Ziehe ihn mit der Maus oder verschiebe ihn mit den Pfeiltasten. Sperre die Position, damit der Text nur beim Betreten oder Verlassen des Kampfes erscheint."
L["While unlocked, the Combat Timer stays visible out of combat as a movable 0:00 placeholder. Drag it with the mouse or nudge it with the arrow keys - with click-through enabled, hold ALT to drag. Lock it to freeze the position."] = "Solange die Position entsperrt ist, bleibt der Kampf-Timer außerhalb des Kampfes als verschiebbarer 0:00-Platzhalter sichtbar. Ziehe ihn mit der Maus oder verschiebe ihn mit den Pfeiltasten – bei aktiviertem Durchklicken halte ALT zum Ziehen. Sperre die Position, um sie einzufrieren."

L["Switched to profile '%s'.\n\nA UI reload is required to fully apply this profile.\n\nReload now?"] = "Zu Profil „%s“ gewechselt.\n\nEin UI-Neuladen ist erforderlich, um dieses Profil vollständig anzuwenden.\n\nJetzt neu laden?"
L["Switched to profile '%s'. Reload after combat with /reload."] = "Zu Profil „%s“ gewechselt. Nach dem Kampf mit /reload neu laden."
L["Switched to profile '%s'. Reload the UI with /reload."] = "Zu Profil „%s“ gewechselt. UI mit /reload neu laden."
L["Can't reload the UI in combat. Leave combat, then type /reload."] = "UI kann im Kampf nicht neu geladen werden. Verlasse den Kampf und gib dann /reload ein."

L["Buff Reminder"] = "Buff-Erinnerung"
L["Show placeholders for missing auras"] = "Platzhalter für fehlende Auren anzeigen"
L["Gives every whitelisted spell its own fixed slot and draws a dimmed icon underneath it. A running aura covers its own placeholder, so a dimmed icon means that spell is missing. MSUF reads no aura data for this, so it keeps working in raids, Mythic+ and arenas. Reminder slots ignore this container's sorting and duration bars."] = "Gibt jedem freigegebenen Zauber einen festen Platz und zeichnet darunter ein gedimmtes Symbol. Eine laufende Aura verdeckt ihren eigenen Platzhalter, ein gedimmtes Symbol bedeutet also, dass dieser Zauber fehlt. MSUF liest dafür keine Aura-Daten, es funktioniert daher auch in Schlachtzügen, Mythisch+ und Arenen. Erinnerungsplätze ignorieren die Sortierung und die Dauerbalken dieses Containers."
L["Placeholder opacity"] = "Deckkraft des Platzhalters"
L["How strongly a missing aura's placeholder is drawn. Lower values keep the frame calm; the running aura always covers it completely either way."] = "Wie stark der Platzhalter einer fehlenden Aura gezeichnet wird. Niedrige Werte halten den Frame ruhig; die laufende Aura verdeckt ihn ohnehin immer vollständig."
L["Grey out placeholders"] = "Platzhalter ausgrauen"
L["Draws the placeholder without colour so a missing aura reads at a glance. Turn this off to keep the spell's own colours and separate the two states by opacity or tint alone."] = "Zeichnet den Platzhalter ohne Farbe, damit eine fehlende Aura sofort auffällt. Schalte dies aus, um die Eigenfarben des Zaubers zu behalten und die beiden Zustände allein über Deckkraft oder Färbung zu trennen."
L["Placeholder tint"] = "Färbung des Platzhalters"
L["%d fixed reminder slots · whitelist order decides their position."] = "%d feste Erinnerungsplätze · die Reihenfolge der Whitelist bestimmt ihre Position."
L["Off · this container shows only auras that are currently active."] = "Aus · dieser Container zeigt nur aktuell aktive Auren."
L["Reminder on"] = "Erinnerung an"
L["Reminder off"] = "Erinnerung aus"
L["Click the icon to cast the spell"] = "Zum Wirken auf das Symbol klicken"
L["Turns every reminder slot into a cast button: clicking it casts that slot's spell at this frame's unit, whether the aura is missing or already running, so re-applying a poison or flask works. The binding is written once outside combat and never changes afterwards, so this costs no timer, no event and no aura read. Only spells work; food, flasks and other items cannot be triggered this way."] = "Macht jeden Erinnerungsplatz zu einer Wirken-Schaltfläche: ein Klick wirkt den Zauber dieses Platzes auf die Einheit dieses Frames – egal ob die Aura fehlt oder bereits läuft, sodass auch das Neuauftragen eines Gifts oder Fläschchens funktioniert. Die Bindung wird einmal außerhalb des Kampfes geschrieben und danach nie mehr geändert, kostet also weder Timer noch Event noch Aura-Abfrage. Es funktionieren nur Zauber; Essen, Fläschchen und andere Gegenstände lassen sich so nicht auslösen."
L["Click-cast"] = "Klick-Wirken"
L["Remind me about the Main Hand"] = "An die Waffenhand erinnern"
L["Adds a slot that watches the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Fügt einen Platz hinzu, der die temporäre Verzauberung deiner Waffenhand beobachtet – Waffenöl, Stein oder ein auf die Waffe aufgetragenes Gift. Anders als bei einer Aura ist dieser Zustand direkt lesbar, das Symbol leuchtet also auf, solange die Verzauberung läuft, und dimmt, sobald sie weg ist – in jedem Inhalt."
L["Remind me about the Off Hand"] = "An die Schildhand erinnern"
L["Same slot for your off hand. Both hands share the consumable configured below, which is what you normally want."] = "Derselbe Platz für deine Schildhand. Beide Hände teilen sich den unten eingestellten Verbrauchsgegenstand, was in der Praxis genau das Gewünschte ist."
L["Oil or stone - item link or ID"] = "Öl oder Stein – Gegenstandslink oder ID"
L["Use this item"] = "Diesen Gegenstand benutzen"
L["Oil or stone"] = "Öl oder Stein"
L["Paste the consumable you want the slot to offer on click. Leave it empty to keep the reminder as a pure indicator. Weapon enchants cannot be cast, so only an item makes these slots clickable."] = "Füge den Verbrauchsgegenstand ein, den der Platz beim Klick anbieten soll. Lässt du das Feld leer, bleibt die Erinnerung eine reine Anzeige. Waffenverzauberungen lassen sich nicht wirken, nur ein Gegenstand macht diese Plätze also klickbar."
L["Click uses %s."] = "Klick benutzt %s."
L["No item set · the enchant slots only indicate."] = "Kein Gegenstand gesetzt · die Verzauberungsplätze zeigen nur an."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs. Paste an item link instead to track the buff that item applies and offer the item itself on click - flasks, runes, stones and potions all work that way. If the item's buff differs from its use effect, put both on one line: the Spell ID decides what is tracked, the item what a click uses."] = "Gib eine Zauber-ID ein, füge einen Zauberlink ein oder tippe einen Zaubernamen. Diese Whitelist verfolgt exakte Zauber-IDs. Füge stattdessen einen Gegenstandslink ein, um den Buff dieses Gegenstands zu verfolgen und den Gegenstand selbst beim Klick anzubieten – Fläschchen, Runen, Steine und Tränke funktionieren so. Weicht der Buff eines Gegenstands von seinem Benutzen-Effekt ab, schreibe beides in eine Zeile: Die Zauber-ID bestimmt, was verfolgt wird, der Gegenstand, was ein Klick benutzt."
L["Click uses this item"] = "Klick benutzt diesen Gegenstand"
L["Click casts this"] = "Klick wirkt das"
L["No click action · paste an item"] = "Keine Klickaktion · Gegenstand einfügen"
L["%d of %d slots can be clicked."] = "%d von %d Plätzen sind anklickbar."
L["Only active auras"] = "Nur aktive Auren"
L["Fixed slots (reminder)"] = "Feste Plätze (Erinnerung)"
L["Every whitelisted entry keeps its own place. A dimmed icon means that entry is missing."] = "Jeder Whitelist-Eintrag behält seinen eigenen Platz. Ein gedimmtes Symbol bedeutet, dass dieser Eintrag fehlt."
L["Only auras that are currently active are shown, packed together."] = "Es werden nur Auren gezeigt, die gerade aktiv sind, dicht gepackt."
L["Sorting is off while this container shows fixed reminder slots · their order comes from the Whitelist."] = "Sortierung ist aus, solange dieser Container feste Erinnerungsplätze zeigt · ihre Reihenfolge kommt aus der Whitelist."
L["Reminder slots do not draw a duration bar."] = "Erinnerungsplätze zeichnen keinen Dauerbalken."
L["Unavailable"] = "Nicht verfügbar"
L["Off · switch Display to Fixed slots in Setup to use this."] = "Aus · stelle Anzeige im Setup auf Feste Plätze, um das zu nutzen."
L["%d fixed slots · order comes from the Whitelist."] = "%d feste Plätze · Reihenfolge kommt aus der Whitelist."
L["%d fixed slots · %d clickable · order comes from the Whitelist."] = "%d feste Plätze · %d anklickbar · Reihenfolge kommt aus der Whitelist."
L["Add a buff - Spell ID, spell link or item link"] = "Buff hinzufügen – Zauber-ID, Zauber- oder Gegenstandslink"
L["Add a debuff - Spell ID, spell link or item link"] = "Debuff hinzufügen – Zauber-ID, Zauber- oder Gegenstandslink"
L["Weapon enchants"] = "Waffenverzauberungen"
L["Track the Main Hand enchant"] = "Verzauberung der Waffenhand verfolgen"
L["Adds a reminder slot for the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Fügt einen Erinnerungsplatz für die temporäre Verzauberung deiner Waffenhand hinzu – Waffenöl, Stein oder ein auf die Waffe aufgetragenes Gift. Anders als bei einer Aura ist dieser Zustand direkt lesbar, das Symbol leuchtet also auf, solange die Verzauberung läuft, und dimmt, sobald sie weg ist – in jedem Inhalt."
L["Track the Off Hand enchant"] = "Verzauberung der Schildhand verfolgen"
L["Same slot for your off hand. Both hands share the consumable set below, which is what you normally want."] = "Derselbe Platz für deine Schildhand. Beide Hände teilen sich den unten gesetzten Verbrauchsgegenstand, was in der Praxis genau das Gewünschte ist."
L["Bind item"] = "Gegenstand binden"
L["Paste the consumable these slots should offer on click. A weapon enchant cannot be cast, so only an item makes them clickable. Leave it empty to keep them as pure indicators."] = "Füge den Verbrauchsgegenstand ein, den diese Plätze beim Klick anbieten sollen. Eine Waffenverzauberung lässt sich nicht wirken, nur ein Gegenstand macht sie also klickbar. Lässt du das Feld leer, bleiben sie reine Anzeigen."
L["Needs Display set to Fixed slots in Setup · enchants have no aura to show otherwise."] = "Benötigt Anzeige = Feste Plätze im Setup · Verzauberungen haben sonst keine Aura zum Anzeigen."
L["No weapon slot tracked."] = "Kein Waffenplatz verfolgt."
L["No item bound · these slots only indicate."] = "Kein Gegenstand gebunden · diese Plätze zeigen nur an."
L["%d tracked"] = "%d verfolgt"
L["Only show what I can apply myself"] = "Nur zeigen, was ich selbst auftragen kann"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Rows with a bound item always stay, because an item is not class bound. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Blendet jeden freigegebenen Zauber aus, den dieser Charakter nicht wirken kann – ohne eine Lücke zu hinterlassen. So bedient eine Whitelist all deine Charaktere: Der Magier behält Arkane Intelligenz, der Schurke die Gifte. Zeilen mit gebundenem Gegenstand bleiben immer, denn ein Gegenstand ist nicht klassengebunden. MSUF prüft das nur neu, wenn sich Zauberbuch oder Talente wirklich ändern, niemals im Kampf."
L["%d hidden: not castable by this character."] = "%d ausgeblendet: von diesem Charakter nicht wirkbar."
L["Always show"] = "Immer zeigen"
L["Pins this entry so the self-cast filter never hides it. Use it for anything that is not a class ability - a flask, food, a rune, a buff someone else casts on you. MSUF cannot tell those apart from another class's spell on its own: nothing reports which class owns a Spell ID."] = "Heftet diesen Eintrag an, sodass der Selbst-Wirken-Filter ihn nie ausblendet. Nutze das für alles, was keine Klassenfähigkeit ist – Fläschchen, Essen, Runen oder einen Buff, den dir jemand anders gibt. MSUF kann die nicht von einem fremden Klassenzauber unterscheiden: Nichts verrät, welcher Klasse eine Zauber-ID gehört."
L["Filter again"] = "Wieder filtern"
L["Lets the self-cast filter decide about this entry again. It will be hidden on characters that cannot cast it."] = "Überlässt diesen Eintrag wieder dem Selbst-Wirken-Filter. Auf Charakteren, die ihn nicht wirken können, wird er ausgeblendet."
L["always shown"] = "immer sichtbar"
L["hidden on this character"] = "auf diesem Charakter ausgeblendet"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Nothing reports which class owns a Spell ID, so a flask buff looks exactly like a foreign class ability here - protect those with a bound item, or with Always show on the row in the Whitelist. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Blendet jeden freigegebenen Zauber aus, den dieser Charakter nicht wirken kann – ohne eine Lücke zu hinterlassen. So bedient eine Whitelist all deine Charaktere: Der Magier behält Arkane Intelligenz, der Schurke die Gifte. Nichts verrät, welcher Klasse eine Zauber-ID gehört, ein Fläschchen-Buff sieht hier also genauso aus wie ein fremder Klassenzauber – schütze solche Einträge mit einem gebundenen Gegenstand oder mit „Immer zeigen“ in der Whitelist. MSUF prüft das nur neu, wenn sich Zauberbuch oder Talente wirklich ändern, niemals im Kampf."

--- Arena frames (dedicated arena1-3 unit frames)
L["Arena"] = "Arena"
L["Arena Castbar"] = "Arena-Zauberleiste"
L["Arena Frames"] = "Arena-Frames"
L["Arena Layout"] = "Arena-Layout"
L["Arena Opponent"] = "Arena-Gegner"
L["Arena castbar preview"] = "Arena-Zauberleisten-Vorschau"
L["Arena frame layout"] = "Arena-Frame-Anordnung"
L["Arena spacing"] = "Arena-Abstand"
L["Aura settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Aura-Einstellungen sind nur für Spieler-, Ziel-, Fokus-, Boss- und Arena-Frames verfügbar."
L["Castbar settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Zauberleisten-Einstellungen sind nur für Spieler-, Ziel-, Fokus-, Boss- und Arena-Frames verfügbar."
L["MSUF Arena Frames"] = "MSUF Arena-Frames"
L["Sort roles across entire raid"] = "Rollen über den gesamten Raid sortieren"
L["Orders tanks, healers, and damage dealers across the whole raid instead of within each raid group. Raid and Mythic Raid only: applies to By Role together with Preserve raid groups, and to Group + Role."] = "Ordnet Tanks, Heiler und Schadensverursacher über den gesamten Raid statt innerhalb jeder Raidgruppe. Nur Raid und Mythischer Raid: gilt für Rolle zusammen mit Raidgruppen beibehalten sowie für Gruppe + Rolle."
L["Raid-wide roles"] = "Raidweite Rollen"

-- Dispel border unit filter.
L["Show on"] = "Anzeigen bei"
L["Friendly"] = "Freundlich"
L["Enemy"] = "Feindlich"
L["Both"] = "Beide"
-- Menu feature localization: resource displays, mouseover fades, markers and textures.
L[" - drag to set Custom Priority"] = " - ziehen, um die benutzerdefinierte Priorität festzulegen"
L["85% above 15 members / 70% above 25"] = "85% bei mehr als 15 Mitgliedern / 70% bei mehr als 25"
L["Arms only. Shows actual aura charges in a segmented bar, using the same native display as Fury Whirlwind. These two trackers use a bar with static dividers; aura values are never read by the addon. Appearance changes during combat apply after combat."] = "Nur Waffen. Zeigt die tatsächlichen Aura-Aufladungen in einer segmentierten Leiste mit derselben nativen Anzeige wie Wirbelwind für Furor. Beide Tracker verwenden eine Leiste mit festen Trennlinien; das Addon liest keine Aura-Werte aus. Darstellungsänderungen im Kampf werden nach Kampfende übernommen."
L["Augmentation Evoker only. The Player power bar shows the remaining Ebon Might duration instead of Mana, and uses the Player Power settings below for width, height, position, textures and text. Essence stays an ordinary Class Resource, and Mana is available through Alternative Mana. Turn this off to get a normal Mana bar back."] = "Nur Verstärkungsrufer. Die Spieler-Ressourcenleiste zeigt die verbleibende Dauer von Schwarzmacht statt Mana. Breite, Höhe, Position, Texturen und Text folgen den Einstellungen für die Spieler-Ressource unten. Essenz bleibt eine normale Klassenressource; Mana ist über Alternatives Mana verfügbar. Ausschalten stellt die normale Manaleiste wieder her."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Auras."] = "Aura-Optionen, Sortierung und Aura-Stil gelten für diesen Unitframe. Globale Symboldarstellung: Darstellung > Auren."
L["Aura Preview Zoom"] = "Aura-Vorschauzoom"
L["Auto fit pips is active only for Circle, Diamond and Hex. It uses pip count x pip size plus gaps."] = "Automatische Symbolanpassung ist nur für Kreis, Raute und Sechseck aktiv. Die Breite ergibt sich aus Symbolanzahl × Symbolgröße plus Abständen."
L["Automatic preserves the current profile behavior for the active class and specialization, including Maelstrom, Insanity, and Ebon Might hand-offs. Mana explicitly keeps Mana on the Player power bar. Vehicles always use their native resource; classes without a Mana pool keep their normal resource while the preference stays saved."] = "Automatisch behält das Verhalten des aktuellen Profils für Klasse und Spezialisierung bei, einschließlich des Wechsels zu Mahlstrom, Wahnsinn und Schwarzmacht. Mana zeigt ausdrücklich Mana auf der Spieler-Ressourcenleiste. Fahrzeuge verwenden immer ihre eigene Ressource; Klassen ohne Mana behalten ihre normale Ressource, während die Auswahl gespeichert bleibt."
L["Bar height (0 = full)"] = "Balkenhöhe (0 = voll)"
L["Border color and opacity are in Appearance > Colors > Group Frame Colors."] = "Rahmenfarbe und Deckkraft findest du unter Darstellung > Farben > Gruppenrahmenfarben."
L["Boss Number"] = "Bossnummer"
L["Boss range update rate"] = "Boss-Reichweitenprüfungen"
L["Boss update rate"] = "Boss-Aktualisierungsrate"
L["Changes only the disappearing loss glow and is shared by every frame."] = "Ändert nur das ausblendende Verlustleuchten und gilt für alle Frames."
L["Class Resource Smooth Fill"] = "Klassenressource sanft füllen"
L["Class Resource layer"] = "Klassenressourcen-Layer"
L["Class Resource shape"] = "Klassenressourcenform"
L["Class Resource text layer"] = "Klassenressourcentext-Layer"
L["Clickable portrait"] = "Anklickbares Porträt"
L["Elite and rare dragon"] = "Elite- und Rar-Drachen"
L["Elite (gold)"] = "Elite (Gold)"
L["Rare (silver)"] = "Rar (Silber)"
L["Rare elite (silver)"] = "Rar-Elite (Silber)"
L["Boss (winged gold)"] = "Boss (Gold mit Flügeln)"
L["Shows the selected dragon on this unit's visible portrait. Off restores the real classification. Ends when this area closes or combat starts."] = "Zeigt den gewählten Drachen am sichtbaren Portrait dieser Einheit. Aus stellt die echte Einstufung wieder her. Endet beim Verlassen dieses Bereichs oder bei Kampfbeginn."
L["Color and opacity are in Appearance > Colors > Group Frame Colors."] = "Farbe und Deckkraft findest du unter Darstellung > Farben > Gruppenrahmenfarben."
L["Color by class applies to all unit power bars. Resource colors apply when it is off. A matched background follows Health."] = "Klassenfarben gelten für alle Einheiten-Ressourcenleisten. Wenn die Option aus ist, gelten die Ressourcenfarben. Ein angepasster Hintergrund folgt der Gesundheit."
L["Colors follow the currently selected preview resource."] = "Farben folgen der aktuell gewählten Vorschau-Ressource."
L["Custom width"] = "Benutzerdefinierte Breite"
L["Displayed resource"] = "Angezeigte Ressource"
L["Ebon Might On Player Power"] = "Schwarzmacht auf der Spieler-Ressourcenleiste"
L["Fade in (seconds)"] = "Einblenden (Sekunden)"
L["Fade out (seconds)"] = "Ausblenden (Sekunden)"
L["Focus color is in Appearance > Colors > Group Frame Colors."] = "Die Fokusfarbe findest du unter Darstellung > Farben > Gruppenrahmenfarben."
L["Font rendering"] = "Schriftwiedergabe"
L["For Bar, the first direction controls the fill: Right fills left-to-right; Left fills right-to-left. Up or Down remains the secondary layout direction."] = "Bei Balken bestimmt die erste Richtung die Füllung: Rechts füllt von links nach rechts; Links füllt von rechts nach links. Oben oder Unten bleibt die zweite Anordnungsrichtung."
L["Global Aura Appearance"] = "Globale Aura-Darstellung"
L["Guardian Ironfur Tracker"] = "Eisenfell-Tracker (Wächter)"
L["HP color"] = "HP-Farbe"
L["HP shape"] = "HP-Form"
L["Hover the unit frame to reveal this text. Preview stays visible. 0 seconds = instant."] = "Fahre mit der Maus über den Unitframe, um diesen Text anzuzeigen. In der Vorschau bleibt er sichtbar. 0 Sekunden = sofort."
L["In Bear Form, replaces the empty Guardian class-resource slot with an estimated Ironfur lifetime bar. Each successful cast adds one moving marker; Ursoc's Endurance and Guardian of Elune are included."] = "Ersetzt in Bärengestalt den leeren Klassenressourcenplatz des Wächters durch eine Leiste mit der geschätzten Eisenfell-Restdauer. Jeder erfolgreiche Einsatz fügt einen beweglichen Marker hinzu; Ursocs Ausdauer und Wächter von Elune werden berücksichtigt."
L["Ironfur Cast Markers"] = "Eisenfell-Zaubermarker"
L["Keep Absorbs + Prediction Visible"] = "Absorption und Heilungsvorhersage sichtbar halten"
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Auras owns only the global icon theme."] = "Layout, Filter, Listen und der Stil jedes Containers werden am jeweiligen Frame eingestellt. Darstellung > Auren steuert nur das globale Symboldesign."
L["Only show on mouseover"] = "Nur bei Mouseover anzeigen"
L["Open Frames > Party/Raid Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Öffne Frames > Gruppen-/Raidframes > Auren für Buff-/Debuff-Filter, Listen, Sichtbarkeit und Layout. Für Text, Abklingzeiten, Stapel und Dauerbalken öffne Darstellung > Auren und wähle Gruppe oder Raid."
L["Open Frames > Party/Raid Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Appearance > Bars > Absorb Display."] = "Öffne Frames > Gruppen-/Raidframes > Layout. Text, Ressourcenleiste und Reichweitenausblendung stehen neben Frame-Grundlagen und Transparenz. Bannungs-Overlay und Debuff-Streifen findest du auf der Seite Bannungs-Overlay. Heilungsvorhersage findest du unter Darstellung > Balken > Absorptionsanzeige."
L["Opens: Frames > Party/Raid Frames > Layout"] = "Öffnet: Frames > Gruppen-/Raidframes > Layout"
L["Opens: Frames > Party/Raid Frames > Status & Indicators"] = "Öffnet: Frames > Gruppen-/Raidframes > Status & Indikatoren"
L["Orb size"] = "Kugelgröße"
L["Ordering and individual Style are edited here. Global icon theme: Appearance > Auras."] = "Sortierung und individuellen Stil bearbeitest du hier. Globales Symboldesign: Darstellung > Auren."
L["Pandemic only"] = "Nur Pandemic-Fenster"
L["Performance warning\n\nCustom Boss update rates replace the adaptive default with continuous range checks for every visible Boss Frame. Higher values can increase CPU use during encounters.\n\nStandard keeps the performance-friendly adaptive rate."] = "Leistungswarnung\n\nBenutzerdefinierte Boss-Aktualisierungsraten ersetzen den adaptiven Standard durch fortlaufende Reichweitenprüfungen für jeden sichtbaren Bossframe. Höhere Werte können die CPU-Last während Begegnungen erhöhen.\n\nStandard behält die ressourcenschonende adaptive Rate bei."
L["Player Power layer"] = "Spieler-Ressourcen-Layer"
L["Player Power text layer"] = "Spieler-Ressourcentext-Layer"
L["Power Loss Color"] = "Ressourcenverlustfarbe"
L["Power X"] = "Ressource X"
L["Power Y"] = "Ressource Y"
L["Power bar color by class"] = "Ressourcenleiste nach Klasse färben"
L["Power text size"] = "Ressourcentextgröße"
L["Requires MapkoSkin API 2.1. Disabling restores the MSUF look; unit frames and profile colors are unchanged."] = "Erfordert MapkoSkin API 2.1. Deaktivieren stellt das MSUF-Aussehen wieder her; Unitframes und Profilfarben bleiben unverändert."
L["Resource text"] = "Ressourcentext"
L["Shape, border and shadow: Appearance > Auras > Buffs. All controls here remain Group-scope aware."] = "Form, Rahmen und Schatten: Darstellung > Auren > Buffs. Alle Einstellungen hier berücksichtigen weiterhin den Gruppenbereich."
L["Shared Dispel type colors plus the other colors available to this card's border modes."] = "Gemeinsame Bannungstyp-Farben sowie weitere Farben für die Rahmenmodi dieser Karte."
L["Shared by Dispel borders, overlays, symbols, and every related preview."] = "Gemeinsam für Bannungsrahmen, Overlays, Symbole und alle zugehörigen Vorschauen."
L["Show Ebon Might duration (Aug)"] = "Schwarzmacht-Dauer anzeigen (Verstärkung)"
L["Show Ironfur cast markers"] = "Eisenfell-Zaubermarker anzeigen"
L["Show Ironfur tracker (Guardian)"] = "Eisenfell-Tracker anzeigen (Wächter)"
L["Show Sweeping Strikes (Arms)"] = "Weitreichende Stöße anzeigen (Waffen)"
L["Show heal prediction"] = "Heilungsvorhersage anzeigen"
L["Include healing from others"] = "Heilung anderer Spieler einbeziehen"
L["Show negative heal absorbs"] = "Heilungsabsorption anzeigen"
L["Show only below 100% health"] = "Nur unter 100% Gesundheit anzeigen"
L["Show positive absorbs"] = "Schadensabsorption anzeigen"
L["Shows one moving marker per tracked Ironfur cast. The 30 Hz motion ticker exists only while the optional tracker has active casts."] = "Zeigt einen beweglichen Marker pro erfasstem Einsatz von Eisenfell. Der 30-Hz-Bewegungsticker läuft nur, solange der optionale Tracker aktive Einsätze verfolgt."
L["Slug uses WoW's crisp vector font renderer. Slug supports None or normal Outline; Thick Outline and text shadow are unavailable while it is active."] = "Slug nutzt WoWs scharfe Vektorschriftdarstellung. Slug unterstützt Keine oder normale Kontur; Dicke Kontur und Textschatten sind bei aktivem Slug nicht verfügbar."
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in Appearance > Colors > Unit Frames."] = "Weicher Verlauf hebt den gesamten Frame beim Mouseover klar hervor, ohne das Porträt zu verdecken. Fester Rahmen behält eine scharfe Kante. Wähle die Farbe unter Darstellung > Farben > Unitframes."
L["Standard keeps the adaptive 0.75 / 2 second checks. Higher values continuously check visible Boss Frames at the selected rate; 20 per second is a 50 ms interval."] = "Standard behält die adaptiven Prüfungen alle 0,75 / 2 Sekunden bei. Höhere Werte prüfen sichtbare Bossframes fortlaufend mit der gewählten Rate; 20 pro Sekunde entspricht einem Intervall von 50 ms."
L["Status icon controls include the Level indicator, visibility, anchor, size, and layer. Position is edited in Preview."] = "Die Statussymbol-Einstellungen umfassen Stufenanzeige, Sichtbarkeit, Anker, Größe und Layer. Die Position bearbeitest du in der Vorschau."
L["Surge 8.0"] = "Surge 8.0"
L["Sweeping Strikes"] = "Weitreichende Stöße"
L["Track interrupts on your focus with a detached kick icon, optionally alongside the Focus castbar."] = "Verfolge Unterbrechungen auf deinem Fokus mit einem separaten Unterbrechungssymbol, optional neben der Fokus-Zauberleiste."
L["Updates per second"] = "Aktualisierungen pro Sekunde"
L["Use Appearance > Bars for highlight borders and Frames > Party/Raid Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Frames > Party/Raid Frames > Auras."] = "Nutze Darstellung > Balken für Hervorhebungsrahmen und Frames > Gruppen-/Raidframes > Status & Indikatoren für Rollen-, Bedrohungs-, Bannungs-, Eck- und Schlachtzugsmarkierungen. Zauberindikatoren findest du unter Frames > Gruppen-/Raidframes > Auren."
L["Uses Blizzard's native StatusBar interpolation when an active aura duration is refreshed. The countdown itself remains C-side."] = "Verwendet die native StatusBar-Interpolation von Blizzard, wenn eine aktive Aura-Dauer aktualisiert wird. Der Countdown selbst bleibt C-seitig."
L["Vertical offset"] = "Vertikaler Versatz"
L["Warrior - Sweeping Strikes"] = "Krieger - Weitreichende Stöße"

