L["Applies MSUF's global scale preset for 1080p-like setups and reloads your UI. Auto restores Blizzard scaling on reload."] = "Wendet MSUFs globale Skalierungsvorgabe für 1080p-ähnliche Setups an und lädt die Oberfläche neu. Beim Neuladen wird die Blizzard-Skalierung automatisch wiederhergestellt."
L["Applies MSUF's global scale preset for 1440p-like setups and reloads your UI. Auto restores Blizzard scaling on reload."] = "Wendet MSUFs globale Skalierungsvorgabe für 1440p-ähnliche Setups an und lädt die Oberfläche neu. Beim Neuladen wird die Blizzard-Skalierung automatisch wiederhergestellt."
L["Applies MSUF's global scale preset for 4K (2160p) setups (0.3556) and reloads your UI. Auto restores Blizzard scaling on reload."] = "Wendet MSUFs globale Skalierungsvorgabe für 4K-Setups (2160p, 0,3556) an und lädt die Oberfläche neu. Beim Neuladen wird die Blizzard-Skalierung automatisch wiederhergestellt."
L["Applies the selected preset to your current active profile. This overwrites settings (export first if unsure)."] = "Wendet die gewählte Vorlage auf dein aktuell aktives Profil an. Dabei werden Einstellungen überschrieben (im Zweifel vorher exportieren)."
