L["Party Interrupt Tracker"] = "Gruppen-Unterbrechungstracker"
L["Party Interrupt Tracker\n\nThis is a BEST-GUESS tracker:\n• Detects PARTY interrupts via UNIT_SPELLCAST_SUCCEEDED.\n• Cooldowns are estimated from a static table (talents/resets may differ).\n• Some abilities/modifiers cannot be inspected reliably in 12.0.\n\nIf other party members also use MSUF, kicks are synced via addon messages to improve reliability.\n\nMythic+ only (party). Disabled in raid/open world."] = "Gruppen-Unterbrechungstracker\n\nDies ist ein Tracker auf Schätzbasis:\n• Erkennt Gruppen-Unterbrechungen über UNIT_SPELLCAST_SUCCEEDED.\n• Abklingzeiten werden anhand einer festen Tabelle geschätzt (Talente/Zurücksetzungen können abweichen).\n• Manche Fähigkeiten/Modifikatoren lassen sich in 12.0 nicht zuverlässig auslesen.\n\nWenn andere Gruppenmitglieder ebenfalls MSUF nutzen, werden Unterbrechungen über Addon-Nachrichten abgeglichen, um die Zuverlässigkeit zu erhöhen.\n\nNur Mythisch+ (Gruppe). Im Schlachtzug und in der offenen Welt deaktiviert."
