L["TIP: Hover this slider and use the Mouse Wheel to change the scale in 5% steps.\n\nScales only MSUF frames (unitframes + castbars). Range 25%–150% (0.25–1.50). Drag or click to adjust. Applied immediately; in combat it applies after combat."] = "TIPP: Fahre über diesen Regler und nutze das Mausrad, um die Skalierung in 5-%-Schritten zu ändern.\n\nSkaliert nur MSUF-Frames (Einheitenframes + Zauberleisten). Bereich 25 %–150 % (0.25–1.50). Ziehen oder klicken zum Anpassen. Wird sofort angewendet; im Kampf erst nach dem Kampf."
L["TIP: Hover this slider and use the Mouse Wheel to change the scale in 5% steps.\n\nScales only the MSUF Slash Menu window. Range 25%–150% (0.25–1.50). Drag or click to adjust. Applied immediately."] = "TIPP: Fahre über diesen Regler und nutze das Mausrad, um die Skalierung in 5-%-Schritten zu ändern.\n\nSkaliert nur das MSUF-Menüfenster. Bereich 25 %–150 % (0.25–1.50). Ziehen oder klicken zum Anpassen. Wird sofort angewendet."
