L["Track interrupts on your Focus without showing the Focus castbar."] = "Verfolge Unterbrechungen an deinem Fokus, ohne die Fokus-Zauberleiste anzuzeigen."
L["Troubleshoot: If visuals don’t update, a quick |cff00ff00/reload|r fixes most UI state issues."] = "Fehlerbehebung: Wenn die Anzeige nicht aktualisiert wird, behebt ein kurzes |cff00ff00/reload|r die meisten UI-Zustandsprobleme."
L["Turned Off in Gameplay"] = "Unter „Gameplay“ deaktiviert"
L["Turns off all scaling MSUF applies (global UI scale + MSUF-only scale), then reloads your UI. Blizzard handles scaling."] = "Deaktiviert jede von MSUF angewendete Skalierung (globale UI-Skalierung + MSUF-eigene Skalierung) und lädt die Oberfläche neu. Die Skalierung übernimmt dann Blizzard."
L["Type"] = "Typ"
L["UI scale tip: MSUF has its own UI scale — separate from the Global UI scale."] = "Tipp zur UI-Skalierung: MSUF hat eine eigene UI-Skalierung – unabhängig von der globalen UI-Skalierung."
L["Undo last change"] = "Letzte Änderung rückgängig machen"
L["Unified bar color"] = "Einheitliche Leistenfarbe"
L["Unit info panel"] = "Einheiteninfofeld"
L["Updates"] = "Aktualisierungen"
L["Updates the power number on every game event"] = "Aktualisiert den Ressourcenwert bei jedem Spielereignis"
L["Use \"Enable filters\" in the Auras 2.0 box as the master switch.\n\nInclude toggles are additive (they never hide your normal auras).\nHighlight toggles only change border colors.\n\nDebuff types: if you select ANY type, debuffs are limited to the selected types."] = "Nutze „Filter aktivieren“ im Auren-2.0-Bereich als Hauptschalter.\n\nEinschluss-Schalter sind additiv (sie blenden deine normalen Auren nie aus).\nHervorhebungs-Schalter ändern nur Rahmenfarben.\n\nDebuff-Typen: Wenn du IRGENDEINEN Typ auswählst, werden Debuffs auf die gewählten Typen beschränkt."
L["Use Midnight style icons"] = "Midnight-Symbole verwenden"
L["Use bold text (THICKOUTLINE)"] = "Fetten Text verwenden (THICKOUTLINE)"
L["Use the Bar settings scope dropdown (left panel, bottom) to choose which unit these settings apply to."] = "Wähle über das Dropdown „Leisten-Geltungsbereich“ (linkes Feld, unten), für welche Einheit diese Einstellungen gelten."
L["Use the Bar settings scope dropdown to choose which unit these settings apply to."] = "Wähle über das Dropdown „Leisten-Geltungsbereich“, für welche Einheit diese Einstellungen gelten."
L["Used by: Crosshair color"] = "Verwendet von: Fadenkreuzfarbe"
L["Uses ExponentialEaseOut interpolation on the"] = "Verwendet ExponentialEaseOut-Interpolation für die"
L["WARNING:\n\nAFK/DND status indicators do NOT update while you are inside an instance AND in combat.\nThis is a client/API limitation.\n\nOutside of instance combat they should work normally.\n\nEnable anyway?"] = "WARNUNG:\n\nAFK-/DND-Statussymbole werden NICHT aktualisiert, solange du dich in einer Instanz UND im Kampf befindest.\nDas ist eine Client-/API-Beschränkung.\n\nAußerhalb des Instanzkampfes funktionieren sie normal.\n\nTrotzdem aktivieren?"
L["WARNING: Best-guess tracking. Cooldowns are estimated; talents/resets may differ. If other party members use MSUF, kicks are synced via addon messages for better accuracy."] = "WARNUNG: Verfolgung auf Schätzbasis. Abklingzeiten werden geschätzt; Talente/Zurücksetzungen können abweichen. Wenn andere Gruppenmitglieder MSUF nutzen, werden Unterbrechungen über Addon-Nachrichten abgeglichen, um die Genauigkeit zu erhöhen."
L["Weapon enchant buffs (Windfury, Flametongue, Earthliving, etc.)."] = "Waffenverzauberungs-Buffs (Windzorn, Flammenzunge, Lebensgeister usw.)."
L["When OFF: Bar snaps instantly to new values."] = "Wenn AUS: Die Leiste springt sofort auf neue Werte."
L["When OFF: Text updates are budget-gated"] = "Wenn AUS: Textaktualisierungen werden budgetiert"
L["When enabled, Blizzard handles countdown numbers natively in C++.\nDisables timer colors but eliminates all periodic timer CPU overhead.\nFont, size and position are still controlled by MSUF."] = "Wenn aktiviert, verwaltet Blizzard die Countdown-Zahlen nativ in C++.\nDamit entfallen Timer-Farben, dafür verschwindet die gesamte periodische CPU-Last der Timer.\nSchriftart, Größe und Position steuert weiterhin MSUF."
L["When enabled, aura cooldown text uses Safe / Warning / Urgent colors based on remaining time.\nWhen disabled, aura cooldown text always uses the Safe color."] = "Wenn aktiviert, nutzt der Abklingzeit-Text der Auren je nach Restzeit die Farben Sicher / Warnung / Dringend.\nWenn deaktiviert, verwendet er immer die Farbe „Sicher“."
L["When enabled, placeholder auras can be shown while MSUF Edit Mode is active."] = "Wenn aktiviert, können im MSUF-Bearbeitungsmodus Platzhalter-Auren angezeigt werden."
L["When enabled, the cooldown swipe represents elapsed time (darkens as time is lost).\n\nTurn this OFF to keep the default cooldown-style swipe."] = "Wenn aktiviert, stellt der Abklingzeit-Wisch die verstrichene Zeit dar (er verdunkelt sich mit fortschreitender Zeit).\n\nDeaktiviere dies, um den standardmäßigen Abklingzeit-Wisch zu behalten."
L["When off, this unit uses Shared caps (Max Buffs/Debuffs, Icons per row). When on, it uses its own caps."] = "Wenn deaktiviert, nutzt diese Einheit die gemeinsamen Obergrenzen (max. Buffs/Debuffs, Symbole pro Reihe). Wenn aktiviert, nutzt sie eigene Obergrenzen."
L["When off, this unit uses Shared filter settings. When on, it uses its own copy of the filters."] = "Wenn deaktiviert, nutzt diese Einheit die gemeinsamen Filtereinstellungen. Wenn aktiviert, nutzt sie eine eigene Kopie der Filter."
L["When scope is set to 'Shared', settings apply globally. Select a unit and enable 'Override shared settings' to customize per unitframe."] = "Steht der Geltungsbereich auf „Gemeinsam“, gelten die Einstellungen global. Wähle eine Einheit und aktiviere „Gemeinsame Einstellungen überschreiben“, um sie je Einheitenframe anzupassen."
L["When unchecked, this unit inherits Shared settings for text modes, absorb display, and spacers."] = "Ist dies nicht aktiviert, übernimmt diese Einheit die gemeinsamen Einstellungen für Textmodi, Absorptionsanzeige und Abstandhalter."
L["When unchecked, this unit inherits Shared settings."] = "Ist dies nicht aktiviert, übernimmt diese Einheit die gemeinsamen Einstellungen."
