L["Group size selects both the scaling percentage and raid overrides. Raid overrides are unavailable for Party frames."] = "Die Gruppengröße bestimmt sowohl den Skalierungsprozentsatz als auch die Raidvorgaben. Raidvorgaben sind für Gruppenrahmen nicht verfügbar."
L["Group size scale (%)"] = "Skalierung nach Gruppengröße (%)"
L["The percentage applies in By group size mode. Exact raid dimensions below replace scaled width or height; 0 keeps the scaled base. Spacing and resource bar height still use the scaling percentage."] = "Der Prozentsatz gilt im Modus „Nach Gruppengröße“. Die genauen Raidmaße unten ersetzen die skalierte Breite oder Höhe; 0 behält die skalierte Basis. Abstände und Ressourcenleistenhöhe verwenden weiterhin den Skalierungsprozentsatz."
L["Raid overrides"] = "Raidvorgaben"
L["1–10 players"] = "1–10 Spieler"
L["11–20 players"] = "11–20 Spieler"
L["21–25 players"] = "21–25 Spieler"
L["Group visibility options apply only to their matching Party, Raid, or Mythic Raid scope. Empty groups collapse when Preserve raid groups is enabled."] = "Die Optionen zur Gruppensichtbarkeit gelten nur für den jeweiligen Bereich Gruppe, Raid oder mythischer Raid. Leere Gruppen werden zusammengefasst, wenn „Raidgruppen beibehalten“ aktiviert ist."

-- Group frames: buff coverage (WoW Forever).
L["Buff coverage (Forever)"] = "Buffabdeckung (Forever)"
L["Show buff coverage icons"] = "Symbole der Buffabdeckung anzeigen"
L["Arcane Intellect"] = "Arkane Intelligenz"
L["Paladin blessings"] = "Paladinsegen"
L["Power Word: Fortitude"] = "Machtwort: Seelenstärke"
L["Divine Spirit"] = "Göttlicher Willen"
L["Keep showing during combat"] = "Im Kampf weiter anzeigen"
L["Thorns only on tanks"] = "Dornen nur auf Tanks"
L["Glow missing icons"] = "Fehlende Buff-Symbole leuchten lassen"
L["Icon size"] = "Symbolgröße"
L["Icon anchor"] = "Symbolanker"
L["Horizontal offset"] = "Horizontaler Versatz"
L["Each icon marks a buff that a class in your group can cast but this member lacks. Thorns is checked on members with the Tank role (on everyone with Thorns only on tanks off), Arcane Intellect and Divine Spirit on mana users. Combat, encounters and PvP matches hide aura data, so the icons keep their last known state until it ends."] = "Jedes Symbol steht für einen Buff, den eine Klasse in deiner Gruppe wirken kann, der diesem Mitglied aber fehlt. Dornen wird bei Mitgliedern mit der Tankrolle geprüft (bei allen, wenn „Dornen nur auf Tanks“ aus ist), Arkane Intelligenz und Göttlicher Willen bei Manaklassen. Im Kampf, in Begegnungen und in PvP-Partien sind Aurendaten verborgen, daher behalten die Symbole bis zu deren Ende ihren letzten bekannten Stand."

