L["Healers are found by their assigned group role, not by class. Classic and Forever groups often leave roles unassigned: set them with Set Role in a member's right-click menu where the game offers it."] = "Heiler werden an ihrer zugewiesenen Gruppenrolle erkannt, nicht an der Klasse. In Classic und Forever bleiben Rollen oft unvergeben: Lege sie mit „Rolle festlegen“ im Rechtsklickmenü eines Mitglieds fest, wo das Spiel es anbietet."
