L["Choose where the Unit Frame layout attaches to CDM: above, centered or below. Keep independent leaves it unattached."] = "Die Unit Frames am CDM oberhalb, mittig oder unterhalb verankern. Unabhängig beibehalten lässt sie unverankert."

L["Size and position"] = "Größe und Position"
L["Out of reach"] = "Außer Reichweite"
L["Copy Swing Timer settings"] = "Swing-Timer-Einstellungen kopieren"
L["Copies selected settings. Positions, enabled states and main-hand-only options stay unchanged."] = "Kopiert die gewählten Einstellungen. Positionen, Aktivierungszustände und reine Waffenhand-Optionen bleiben erhalten."

L["Copy resource bar settings"] = "Ressourcenleisten-Einstellungen kopieren"
L["Reset resource bar settings"] = "Ressourcenleisten-Einstellungen zurücksetzen"
L["Reset selected"] = "Auswahl zurücksetzen"
L["No compatible settings to copy."] = "Keine passenden Einstellungen zum Kopieren."
L["Copies compatible settings. Keeps positions, anchors and activation. Player Power uses Player power text size and smoothing."] = "Kopiert passende Einstellungen. Positionen, Anker und Aktivierung bleiben erhalten. Die Spielerressource nutzt Textgröße und Glättung der Spielerressource."
L["Set up Class Resources and Player Power?\n\nChanges visibility, anchors, sizes and positions.\nPlacement: %s.\n\nUndo is available."] = "Klassenressourcen und Spielerressource einrichten?\n\nÄndert Sichtbarkeit, Anker, Größen und Positionen.\nPlatzierung: %s.\n\nRückgängig ist verfügbar."
L["Essential Cooldowns or screen center"] = "Haupt-Cooldowns oder Bildschirmmitte"
L["Enable a resource bar to preview it."] = "Aktiviere eine Ressourcenleiste für die Vorschau."
L["Additional mana bar for dual-resource specializations."] = "Zusätzliche Manaleiste für Spezialisierungen mit zwei Ressourcen."

L["Reset %s to defaults?"] = "%s auf Standard zurücksetzen?"
-- Menu labels, summaries and help.
L["%d editable Layer numbers (0-30)"] = "%d bearbeitbare Ebenennummern (0-30)"
L["%d px / %s"] = "%d px / %s"
L["%d px / %s / %s"] = "%d px / %s / %s"
L["%s (off)"] = "%s (aus)"
L["%s (shared)"] = "%s (gemeinsam)"
L["%s / %d px"] = "%s / %d px"
L["%s Icon"] = "%s-Symbol"
L["%s Icons"] = "%s-Symbole"
L["%s Off"] = "%s aus"
L["%s On"] = "%s an"
L["%s preview layer"] = "Vorschauebene: %s"
L["%s section"] = "Abschnitt %s"
L["Abbreviates large HP numbers, absorb included, instead of printing the full value. Available while a slot shows a number."] = "Kürzt große Lebenswerte einschließlich Absorption ab, statt den vollständigen Wert anzuzeigen. Verfügbar, wenn ein Textplatz eine Zahl anzeigt."
L["Action failed"] = "Aktion fehlgeschlagen"
L["Add Custom Buff"] = "Benutzerdefinierten Buff hinzufügen"
L["Adds a shade over the filled part of health bars that darkens toward the arrows you pick. The strength slider sets how dark it gets."] = "Legt einen Schatten über den gefüllten Teil der Lebensleisten. Er wird in Richtung der ausgewählten Pfeile dunkler. Der Stärkeregler bestimmt die Dunkelheit."
L["Adds a shield glow at the end of the health bar when absorbs plus incoming heals cover all of the missing health."] = "Zeigt ein Schildleuchten am Ende der Lebensleiste, wenn Absorption und eingehende Heilung zusammen die gesamte fehlende Gesundheit abdecken."
L["Adds or removes a fade direction; the shade darkens toward this arrow. Directions can be combined, and one always stays on."] = "Aktiviert oder deaktiviert eine Verlaufsrichtung. Der Schatten wird in Richtung dieses Pfeils dunkler. Mehrere Richtungen lassen sich kombinieren; mindestens eine bleibt aktiv."
L["Adds the same fading shade to power bars, with its own direction arrows and strength."] = "Fügt Ressourcenleisten denselben Schattenverlauf hinzu, mit eigenen Richtungspfeilen und eigener Stärke."
L["Adds the unit's absorb shield amount after this slot's HP value, with or without a shield icon. Shown only while a shield is active."] = "Zeigt den Absorptionswert des Schildes nach dem Lebenswert dieses Textplatzes an, mit oder ohne Schildsymbol. Nur sichtbar, solange ein Schild aktiv ist."
L["Also keeps Blizzard Focus visible; /reload required."] = "Lässt auch Blizzards Fokusrahmen sichtbar; /reload erforderlich."
L["Also keeps Blizzard Target visible; /reload required."] = "Lässt auch Blizzards Zielrahmen sichtbar; /reload erforderlich."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: %s."] = "Aura-Optionen, Sortierung und Aura-Stil gelten für diesen Einheitenrahmen. Globales Symbolaussehen: %s."
L["Aura sensor enabled for Dispel. Buff and Debuff icon caps may stay at 0."] = "Aura-Erkennung für die Entzauberungsanzeige aktiviert. Die Höchstzahl der Buff- und Debuff-Symbole darf bei 0 bleiben."
L["Aura tooltip caster names"] = "Zauberwirker in Aura-Tooltips"
L["Aura type:"] = "Aura-Typ:"
L["Automatic keeps each resource's established text, such as Current for Combo Points and Current / Maximum for Vengeance Soul Fragments. The explicit modes override only the central resource value; Rune timers, Ebon Might duration and the Ironfur stack counter keep their native formats."] = "Automatisch behält die übliche Textanzeige jeder Ressource bei, etwa Aktuell für Combopunkte und Aktuell / Maximum für Seelenfragmente (Rachsucht). Die anderen Modi ändern nur den mittleren Ressourcenwert. Runentimer, die Dauer von Schwarzmacht und der Stapelzähler von Eisenfell behalten ihre eigenen Formate."
L["Background Color"] = "Hintergrundfarbe"
L["Bar"] = "Leiste"
L["Bar Outline Color"] = "Leistenkonturfarbe"
L["Border Alpha (%)"] = "Rahmendeckkraft (%)"
L["Border color and opacity are in %s."] = "Rahmenfarbe und Deckkraft werden unter %s eingestellt."
L["Buttons"] = "Schaltflächen"
L["Cannot load %s: %s"] = "%s kann nicht geladen werden: %s"
L["Choose the Health and Power shape for this frame. Use shared style follows %s."] = "Legt die Form der Lebens- und Ressourcenleisten dieses Rahmens fest. Gemeinsamen Stil verwenden übernimmt die Einstellungen aus %s."
L["Class / Reaction"] = "Klasse / Reaktion"
L["Class Resource Layer"] = "Ebene der Klassenressource"
L["Class Resource Text Layer"] = "Textebene der Klassenressource"
L["Click casting / Clique"] = "Klickzaubern / Clique"
L["Color and opacity are in %s."] = "Farbe und Deckkraft werden unter %s eingestellt."
L["Colors the border by debuff type while the unit has a debuff that Dispel border detects. Changing it asks for a UI reload."] = "Färbt den Rahmen nach dem Debuff-Typ, solange die Einheit einen von der Entzauberungsanzeige erkannten Debuff hat. Eine Änderung erfordert das Neuladen der Benutzeroberfläche."
L["Colors the border while the unit has a buff you can purge or spellsteal. Only Target and Focus frames support it."] = "Färbt den Rahmen, solange die Einheit einen Buff hat, der entfernt oder mit Zauberraub gestohlen werden kann. Nur Ziel- und Fokusrahmen unterstützen diese Anzeige."
L["Companion"] = "Begleiter"
L["Configure target highlighting in %s."] = "Zielhervorhebung in %s konfigurieren."
L["Controls how subtle or strong the rounded corners appear. Masks, outlines, highlights, mouseover edges, power bars, enabled class resources, and enabled castbars use the same value."] = "Bestimmt, wie dezent oder ausgeprägt die abgerundeten Ecken erscheinen. Masken, Konturen, Hervorhebungen, Mouseover-Ränder, Ressourcenleisten sowie aktivierte Klassenressourcen und Zauberleisten verwenden denselben Wert."
L["Cooldown Anchor"] = "Abklingzeitanker"
L["Cooldown Font"] = "Abklingzeitschrift"
L["Cooldown Timer Colors"] = "Farben der Abklingzeittimer"
L["Cooldown X"] = "Abklingzeit X"
L["Cooldown Y"] = "Abklingzeit Y"
L["Copy Group Settings"] = "Gruppeneinstellungen kopieren"
L["Copy Unit Settings"] = "Einheiteneinstellungen kopieren"
L["Copy target %s"] = "Kopierziel: %s"
L["Counts incoming heals from every healer, not only your own. Useful on group frames when several healers are active."] = "Berücksichtigt eingehende Heilung von allen Heilern, nicht nur die eigene. Hilfreich auf Gruppenrahmen, wenn mehrere Heiler aktiv sind."
L["Custom icon"] = "Benutzerdefiniertes Symbol"
L["Custom: %s"] = "Benutzerdefiniert: %s"
L["Cuts long spell names on every castbar to Max name length and marks the cut with '...'. Reserved space applies only while this is on."] = "Kürzt lange Zaubernamen auf allen Zauberleisten auf die maximale Namenslänge und kennzeichnet die Kürzung mit '...'. Der reservierte Anzeigebereich gilt nur, solange diese Option aktiv ist."
L["Daylight"] = "Tageslicht"
L["Decimals below sec"] = "Nachkommastellen unter (Sek.)"
L["Dispel Border, Overlay, and Symbol need each UnitFrame's Aura sensor. Enable Buffs or Debuffs on the affected UnitFrame, or turn on its Dispel feature to enable the sensor automatically. Both icon caps may stay at 0."] = "Entzauberungsrahmen, Überlagerung und Symbol benötigen die Aura-Erkennung des jeweiligen Einheitenrahmens. Dazu Buffs oder Debuffs auf dem betroffenen Rahmen aktivieren oder dessen Entzauberungsanzeige einschalten; sie aktiviert die Aura-Erkennung automatisch. Die Höchstzahl beider Symbolarten darf bei 0 bleiben."
L["Dispel Border, Overlay, and Symbol need this UnitFrame's Aura sensor. Enable Buffs or Debuffs, or turn on this Dispel feature to enable the sensor automatically. Set both icon caps to 0 if you want no aura icons."] = "Entzauberungsrahmen, Überlagerung und Symbol benötigen die Aura-Erkennung dieses Einheitenrahmens. Dazu Buffs oder Debuffs aktivieren oder diese Entzauberungsanzeige einschalten; sie aktiviert die Aura-Erkennung automatisch. Die Höchstzahl beider Symbolarten auf 0 setzen, wenn keine Aura-Symbole angezeigt werden sollen."
L["Dots on Target"] = "DoTs auf dem Ziel"
L["Draw order on the shared 0-30 layer scale. Raise it to draw the outline above text, icons or auras on a lower layer."] = "Zeichenreihenfolge auf der gemeinsamen Ebenenskala von 0 bis 30. Ein höherer Wert zeichnet die Kontur über Texten, Symbolen oder Auren auf niedrigeren Ebenen."
L["Draws absorb shields on the unit, such as Power Word: Shield, as an overlay on the health bar."] = "Zeigt Absorptionsschilde der Einheit, etwa Machtwort: Schild, als Überlagerung auf der Lebensleiste."
L["Each castbar text can override the shared castbar text color. Target text exists on Target, Focus, Boss, and Arena."] = "Jeder Zauberleistentext kann die gemeinsame Textfarbe überschreiben. Zieltext ist auf Ziel-, Fokus-, Boss- und Arenazauberleisten verfügbar."
L["Each text has three slots: left, center and right. The slot picked here is the one the value, Hide % sign and slot size settings edit."] = "Jeder Text hat drei Plätze: links, mittig und rechts. Die Einstellungen Wert, %-Zeichen ausblenden und Platzgröße gelten für den hier gewählten Platz."
L["Edge softness"] = "Kantenweichheit"
L["Effect Layer (0-30)"] = "Effektebene (0-30)"
L["Ember"] = "Glut"
L["Fill and color mode affect only the health background; foreground health coloring stays independent."] = "Füll- und Farbmodus beeinflussen nur den Hintergrund der Lebensleiste. Die Farbe des gefüllten Vordergrunds bleibt davon unabhängig."
L["Flips the fill direction on the Target castbar only, so it can mirror your Player castbar when the two frames face each other."] = "Kehrt nur die Füllrichtung der Zielzauberleiste um. So kann sie die Spielerzauberleiste spiegeln, wenn die beiden Rahmen einander gegenüberliegen."
L["Focus color is in %s."] = "Die Fokusfarbe wird unter %s eingestellt."
L["Focus interrupt tracker"] = "Unterbrechungsanzeige für den Fokus"
L["Font size of the slot picked in Text slots only. Slots you never resize keep the normal text size."] = "Schriftgröße nur für den unter Textplätze gewählten Platz. Plätze ohne eigene Größe behalten die normale Textgröße."
L["Frame Outline Color"] = "Rahmenkonturfarbe"
L["Frames %d%%"] = "Rahmen %d%%"
L["Gives this scope its own text style, colors and name shortening, so Shared changes stop reaching it. The font family always stays shared."] = "Gibt diesem Bereich einen eigenen Textstil, eigene Farben und eigene Namenskürzung. Änderungen der gemeinsamen Einstellungen gelten hier dann nicht mehr. Die Schriftfamilie bleibt immer gemeinsam."
L["Gives this unit or group its own gradient, absorb, outline and highlight settings instead of following Shared. Turning it off keeps your custom values."] = "Gibt dieser Einheit oder Gruppe eigene Einstellungen für Farbverlauf, Absorption, Kontur und Hervorhebung anstelle der gemeinsamen Einstellungen. Beim Ausschalten bleiben die eigenen Werte gespeichert."
L["Gradually brightens the bar toward white as a cast nears its end, so the last moment of a cast is easy to spot."] = "Hellt die Leiste gegen Ende des Zaubers allmählich bis Weiß auf. So ist der letzte Moment des Zaubers leichter zu erkennen."
L["Grid %s/%s"] = "Raster %s/%s"
L["Group frame provider"] = "Anbieter für Gruppenrahmen"
L["Group threat visuals show for"] = "Gruppenbedrohung anzeigen für"
L["Grow"] = "Wachstumsrichtung"
L["HP value"] = "HP-Wert"
L["Heal-Absorb / Negative Heal"] = "Heilungsabsorption / Negative Heilung"
L["Health gradient stops"] = "Stützpunkte des Lebensfarbverlaufs"
L["Hide in Housing"] = "In Spielerbehausungen ausblenden"
L["Higher numbers draw this text in front. Portrait, aura and status icon layers use the same 0-30 scale; set it above whatever covers the text."] = "Höhere Werte zeichnen diesen Text weiter vorn. Porträts, Auren und Statussymbole verwenden dieselbe Ebenenskala von 0 bis 30. Ein Wert über dem verdeckenden Element macht den Text sichtbar."
L["Highlight Priority Order"] = "Prioritätsreihenfolge der Hervorhebungen"
L["Highlights the Boss frame of the boss you are targeting. It is shared by all boss frames, so it changes only on the Shared scope."] = "Hebt den Bossrahmen des aktuell anvisierten Bosses hervor. Die Einstellung gilt gemeinsam für alle Bossrahmen und lässt sich daher nur im gemeinsamen Bereich ändern."
L["How dark the health bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Bestimmt die Dunkelheit des Schattens an der stärksten Kante der Lebensleiste. 0 zeigt keinen Schatten; 1 verwendet die volle Schattenfarbe."
L["How dark the power bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Bestimmt die Dunkelheit des Schattens an der stärksten Kante der Ressourcenleiste. 0 zeigt keinen Schatten; 1 verwendet die volle Schattenfarbe."
L["How far the bar jolts, in pixels. 0 turns the shake off even while Shake on interrupt is enabled."] = "Stärke des Rüttelns in Pixeln. 0 schaltet es aus, auch wenn „Bei Unterbrechung rütteln“ aktiv ist."
L["How long an interrupted cast stays visible with the interrupt message before the bar hides. 0 hides it immediately."] = "Bestimmt, wie lange ein unterbrochener Zauber mit der Unterbrechungsmeldung sichtbar bleibt, bevor die Leiste ausgeblendet wird. 0 blendet sie sofort aus."
L["How long the text takes to fully appear once your mouse enters the unit frame. 0 shows it instantly."] = "Dauer bis zur vollständigen Einblendung, sobald die Maus den Einheitenrahmen erreicht. 0 zeigt den Text sofort."
L["How long the text takes to fully fade away after your mouse leaves the unit frame. 0 hides it instantly."] = "Dauer bis zur vollständigen Ausblendung, nachdem die Maus den Einheitenrahmen verlassen hat. 0 blendet den Text sofort aus."
L["Hunted Foe"] = "Gejagter Feind"
L["Icon (follows castbar)"] = "Symbol (folgt der Zauberleiste)"
L["Icon Border"] = "Symbolrahmen"
L["Icon Effect"] = "Symboleffekt"
L["Icon Shadow"] = "Symbolschatten"
L["Independent from MSUF Enable; /reload required."] = "Unabhängig vom Aktivierungszustand von MSUF; /reload erforderlich."
L["Jolts a castbar sideways when the cast it shows is interrupted, so kicks are easy to notice. Applies to every castbar."] = "Lässt eine Zauberleiste bei einer Unterbrechung seitlich rütteln, damit Unterbrechungen leichter auffallen. Gilt für alle Zauberleisten."
L["Keeps this many extra pixels free next to the spell name, on top of the room kept for the cast time, so long names stay clear of the timer."] = "Hält neben dem Zaubernamen diese Anzahl zusätzlicher Pixel frei, zusätzlich zum Platz für die Zauberzeit. So überdecken lange Namen den Timer nicht."
L["Keeps this text hidden until your mouse is over the unit frame. Name, HP and power text each have their own switch."] = "Blendet diesen Text nur ein, solange die Maus über dem Einheitenrahmen liegt. Namen, Lebenswerte und Ressourcentext haben jeweils einen eigenen Schalter."
L["Large Groups"] = "Große Gruppen"
L["Lets the spark stick out above and below the bar at about twice its height. Only matters while the spark is shown."] = "Lässt den Funken ober- und unterhalb der Leiste bis etwa zur doppelten Leistenhöhe herausragen. Gilt nur bei sichtbarem Funken."
L["Lower %s"] = "%s nach unten verschieben"
L["MSUF (Forever Version)"] = "MSUF (Forever-Version)"
L["Makes channeled spells fill up like normal casts. Off keeps the classic look where a channel starts full and drains."] = "Lässt kanalisierte Zauber wie normale Zauber von leer nach voll laufen. Aus behält die klassische Anzeige bei, die voll beginnt und sich leert."
L["Manual width for the detached Player power bar. Available while Width mode is Manual; dragging it releases Sync width to Class Resource, because that sync would otherwise win. Unset, the bar inherits the Player frame width."] = "Manuelle Breite der abgetrennten Spielerressourcenleiste. Verfügbar im Breitenmodus Manuell. Beim Ziehen wird „Breite mit Klassenressource synchronisieren“ gelöst, da die Synchronisierung sonst Vorrang hätte. Ohne eigenen Wert gilt die Breite des Spielerrahmens."
L["Mapkotwo"] = "Mapkotwo"
L["Marked Add"] = "Markierter Zusatzgegner"
L["Maximum Health Loss Color"] = "Farbe bei maximalem Lebensverlust"
L["Menu appearance preset"] = "Voreingestellte Menüdarstellung"
L["Mid"] = "Mitte"
L["Mirrors the HP text: left and right slots swap sides and multi-value choices flip, so Current / Percent becomes Percent / Current."] = "Spiegelt den Lebenstext: Linker und rechter Platz tauschen die Seiten, und die Reihenfolge mehrteiliger Werte kehrt sich um. Aktuell / Prozent wird so zu Prozent / Aktuell."
L["Modifier key"] = "Modifikatortaste"
L["Moonlit Tank"] = "Tank im Mondlicht"
L["Move the group or selected slot directly in Preview."] = "Die Gruppe oder den ausgewählten Platz direkt in der Vorschau verschieben."
L["Move the name directly in Preview."] = "Den Namen direkt in der Vorschau verschieben."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width. In Automatic mode, Augmentation Evoker uses this bar for Ebon Might; an explicit Mana selection keeps it as Mana."] = "Löst die Spielerressourcenleiste aus dem Einheitenrahmen. Anker verbindet sie mit dem Klassenressourcenblock; Synchronisieren übernimmt nur dessen Breite. Im Automatikmodus zeigt sie beim Verstärkungsrufer Schwarzmacht an. Wird Mana ausdrücklich gewählt, bleibt die Anzeige bei Mana."
L["Mythic"] = "Mythisch"
L["Mythic Raid frames"] = "Mythische Schlachtzugsrahmen"
L["Non-tanks"] = "Nicht-Tanks"
L["Off (default): panels keep the Classic Glass appearance. On: panels and navigation follow your accent color. Success, warning and danger colors never change."] = "Aus (Standard): Die Bereiche behalten das Classic-Glass-Aussehen. An: Bereiche und Navigation folgen deiner Akzentfarbe. Erfolgs-, Warn- und Gefahrenfarben ändern sich nie."
L["Offline %s s"] = "Offline %s s"
L["On: aura tooltips name who applied the aura, coloured by reaction or class, through the game's own 12.1.5 option, and MSUF re-enables it after every login. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "An: Aura-Tooltips nennen, wer die Aura angewendet hat, gefärbt nach Reaktion oder Klasse, über die spieleigene 12.1.5-Option; MSUF aktiviert sie nach jeder Anmeldung erneut. Aus (Standard): MSUF berührt die Spieloption nie, sodass andere Addons oder eine manuelle Konsoleneinstellung die Kontrolle behalten; beim Ausschalten wird die Option einmal zurückgesetzt."
L["On: dragging this text in Preview moves all its slots together. Off: each visible slot gets its own handle so you can place it separately."] = "An: Ziehen dieses Textes in der Vorschau verschiebt alle seine Plätze gemeinsam. Aus: Jeder sichtbare Platz erhält einen eigenen Anfasser und lässt sich separat platzieren."
L["Open %s settings"] = "Einstellungen für %s öffnen"
L["Open Priority Frames for %s"] = "Prioritätsrahmen für %s öffnen"
L["Open Suite Modules"] = "Suite-Module öffnen"
L["Open a Frame"] = "Rahmen öffnen"
L["Open search result %s"] = "Suchergebnis %s öffnen"
L["Opens the global Aura icon appearance: shape, border, shadow, colors and native Player weapon enchants. This frame's container Style stays here."] = "Öffnet das globale Aussehen der Aura-Symbole: Form, Rahmen, Schatten, Farben und die spieleigenen Waffenverzauberungen des Spielers. Der Containerstil dieses Rahmens wird weiterhin hier eingestellt."
L["Optional modules beyond unit frames: action bars, bags, chat, minimap and more."] = "Optionale Module über Einheitenrahmen hinaus: Aktionsleisten, Taschen, Chat, Minikarte und mehr."
L["Ordering and individual Style are edited here. Global icon theme: %s."] = "Sortierung und individueller Stil werden hier bearbeitet. Globales Symboldesign: %s."
L["Orders Class Resource numeric text, Rune times and the Ebon Might duration text independently from the Class Resource bar and Player Power text."] = "Bestimmt die Zeichenebene von Klassenressourcenwerten, Runenzeiten und der Dauer von Schwarzmacht unabhängig von der Klassenressourcenleiste und dem Spielerressourcentext."
L["Orders only the normal Player Power bar. It does not control Class Resource pips or their text."] = "Bestimmt nur die Zeichenebene der normalen Spielerressourcenleiste. Klassenressourcenpunkte und deren Text bleiben unverändert."
L["Orders only the normal Player Power text. The visible Essence count and Ebon Might time belong to Class Resource text."] = "Bestimmt nur die Zeichenebene des normalen Spielerressourcentextes. Die sichtbare Essenzanzahl und die Dauer von Schwarzmacht gehören zum Klassenressourcentext."
L["Orders the Class Resource bar and pips. Its numeric, Rune and Ebon duration text uses the separate Class Resource text layer under Appearance > Text."] = "Bestimmt die Zeichenebene der Klassenressourcenleiste und ihrer Punkte. Zahlen, Runenzeiten und die Dauer von Schwarzmacht verwenden die eigene Klassenressourcen-Textebene unter Darstellung > Text."
