L["Power bars glide to new values instead of jumping; turns off Chunked power loss. Set per unit: pick a unit scope with a power bar, such as Player or Target."] = "Ressourcenleisten gleiten zu neuen Werten, statt zu springen; deaktiviert „Verzögerter Ressourcenverlust“. Gilt pro Einheit: einen Einheitenbereich mit Ressourcenleiste wählen, etwa Spieler oder Ziel."
