L["Print the client, game mode and Blizzard addon facts for a bug report."] = "Gibt Client, Spielmodus und Informationen zu Blizzard-Addons für einen Fehlerbericht im Chat aus."
L["Quick Palette"] = "Schnellpalette"
L["Raid frames"] = "Schlachtzugsrahmen"
