L["Round MSUF castbar surfaces and outlines. Blizzard castbars, spell icons, and the GCD bar are not changed."] = "Rundet die Flächen und Konturen der MSUF-Zauberleisten ab. Blizzards Zauberleisten, Zaubersymbole und die GCD-Leiste bleiben unverändert."
L["Round rectangular class resource bars. Circle, Diamond, and Hex shapes are unchanged."] = "Rundet rechteckige Klassenressourcenleisten ab. Kreis-, Rauten- und Sechseckformen bleiben unverändert."
L["Search for %s"] = "Nach %s suchen"
L["Select search result %s"] = "Suchergebnis %s auswählen"
L["Shades the end of the Player castbar by your latency or spell queue window, whichever is larger, to help time your next spell. Player castbar only."] = "Markiert am Ende der Spielerzauberleiste den größeren Wert aus Latenz und Zauberwarteschlangenfenster. Das erleichtert das rechtzeitige Auslösen des nächsten Zaubers. Gilt nur für die Spielerzauberleiste."
L["Shadow Alpha (%)"] = "Schattendeckkraft (%)"
L["Shadow Size"] = "Schattengröße"
L["Shadow distance"] = "Schattenabstand"
L["Shape, border and shadow: %s. All controls here remain Group-scope aware."] = "Form, Rahmen und Schatten: %s. Alle Einstellungen hier gelten weiterhin für den ausgewählten Gruppenbereich."
L["Sharp / Pixel"] = "Scharf / Pixel"
L["Show Duration Bar"] = "Dauerleiste anzeigen"
L["Show MSUF button in game menu"] = "MSUF-Schaltfläche im Spielmenü anzeigen"
L["Show Timer Text"] = "Timer-Text anzeigen"
L["Show Tooltip"] = "Tooltip anzeigen"
L["Show Weapon Enchants on Player"] = "Waffenverzauberungen beim Spieler anzeigen"
L["Show castbar with Focus Kick icon"] = "Zauberleiste mit Fokus-Kick-Symbol anzeigen"
L["Show caster names in aura tooltips"] = "Zauberwirker in Aura-Tooltips anzeigen"
L["Show on Arena castbars"] = "Auf Arenazauberleisten anzeigen"
L["Show on enemy nameplates (MSUF Suite)"] = "Auf feindlichen Namensplaketten anzeigen (MSUF Suite)"
L["Show preview drag hint animation"] = "Vorschau-Ziehhinweis-Animation anzeigen"
L["Show this frame only when its unit is below full health. At full health it is transparent, even in combat or with a target. Replaces the Out of combat, No target, and Out of combat and no target rules; other hide conditions still apply. Edit Mode keeps the frame visible for editing. The transparent frame can still receive mouse clicks."] = "Zeigt diesen Rahmen nur, solange die Einheit nicht bei vollem Leben ist. Bei vollem Leben bleibt er transparent, auch im Kampf oder mit einem Ziel. Ersetzt die Regeln „Außerhalb des Kampfes“, „Kein Ziel“ und „Außerhalb des Kampfes und kein Ziel“; andere Ausblendbedingungen gelten weiter. Im Bearbeitungsmodus bleibt der Rahmen sichtbar. Der transparente Rahmen kann weiterhin Mausklicks empfangen."
L["Show unitframe tooltips"] = "Einheitenrahmen-Tooltips anzeigen"
L["Shows HP percent with one decimal (for example, 63.4 instead of 63) in every HP slot that shows a percent."] = "Zeigt den Lebensprozentsatz mit einer Dezimalstelle (zum Beispiel 63,4 statt 63) in jedem Lebens-Textplatz mit Prozentanzeige."
L["Shows a shield glow at the end of the health bar while the unit is at full health and still has an absorb shield."] = "Zeigt ein Schildleuchten am Ende der Lebensleiste, solange die Einheit bei voller Gesundheit ist und noch einen Absorptionsschild hat."
L["Shows heal absorbs, effects that soak up incoming healing before health can rise, as a bar over current health."] = "Zeigt Heilungsabsorption, die eingehende Heilung aufzehrt, bevor sich die Gesundheit erhöhen kann, als Leiste über der aktuellen Gesundheit an."
L["Shows incoming heals as a bar on the health bar before they land. Only your own heals count unless Include healing from others is on."] = "Zeigt eingehende Heilung vor ihrem Eintreffen als Leiste auf der Lebensleiste an. Nur eigene Heilung zählt, solange „Heilung anderer Spieler einbeziehen“ aus ist."
L["Shows sample bars on the frames of the selected scope, even while this bar is turned off, so you can check its look. Cannot be turned on in combat."] = "Zeigt Beispielleisten auf den Rahmen des ausgewählten Bereichs, auch wenn diese Leiste ausgeschaltet ist. So lässt sich ihr Aussehen prüfen. Im Kampf nicht aktivierbar."
L["Shows the aggro color on the border when the unit has threat: your frame while you hold aggro, enemies attacking you, and group members with high threat."] = "Zeigt die Aggrofarbe am Rahmen bei Bedrohung: am eigenen Rahmen bei eigener Aggro, bei angreifenden Gegnern und bei Gruppenmitgliedern mit hoher Bedrohung."
L["Shows the percent as a bare number (63 instead of 63%) in the selected slot only. Available when that slot's value includes a percent."] = "Zeigt den Prozentsatz nur im ausgewählten Platz als Zahl ohne Prozentzeichen an (63 statt 63%). Verfügbar, wenn der Wert des Platzes einen Prozentwert umfasst."
L["Shows the remaining global cooldown in the Player castbar time text while the GCD bar runs."] = "Zeigt die verbleibende globale Abklingzeit im Zeittext der Spielerzauberleiste an, solange die GCD-Leiste läuft."
L["Slug"] = "Slug"
L["Smooth"] = "Weich"
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in %s."] = "Ein weicher Farbverlauf hebt den gesamten Rahmen bei Mouseover hervor, ohne das Porträt zu beeinträchtigen. Ein fester Rahmen erzeugt eine klare Kante. Die Farbe wird unter %s gewählt."
L["Some settings in this section differ from their defaults. Reset section restores them."] = "Einige Einstellungen dieses Abschnitts weichen von den Standardwerten ab. Abschnitt zurücksetzen stellt diese wieder her."
L["Spell ID %s"] = "Zauber-ID %s"
L["Spell Indicator Order"] = "Reihenfolge der Zaubersymbole"
L["Spell names longer than this many characters are cut and end in '...'. Names are also trimmed to fit the free bar width, so narrow bars may show fewer."] = "Zaubernamen mit mehr als dieser Anzahl Zeichen werden gekürzt und enden mit '...'. Sie werden außerdem an die freie Leistenbreite angepasst. Schmale Leisten können daher weniger Zeichen anzeigen."
L["Spent power drops at once while the spent part briefly stays highlighted, then fades; turns off Smooth power bar. Set per unit, like Smooth power bar."] = "Der Ressourcenwert sinkt sofort; der verbrauchte Anteil bleibt kurz hervorgehoben und verblasst dann. Deaktiviert „Weiche Ressourcenleiste“ und wird wie diese pro Einheit eingestellt."
L["Stack Font"] = "Schriftart der Stapelanzeige"
L["Stack X"] = "Stapelanzahl X"
L["Stack Y"] = "Stapelanzahl Y"
L["Suite Action Bars"] = "Suite-Aktionsleisten"
L["Suite Cooldown Manager"] = "Suite-Abklingzeitverwaltung"
L["Suite Damage Meter"] = "Suite-Schadensanzeige"
L["Suite Quality of Life"] = "Suite-Komfortfunktionen"
L["Suite setup unavailable"] = "Suite-Setup nicht verfügbar"
L["Symbol anchor"] = "Symbolanker"
L["Symbol opacity"] = "Symboldeckkraft"
L["Symbol placed between values that share one slot, like Current and Percent. Used by all slots of this text."] = "Trennzeichen zwischen Werten desselben Platzes, etwa Aktuell und Prozent. Gilt für alle Plätze dieses Textes."
L["Symbol set"] = "Symbolsatz"
L["Symbol size"] = "Symbolgröße"
L["Symbol spacing"] = "Symbolabstand"
L["Symbol strata"] = "Symbolebene"
L["Text Layers"] = "Textebenen"
L["Text opacity"] = "Textdeckkraft"
L["Texture comes from Bars; preview uses Player background opacity multiplied by tint opacity."] = "Die Textur kommt aus Balken. Die Vorschau multipliziert die Hintergrunddeckkraft des Spielerrahmens mit der Deckkraft der Tönung."
L["The typeface for all unit and group frame text; every scope shares it. Fonts other addons register through SharedMedia also appear here."] = "Schriftart für alle Texte auf Einheiten- und Gruppenrahmen. Sie gilt gemeinsam für alle Bereiche. Schriftarten, die andere Addons über SharedMedia registrieren, werden ebenfalls angezeigt."
L["Timer Anchor"] = "Anker des Zeittexts"
L["Timer Thresholds"] = "Zeitschwellen"
L["Timer X"] = "Zeittext X"
L["Timer Y"] = "Zeittext Y"
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in %s, scoped by Aura type."] = "Timer- und Entzauberungsfarben gelten gemeinsam für Auren auf Einheiten- und Gruppenrahmen sowie für alle Vorschauen. Farben für Symbolrahmen und Schatten werden unter %s nach Aura-Typ eingestellt."
L["Toggle Spell Indicator"] = "Zaubersymbol umschalten"
L["Tracked spell %s"] = "Erfasster Zauber: %s"
L["Tracked spell tile %d"] = "Feld %d für erfasste Zauber"
L["Turns every HP text slot on this frame on or off. The health bar is not affected, and your slot setup is kept."] = "Schaltet alle Lebens-Textplätze dieses Rahmens ein oder aus. Die Lebensleiste bleibt unverändert, und die Platzeinstellungen bleiben gespeichert."
L["Turns every power text slot on this frame on or off. The power bar is not affected, and your slot setup is kept."] = "Schaltet alle Ressourcen-Textplätze dieses Rahmens ein oder aus. Die Ressourcenleiste bleibt unverändert, und die Platzeinstellungen bleiben gespeichert."
L["Turns off custom font settings on every unit and group scope at once, so they all follow Shared again."] = "Deaktiviert eigene Schrifteinstellungen gleichzeitig in allen Einheiten- und Gruppenbereichen. Sie übernehmen danach wieder die gemeinsamen Einstellungen."
L["Turns off custom settings on every unit and group scope at once, so all frames follow Shared again. Their custom values stay saved."] = "Deaktiviert eigene Einstellungen gleichzeitig in allen Einheiten- und Gruppenbereichen. Alle Rahmen übernehmen danach wieder die gemeinsamen Einstellungen. Die eigenen Werte bleiben gespeichert."
L["Turns this frame's name text on or off. Its anchor, size and color stay saved while it is off."] = "Schaltet den Namenstext dieses Rahmens ein oder aus. Verankerung, Größe und Farbe bleiben im ausgeschalteten Zustand gespeichert."
L["Unavailable fill color"] = "Füllfarbe: Kick nicht bereit"
L["Updates the Player power text on every power tick instead of the regular update rate. Only the Player frame uses it; set it on the Shared scope."] = "Aktualisiert den Spielerressourcentext bei jedem Ressourcentick statt im normalen Aktualisierungsintervall. Gilt nur für den Spielerrahmen und wird im gemeinsamen Bereich eingestellt."
L["Use MapkoSkin for MSUF menus"] = "MapkoSkin für MSUF-Menüs verwenden"
L["Use NSRT nicknames on MSUF frames"] = "NSRT-Spitznamen auf MSUF-Rahmen verwenden"
L["Use bar background texture"] = "Leistenhintergrundtextur verwenden"
L["Use bar texture"] = "Leistentextur verwenden"
L["Violet"] = "Violett"
L["Voidcaller"] = "Leerenrufer"
L["What the selected slot shows. None leaves the slot empty; choices with several values are joined by the Delimiter."] = "Bestimmt den Inhalt des ausgewählten Platzes. Keine lässt den Platz leer; mehrere Werte werden durch das Trennzeichen verbunden."
L["When anchored here, Player power settings are managed by Class Resources. In Automatic mode, Augmentation Evoker shows Ebon Might on this bar."] = "Bei dieser Verankerung werden die Einstellungen der Spielerressource unter Klassenressourcen verwaltet. Im Automatikmodus zeigt die Leiste beim Verstärkungsrufer Schwarzmacht an."
L["When several highlight borders show at once, the highest one in the list wins. Turn this on to reorder the list by dragging."] = "Wenn mehrere Hervorhebungsrahmen gleichzeitig aktiv sind, gilt der oberste in der Liste. Mit dieser Option lässt sich die Reihenfolge durch Ziehen ändern."
L["Where the name is pinned on the frame and how it aligns. Dragging it in Preview offsets it from this point."] = "Bestimmt die Verankerung und Ausrichtung des Namens am Rahmen. Ziehen in der Vorschau verschiebt ihn relativ zu diesem Punkt."
L["Which way the bar grows during a cast, on every castbar. Channels drain the other way unless Always use fill direction for all casts is on."] = "Wachstumsrichtung aller Zauberleisten während des Zaubers. Kanalisierte Zauber leeren die Leiste in der Gegenrichtung, solange „Füllrichtung immer für alle Zauber nutzen“ aus ist."
L["Width in pixels of the normal frame outline; 0 hides it. Aggro, dispel and other highlight borders use their own thickness."] = "Breite der normalen Rahmenkontur in Pixeln. 0 blendet sie aus. Aggro-, Entzauberungs- und andere Hervorhebungsrahmen verwenden ihre eigene Stärke."
L["Width of the border around each castbar, in pixels; 0 removes it. The Interrupt Ready border style colors this border, so keep it above 0 for that style."] = "Rahmenbreite aller Zauberleisten in Pixeln. 0 entfernt den Rahmen. Der Rahmenstil „Kick bereit“ färbt diesen Rahmen und braucht daher einen Wert über 0."
L["Window %d"] = "Fenster %d"
L["Writes the instant spell's name on the GCD bar and shows its icon. Off leaves the spell text blank."] = "Zeigt den Namen und das Symbol des Sofortzaubers auf der GCD-Leiste an. Aus lässt den Zaubertext leer."
L["not installed"] = "nicht installiert"
L["only the global %s icon shape, border and shadow settings, plus the shared Blizzard Buff/Debuff visibility settings; other Aura types and all Unit/Group lane settings stay unchanged"] = "nur die globalen Einstellungen für Symbolform, Rahmen und Schatten von %s sowie die gemeinsamen Sichtbarkeitseinstellungen für Blizzards Buffs und Debuffs; andere Aura-Typen und alle Einstellungen der Einheiten- und Gruppenspuren bleiben unverändert"
L["only the global %s icon shape, border and shadow settings; other Aura types and all Unit/Group lane settings stay unchanged"] = "nur die globalen Einstellungen für Symbolform, Rahmen und Schatten von %s; andere Aura-Typen und alle Einstellungen der Einheiten- und Gruppenspuren bleiben unverändert"
